const float vx_offset = 0.5;

vec4 spline(float x, vec4 c1, vec4 c2, vec4 c3, vec4 c4, vec4 c5, vec4 c6, vec4 c7, vec4 c8, vec4 c9)
{
	float w1, w2, w3, w4, w5, w6, w7, w8, w9;
	w1 = 0.0;
	w2 = 0.0;
	w3 = 0.0;
	w4 = 0.0;
	w5 = 0.0;
	w6 = 0.0;
	w7 = 0.0;
	w8 = 0.0;
	w9 = 0.0;
	float tmp = x * 8.0;
	if (tmp<=1.0) {
		w1 = 1.0 - tmp;
		w2 = tmp;
	}
	else if (tmp<=2.0) {
		tmp = tmp - 1.0;
		w2 = 1.0 - tmp;
		w3 = tmp;
	}
	else if (tmp<=3.0) {
		tmp = tmp - 2.0;
		w3 = 1.0-tmp;
		w4 = tmp;
	}
	else if (tmp<=4.0) {
		tmp = tmp - 3.0;
		w4 = 1.0-tmp;
		w5 = tmp;
	}
	else if (tmp<=5.0) {
		tmp = tmp - 4.0;
		w5 = 1.0-tmp;
		w6 = tmp;
	}
	else if (tmp<=6.0) {
		tmp = tmp - 5.0;
		w6 = 1.0-tmp;
		w7 = tmp;
	}
	else if (tmp<=7.0) {
		tmp = tmp - 6.0;
		w7 = 1.0 - tmp;
		w8 = tmp;
	}
	else {
		//tmp = saturate(tmp - 7.0);
		// http://www.ozone3d.net/blogs/lab/20080709/saturate-function-in-glsl/
		tmp = clamp(tmp - 7.0, 0.0, 1.0);
		w8 = 1.0-tmp;
		w9 = tmp;
	}
	return w1*c1 + w2*c2 + w3*c3 + w4*c4 + w5*c5 + w6*c6 + w7*c7 + w8*c8 + w9*c9;
}

