		}

		pt = rotatePointNorm(pt,preRotateAngle);
		returnMe = IMG_NORM_PIXEL(inputImage,pt);

		if (repeatStyle > 0)	{
			if (repeatStyle == 1)
				returnMe.a *= (val > 1.0) ? 1.0 - repeatDecay * (val) : 1.0;
			else	{
				float repCount = 1.0 / (1.0+resultSize);
				returnMe.a *= 1.0 - repeatDecay * floor(val) / repCount;
			}
		}
	}

