const vec4 redfilter1 		= vec4(1.0, 0.0, 0.0, 1.0);
const vec4 bluegreenfilter1 	= vec4(0.0, 1.0, 0.7, 1.0);

const vec4 redfilter2 		= vec4(1.0, 0.0, 0.0, 0.0);
const vec4 bluegreenfilter2 	= vec4(0.0, 1.0, 1.0, 0.0);

const vec4 cyanfilter		= vec4(0.0, 1.0, 0.5, 0.0);
const vec4 magentafilter	= vec4(1.0, 0.0, 0.25, 0.0);



void main (void) 
{
	vec4 input0 = IMG_THIS_PIXEL(inputImage);
	vec4 result;

	if (style == 0)	{
		vec4 redrecord = input0 * redfilter1;
		vec4 bluegreenrecord = input0 * bluegreenfilter1;
		vec4 rednegative = vec4(redrecord.r);
		vec4 bluegreennegative = vec4((bluegreenrecord.g + bluegreenrecord.b)/2.0);

		vec4 redoutput = rednegative * redfilter1;
		vec4 bluegreenoutput = bluegreennegative * bluegreenfilter1;

		// additive 'projection"
		result = redoutput + bluegreenoutput;

		result = mix(input0, result, amount);
		result.a = input0.a;
	}
	else if (style == 1)	{
		vec4 redrecord = input0 * redfilter2;
		vec4 bluegreenrecord = input0 * bluegreenfilter2;

		vec4 rednegative = vec4(redrecord.r);
		vec4 bluegreennegative = vec4((bluegreenrecord.g + bluegreenrecord.b)/2.0);

		vec4 redoutput = rednegative + cyanfilter;
		vec4 bluegreenoutput = bluegreennegative + magentafilter;

		result = redoutput * bluegreenoutput;

		result = mix(input0, result, amount);
		result.a = input0.a;	
	}
	else if (style == 2)	{
		vec3 redmatte = vec3(input0.r - ((input0.g + input0.b)/2.0));
		vec3 greenmatte = vec3(input0.g - ((input0.r + input0.b)/2.0));
		vec3 bluematte = vec3(input0.b - ((input0.r + input0.g)/2.0));

		redmatte = 1.0 - redmatte;
		greenmatte = 1.0 - greenmatte;
		bluematte = 1.0 - bluematte;

		vec3 red =  greenmatte * bluematte * input0.r;
		vec3 green = redmatte * bluematte * input0.g;
		vec3 blue = redmatte * greenmatte * input0.b;

		result = vec4(red.r, green.g, blue.b, input0.a);

		result = mix(input0, result, amount);
		result.a = input0.a;	
	}
	gl_FragColor = result;		
}

//	Based on v002 vignette – https://github.com/v002/v002-Film-Effects/



// create a black and white oval about the center of our image for our vignette
vec4 vignetteFucntion(vec2 normalizedTexcoord, float vignetteedge, float vignetteMix)
{
	normalizedTexcoord = 2.0 * normalizedTexcoord - 1.0; // - 1.0 to 1.0
	float r = length(normalizedTexcoord);
	vec4 vignette = (vec4(smoothstep(0.0, 1.0, pow(clamp(r - vignetteMix, 0.0, 1.0), 1.0 + vignetteedge * 10.0))));
	return clamp(1.0 - vignette, 0.0, 1.0);
}



void main (void) 
{ 		
	vec2 normcoord = vec2(isf_FragNormCoord[0],isf_FragNormCoord[1]);


	// make a vignette around our borders.
	vec4 vignetteResult = vignetteFucntion(normcoord, vignetteEdge, vignetteMix);

	// sharpen via unsharp mask (subtract image from blured image)
	vec4 input0 = IMG_THIS_PIXEL(inputImage);

	gl_FragColor = mix(input0,vignetteResult * input0, vignette);		
}

void main (void) 
{ 
	vec2 t1, t2;
	vec2 ctr = RENDERSIZE / 2.0;

	t1 = gl_FragCoord.xy;

	float a = -0.0;
	float b = -.1 * Amount;
	float c = -.0;
	float d = 1.0  - 1.1 * ( a + b + c );
	float r1, r2;
	float unit = length(ctr) / 2.0;

	r1 = distance( t1, ctr )/unit;
	r2 =  r1 *( r1*( r1 * (a*r1 + b) + c) + d );
	float sc = step( 0.0 , r1) * ( r1/(r2 + .000001)) + (1.0 - step( 0.0 , r1));

	t2  = ctr + ( t1 - ctr) * sc;

	gl_FragColor = IMG_PIXEL(inputImage, t2);

	if ((t2.x < 0.0)
		||(t2.y < 0.0)
		||(t2.x > RENDERSIZE.x)
		||(t2.y > RENDERSIZE.y)) 
	{
		gl_FragColor = vec4(0.0);
	}
}

precision mediump float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_timeScale;
uniform float u_ampDecay;
uniform vec2 u_mouse;

vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289v2(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x * 34.0) + 1.0) * x); }

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187, 0.366025403784439,
                     -0.577350269189626, 0.024390243902439);
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);
  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod289v2(i);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float fbm(vec2 p, float t) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * snoise(p * freq + t * 0.3);
    freq *= 2.1;
    amp *= u_ampDecay;
    p += vec2(1.7, 9.2);
  }
  return val;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  vec2 p = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);

  float t = u_time * u_timeScale;

  if (u_mouse.x > 0.0) {
    vec2 mNorm = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    vec2 diff = p - mNorm;
    float dist = length(diff);
    float swirl = exp(-dist * dist * 8.0) * 0.4;
    float angle = swirl * 6.0;
    float ca = cos(angle), sa = sin(angle);
    p = mNorm + mat2(ca, -sa, sa, ca) * diff;
  }

  vec2 q = vec2(fbm(p + vec2(0.0, 0.0), t),
               fbm(p + vec2(5.2, 1.3), t));

  vec2 r = vec2(fbm(p + 4.0 * q + vec2(1.7, 9.2), t * 1.2),
               fbm(p + 4.0 * q + vec2(8.3, 2.8), t * 1.2));

  float f = fbm(p + 3.5 * r, t * 0.8);

  vec3 col = mix(vec3(0.075, 0.065, 0.055), vec3(0.20, 0.14, 0.07), clamp(f * f * 2.0, 0.0, 1.0));
  col = mix(col, vec3(0.78, 0.58, 0.24), clamp(length(q) * 0.5, 0.0, 1.0));
  col = mix(col, vec3(0.95, 0.75, 0.35), clamp(length(r.x) * 0.6, 0.0, 1.0));

  float highlight = smoothstep(0.5, 1.2, f * f * 3.0 + length(r) * 0.5);
  col += vec3(0.18, 0.12, 0.04) * highlight;

  col = pow(col, vec3(1.1));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_crackSpeed;
uniform float u_lightBleed;
uniform vec2 u_mouse;

// Hash functions for procedural Voronoi
vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)),
           dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453123);
}

float hash1(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Voronoi with distance to nearest edge
// Returns: x = dist to nearest center, y = dist to nearest edge, z = cell id
vec3 voronoi(vec2 p, float t) {
  vec2 n = floor(p);
  vec2 f = fract(p);

  // First pass: find nearest cell center
  float minDist = 8.0;
  vec2 nearestCell = vec2(0.0);
  vec2 nearestPoint = vec2(0.0);

  // 3x3 neighbor search — unrolled to avoid non-constant indexing
  vec2 g;
  vec2 o;
  vec2 diff;
  float d;

  g = vec2(-1.0, -1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }
  g = vec2(0.0, -1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }
  g = vec2(1.0, -1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }

  g = vec2(-1.0, 0.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }
  g = vec2(0.0, 0.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }
  g = vec2(1.0, 0.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }

  g = vec2(-1.0, 1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }
  g = vec2(0.0, 1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }
  g = vec2(1.0, 1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearestCell = n + g; nearestPoint = diff; }

  // Second pass: find distance to nearest edge
  float minEdge = 8.0;

  g = vec2(-1.0, -1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }
  g = vec2(0.0, -1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }
  g = vec2(1.0, -1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }

  g = vec2(-1.0, 0.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }
  g = vec2(0.0, 0.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }
  g = vec2(1.0, 0.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }

  g = vec2(-1.0, 1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }
  g = vec2(0.0, 1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }
  g = vec2(1.0, 1.0); o = hash2(n + g) * 0.5 + 0.25; o = 0.5 + 0.4 * sin(t * 0.3 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearestPoint, diff - nearestPoint) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearestPoint + diff), normalize(diff - nearestPoint))); }

  float cellId = hash1(nearestCell);
  return vec3(sqrt(minDist), minEdge, cellId);
}

// Simpler Voronoi for micro fractures (just edge distance)
float voronoiEdge(vec2 p, float t) {
  vec2 n = floor(p);
  vec2 f = fract(p);
  float minDist = 8.0;
  vec2 nearPt = vec2(0.0);
  vec2 g; vec2 o; vec2 diff; float d;

  g = vec2(-1.0, -1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(0.0, -1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(1.0, -1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(-1.0, 0.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(0.0, 0.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(1.0, 0.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(-1.0, 1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(0.0, 1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }
  g = vec2(1.0, 1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f; d = dot(diff, diff);
  if (d < minDist) { minDist = d; nearPt = diff; }

  float minEdge = 8.0;
  g = vec2(-1.0, -1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(0.0, -1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(1.0, -1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(-1.0, 0.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(0.0, 0.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(1.0, 0.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(-1.0, 1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(0.0, 1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }
  g = vec2(1.0, 1.0); o = hash2(n + g); o = 0.5 + 0.35 * sin(t * 0.5 + 6.2831 * o); diff = g + o - f;
  if (dot(diff - nearPt, diff - nearPt) > 0.001) { minEdge = min(minEdge, dot(0.5 * (nearPt + diff), normalize(diff - nearPt))); }

  return minEdge;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  vec2 mouseOffset = vec2(0.0);
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res;
    mouseOffset = -(mUV - 0.5) * 0.15;
  }
  vec2 p = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);

  float t = u_time * u_crackSpeed;

  // Subtle heat shimmer distortion
  vec2 shimmer = vec2(
    sin(p.y * 12.0 + t * 2.3) * 0.003,
    cos(p.x * 10.0 + t * 1.7) * 0.003
  );
  p += shimmer;

  // Macro Voronoi fractures — foreground layer, stronger parallax
  vec2 macroUV = (p + mouseOffset * 1.0) * 3.5 + 0.5;
  vec3 macro = voronoi(macroUV, t);
  float macroCenterDist = macro.x;
  float macroEdge = macro.y;
  float cellId = macro.z;

  // Micro fractures — background layer, subtler parallax (inverted for depth)
  float microEdge = voronoiEdge((p + mouseOffset * 2.5) * 9.0 + vec2(3.7, 1.2), t * 0.7);

  // Time-varying crack widths
  float crackPulse = 0.5 + 0.3 * sin(t * 1.5) + 0.2 * sin(t * 2.7 + 1.0);
  float macroCrackWidth = 0.04 * crackPulse;
  float microCrackWidth = 0.025 * crackPulse;

  // Crack intensity (how close to a crack edge)
  float macroCrack = 1.0 - smoothstep(0.0, macroCrackWidth, macroEdge);
  float microCrack = 1.0 - smoothstep(0.0, microCrackWidth, microEdge);

  // Combined crack pattern — macro dominates, micro adds detail
  float crack = macroCrack + microCrack * 0.4;
  crack = clamp(crack, 0.0, 1.0);

  // Fresnel-like glow at crack edges (wider glow around cracks)
  float macroGlow = 1.0 - smoothstep(0.0, macroCrackWidth * 4.0, macroEdge);
  float microGlow = 1.0 - smoothstep(0.0, microCrackWidth * 3.0, microEdge);
  float glow = macroGlow * 0.7 + microGlow * 0.3;

  // Per-cell glass color variation (thickness differences)
  float cellThickness = 0.6 + 0.4 * cellId;
  float cellHueShift = cellId * 0.3;

  // Base amber/caramel glass color
  vec3 amber = vec3(0.78, 0.585, 0.424);      // #c8956c
  vec3 caramel = vec3(0.831, 0.647, 0.455);    // #d4a574
  vec3 deepAmber = vec3(0.29, 0.125, 0.0);     // #4a2000

  // Glass surface — varies per cell
  vec3 glassColor = mix(amber, caramel, cellHueShift);
  glassColor = mix(deepAmber, glassColor, cellThickness);

  // Subtle center-to-edge gradient within each cell (thinner at edges)
  float cellGrad = smoothstep(0.0, 0.5, macroCenterDist);
  glassColor = mix(glassColor * 1.1, glassColor * 0.85, cellGrad);

  // Pink/rose gold refraction tint near cracks
  vec3 roseGold = vec3(0.9, 0.65, 0.6);
  float refractTint = glow * (0.3 + 0.2 * sin(cellId * 12.0 + t * 0.8));
  glassColor = mix(glassColor, roseGold, refractTint * 0.25);

  // Light bleeding through cracks
  vec3 crackLight = vec3(1.0, 0.91, 0.75);     // #ffe8c0
  vec3 crackBright = vec3(1.0, 0.96, 0.9);     // #fff5e6
  vec3 lightColor = mix(crackLight, crackBright, crack);

  // Apply crack lighting with light bleed control
  float lightIntensity = crack * u_lightBleed;
  float glowIntensity = glow * u_lightBleed * 0.5;

  // Combine glass surface with crack light
  vec3 col = glassColor;

  // Soft glow around cracks (the light bleed)
  col = mix(col, lightColor * 0.8, glowIntensity);

  // Bright crack lines themselves
  col = mix(col, lightColor, lightIntensity);

  // Add subtle inner glow / subsurface scattering feel
  float sss = 0.5 + 0.5 * sin(p.x * 3.0 + t * 0.5) * sin(p.y * 2.5 + t * 0.3);
  col += vec3(0.05, 0.03, 0.01) * sss * cellThickness;

  // Vignette
  float vig = 1.0 - dot(p * 0.8, p * 0.8);
  vig = smoothstep(0.0, 1.0, vig);
  col *= 0.6 + 0.4 * vig;

  // Tone mapping — keep it warm
  col = pow(col, vec3(0.95));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_modeSpeed;
uniform float u_complexity;
uniform vec2 u_mouse;

float hash(vec2 p){
  vec3 p3=fract(vec3(p.xyx)*vec3(.1031,.1030,.0973));
  p3+=dot(p3,p3.yzx+33.33);
  return fract((p3.x+p3.y)*p3.z);
}

float chladni(vec2 p, float n, float m){
  float pi=3.14159265;
  return cos(n*pi*p.x)*cos(m*pi*p.y) - cos(m*pi*p.x)*cos(n*pi*p.y);
}

// Get mode pair using time — no arrays needed
vec2 getMode(float idx){
  // 6 beautiful Chladni mode pairs
  if(idx<1.0) return vec2(1.0,2.0);
  if(idx<2.0) return vec2(2.0,3.0);
  if(idx<3.0) return vec2(3.0,5.0);
  if(idx<4.0) return vec2(1.0,4.0);
  if(idx<5.0) return vec2(2.0,5.0);
  return vec2(3.0,4.0);
}

void main(){
  vec2 uv=(gl_FragCoord.xy-u_res*0.5)/min(u_res.x,u_res.y);
  float t=u_time*u_modeSpeed;

  vec2 p=uv*2.0;

  // Mouse-driven node shift
  if (u_mouse.x > 0.0) {
    vec2 mouseNorm = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    p += mouseNorm * 1.5;
  }

  // Circular plate
  float plateDist=length(uv);
  float plateMask=smoothstep(0.52,0.47,plateDist);

  // Cycle through modes
  float modeTime=t*0.15;
  float modeIdx=mod(modeTime,6.0);
  float idx0=floor(modeIdx);
  float idx1=mod(idx0+1.0,6.0);
  float blend=fract(modeIdx);
  blend=blend*blend*(3.0-2.0*blend);

  vec2 mode0=getMode(idx0);
  vec2 mode1=getMode(idx1);

  float cScale=u_complexity/5.0;

  float c0=chladni(p,mode0.x*cScale,mode0.y*cScale);
  float c1=chladni(p,mode1.x*cScale,mode1.y*cScale);
  float c=mix(c0,c1,blend);

  // Secondary pattern for richness
  float cb0=chladni(p+0.03,mode0.x*cScale+0.5,mode0.y*cScale+0.5);
  float cb1=chladni(p+0.03,mode1.x*cScale+0.5,mode1.y*cScale+0.5);
  float cb=mix(cb0,cb1,blend);

  // Sand on nodal lines — use smoothstep for wide, visible lines
  float w=0.3+0.1*sin(t*0.5);
  float sand=1.0-smoothstep(0.0,w,abs(c));
  float sand2=(1.0-smoothstep(0.0,w*1.3,abs(cb)))*0.35;
  sand=max(sand,sand2);
  sand=pow(sand,0.6);

  // Grain texture
  float grain=hash(gl_FragCoord.xy+fract(t*0.1)*100.0);
  float grainMask=smoothstep(0.1,0.4,sand);
  sand*=0.8+0.2*grain*grainMask;

  // Color
  vec3 plate=vec3(0.03,0.025,0.02);
  vec3 sandCol=mix(vec3(0.65,0.45,0.22),vec3(0.95,0.78,0.40),sand);

  // Bloom
  float bloom=1.0-smoothstep(0.0,w*2.5,abs(c));

  vec3 col=mix(plate,sandCol,sand);
  col+=vec3(0.25,0.17,0.07)*bloom*0.4;

  // Plate reflection
  float reflAngle=atan(uv.y,uv.x)+t*0.05;
  float refl=0.02*(0.5+0.5*sin(reflAngle*3.0))*smoothstep(0.55,0.2,plateDist);
  col+=vec3(0.12,0.10,0.06)*refl*(1.0-sand);

  // Edge glow
  float edge=smoothstep(0.5,0.43,plateDist)*smoothstep(0.38,0.46,plateDist);
  col+=vec3(0.10,0.07,0.03)*edge;

  col*=plateMask;
  col+=vec3(0.008,0.006,0.004)*(1.0-plateMask);

  // Vignette
  float vig=1.0-smoothstep(0.3,0.85,plateDist);
  col*=0.75+0.25*vig;

  // Grain
  col+=(hash(gl_FragCoord.xy+t*73.0)-0.5)*0.012;
  col=pow(max(col,0.0),vec3(0.95));

  gl_FragColor=vec4(clamp(col,0.0,1.0),1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_flashRate;
uniform float u_glowIntensity;
uniform vec2 u_mouse;

#define PI 3.141592653589793
#define TAU 6.283185307179586
#define MAX_SHAPES 8

// ── ACES tone mapping ──
vec3 ACESFilm(vec3 x) {
  float a = 2.51;
  float b = 0.03;
  float c = 2.43;
  float d = 0.59;
  float e = 0.14;
  return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

// ── Hash ──
float hash(float n) {
  return fract(sin(n) * 43758.5453123);
}

vec2 hash2(float n) {
  return vec2(hash(n), hash(n + 7.31));
}

// ── Value noise for background texture ──
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float n = i.x + i.y * 57.0;
  return mix(mix(hash(n), hash(n + 1.0), f.x),
             mix(hash(n + 57.0), hash(n + 58.0), f.x), f.y);
}

// ── 2D rotation ──
mat2 rot2(float a) {
  float c = cos(a); float s = sin(a);
  return mat2(c, -s, s, c);
}

// ── SDF primitives ──

// Equilateral triangle SDF
float sdTriangle(vec2 p, float r) {
  float k = sqrt(3.0);
  p.x = abs(p.x) - r;
  p.y = p.y + r / k;
  if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
  p.x -= clamp(p.x, -2.0 * r, 0.0);
  return -length(p) * sign(p.y);
}

// Box SDF (parallelogram via skewed coordinates)
float sdBox(vec2 p, vec2 b) {
  vec2 d = abs(p) - b;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// Parallelogram SDF
float sdParallelogram(vec2 p, float wi, float he, float sk) {
  vec2 e = vec2(sk, he);
  p = (p.y < 0.0) ? -p : p;
  vec2 w = p - e;
  w.x -= clamp(w.x, -wi, wi);
  vec2 d = vec2(dot(w, w), -w.y);
  float s = p.x * e.y - p.y * e.x;
  p = (s < 0.0) ? -p : p;
  vec2 v = p - vec2(wi, 0);
  v -= e * clamp(dot(v, e) / dot(e, e), -1.0, 1.0);
  d = min(d, vec2(dot(v, v), wi * he - abs(s)));
  return sqrt(d.x) * sign(-d.y);
}

// Rhombus / diamond SDF
float sdRhombus(vec2 p, vec2 b) {
  vec2 q = abs(p);
  float h = clamp((-2.0 * dot(q, b) + dot(b, b)) / dot(b, b), -1.0, 1.0);
  float d = length(q - 0.5 * b * vec2(1.0 - h, 1.0 + h));
  return d * sign(q.x * b.y + q.y * b.x - b.x * b.y);
}

// Hexagon SDF
float sdHexagon(vec2 p, float r) {
  vec2 q = abs(p);
  float d = dot(q, normalize(vec2(1.0, 1.732)));
  return max(d, q.y) - r;
}

// Trapezoid SDF
float sdTrapezoid(vec2 p, float r1, float r2, float he) {
  vec2 k1 = vec2(r2, he);
  vec2 k2 = vec2(r2 - r1, 2.0 * he);
  p.x = abs(p.x);
  vec2 ca = vec2(max(0.0, p.x - ((p.y < 0.0) ? r1 : r2)), abs(p.y) - he);
  vec2 cb = p - k1 + k2 * clamp(dot(k1 - p, k2) / dot(k2, k2), 0.0, 1.0);
  float s = (cb.x < 0.0 && ca.y < 0.0) ? -1.0 : 1.0;
  return s * sqrt(min(dot(ca, ca), dot(cb, cb)));
}

// ── Shape evaluation ──
// Returns SDF for shape type 0-4
float evalShape(vec2 p, int type, float scale) {
  float d = 1e5;
  if (type == 0) {
    // Equilateral triangle
    d = sdTriangle(p, scale * 0.36);
  } else if (type == 1) {
    // Wide parallelogram
    d = sdParallelogram(p, scale * 0.38, scale * 0.14, scale * 0.15);
  } else if (type == 2) {
    // Elongated diamond
    d = sdRhombus(p, vec2(scale * 0.12, scale * 0.40));
  } else if (type == 3) {
    // Hexagon segment
    d = sdHexagon(p, scale * 0.25);
  } else if (type == 4) {
    // Trapezoid
    d = sdTrapezoid(p, scale * 0.15, scale * 0.35, scale * 0.18);
  }
  return d;
}

// ── Color decay sequence ──
// Maps a decay phase (0=born, 1=gone) to color
vec3 decayColor(float phase) {
  // 0.0-0.05: white flash
  // 0.05-0.25: cyan
  // 0.25-0.50: electric blue
  // 0.50-0.75: magenta
  // 0.75-1.0: deep purple → gone
  vec3 white    = vec3(1.0, 1.0, 1.0);
  vec3 cyan     = vec3(0.0, 0.95, 1.0);
  vec3 blue     = vec3(0.15, 0.4, 1.0);
  vec3 magenta  = vec3(0.95, 0.1, 0.85);
  vec3 purple   = vec3(0.35, 0.05, 0.55);
  vec3 dark     = vec3(0.05, 0.01, 0.1);

  vec3 col = dark;
  if (phase < 0.05) {
    col = mix(white, white, phase / 0.05);
  } else if (phase < 0.20) {
    col = mix(white, cyan, (phase - 0.05) / 0.15);
  } else if (phase < 0.40) {
    col = mix(cyan, blue, (phase - 0.20) / 0.20);
  } else if (phase < 0.65) {
    col = mix(blue, magenta, (phase - 0.40) / 0.25);
  } else if (phase < 0.85) {
    col = mix(magenta, purple, (phase - 0.65) / 0.20);
  } else {
    col = mix(purple, dark, (phase - 0.85) / 0.15);
  }
  return col;
}

// ── Per-shape parameters from hash ──
struct ShapeData {
  vec2 center;
  float rotation;
  float scale;
  int type;
  float birthTime;
};

ShapeData getShape(int idx, float flashInterval) {
  ShapeData s;

  float fi = float(idx);

  // Musical timing: strong beat (even idx), weak beat (odd idx)
  bool isStrong = (mod(fi, 2.0) < 0.5);

  // Hash-based position, rotation, type — changes each cycle
  float cycleLen = float(MAX_SHAPES) * flashInterval;
  float cycle = floor(u_time / cycleLen);
  float seed = fi * 13.37 + cycle * 97.31;

  // Timing jitter: +/-10% humanization on interval
  float jitter = (hash(seed + 10.0) - 0.5) * 0.2 * flashInterval;
  s.birthTime = fi * flashInterval + jitter;

  // Position: spread across screen with some randomness
  vec2 basePos = hash2(seed + 1.0) * 2.0 - 1.0;
  s.center = basePos * vec2(0.65, 0.50);

  // Rotation: dramatic angles — quantized to bold increments + randomness
  float baseAngle = floor(hash(seed + 2.0) * 8.0) * (PI / 4.0);
  float angleJitter = (hash(seed + 5.0) - 0.5) * (PI / 6.0);
  s.rotation = baseAngle + angleJitter;

  // Scale: wide variety, strong beats are bigger
  float baseScale = 0.4 + hash(seed + 3.0) * 1.2;
  s.scale = isStrong ? baseScale * 1.3 : baseScale * 0.7;

  // Shape type
  s.type = int(mod(hash(seed + 4.0) * 5.0, 5.0));

  return s;
}

void main() {
  vec2 fragCoord = gl_FragCoord.xy;
  vec2 uv = fragCoord / u_res;
  float aspect = u_res.x / u_res.y;

  // Aspect-corrected centered coordinates
  vec2 mouseShift = vec2(0.0);
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res;
    mouseShift = -(mUV - 0.5) * 0.15;
  }
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);

  float t = u_time;
  float flashInterval = u_flashRate;
  float decayDuration = 4.0;
  float cycleLen = float(MAX_SHAPES) * flashInterval;

  // Time within the current cycle
  float cycleTime = mod(t, cycleLen);

  // ── Background ──
  // Dark blue-purple base with subtle noise texture
  vec3 bg = vec3(0.015, 0.012, 0.025);
  float bgNoise = vnoise(p * 3.0 + t * 0.05) * 0.4 + vnoise(p * 7.0 - t * 0.03) * 0.3;
  bgNoise += vnoise(p * 1.5 + vec2(t * 0.02, -t * 0.01)) * 0.3;
  bg += vec3(0.008, 0.006, 0.015) * bgNoise;

  // Background pulse: brightens with each new shape (more visible)
  float currentShapeIdx = floor(cycleTime / flashInterval);
  float timeSinceLastFlash = cycleTime - currentShapeIdx * flashInterval;
  bool currentIsStrong = (mod(currentShapeIdx, 2.0) < 0.5);
  float bgPulseStrength = currentIsStrong ? 0.18 : 0.08;
  float bgPulse = exp(-timeSinceLastFlash * 6.0) * bgPulseStrength;
  bg += vec3(0.08, 0.06, 0.12) * bgPulse;

  vec3 col = bg;

  // ── Process each shape ──
  // We check shapes from two cycles: current and previous,
  // so fading shapes from the last cycle are still visible
  for (int ci = 0; ci < 2; ci++) {

    for (int i = 0; i < MAX_SHAPES; i++) {
      ShapeData shape = getShape(i, flashInterval);

      // For previous cycle, adjust birth times and use previous cycle seed
      float birthT = shape.birthTime;
      float fi = float(i);
      bool isStrong = (mod(fi, 2.0) < 0.5);
      if (ci == 1) {
        // Previous cycle shapes — recalculate with previous cycle hash
        float prevCycle = floor(t / cycleLen) - 1.0;
        float seed = fi * 13.37 + prevCycle * 97.31;
        shape.center = (hash2(seed + 1.0) * 2.0 - 1.0) * vec2(0.65, 0.50);
        float baseAngle = floor(hash(seed + 2.0) * 8.0) * (PI / 4.0);
        float angleJitter = (hash(seed + 5.0) - 0.5) * (PI / 6.0);
        shape.rotation = baseAngle + angleJitter;
        float baseScale = 0.4 + hash(seed + 3.0) * 1.2;
        shape.scale = isStrong ? baseScale * 1.3 : baseScale * 0.7;
        shape.type = int(mod(hash(seed + 4.0) * 5.0, 5.0));
        float jitter = (hash(seed + 10.0) - 0.5) * 0.2 * flashInterval;
        shape.birthTime = fi * flashInterval + jitter;
        birthT = shape.birthTime - cycleLen;
      }

      // Age of this shape
      float age = cycleTime - birthT;
      if (ci == 1) age = cycleTime + cycleLen - shape.birthTime;

      // Skip if not born yet or fully faded
      if (age < 0.0 || age > decayDuration) continue;

      // Decay phase: 0 = just born, 1 = fully gone
      float phase = age / decayDuration;

      // ── Evaluate SDF (with per-shape parallax depth) ──
      float depthLayer = 0.5 + float(i) * 0.25;
      vec2 localP = p - shape.center - mouseShift * depthLayer;
      localP = rot2(shape.rotation) * localP;
      float d = evalShape(localP, shape.type, shape.scale);

      // ── Flash moment (first 0.2s) ──
      float flashPhase = clamp(age / 0.2, 0.0, 1.0);
      float isFlashing = 1.0 - flashPhase;
      float beatMul = isStrong ? 1.4 : 0.8;

      // ── Layer 1: Active shape fill (translucent, edge-bright gradient) ──
      float fillAlpha = smoothstep(0.005, -0.005, d);
      // Interior gradient: brighter at edges (d near 0), dimmer at center (d very negative)
      float interiorDist = clamp(-d / (shape.scale * 0.25), 0.0, 1.0);
      float edgeBrightness = 1.0 - interiorDist * 0.65;
      float fillFade = exp(-age * 2.5);
      float flashBright = isFlashing * 2.0 * beatMul + fillFade;
      vec3 fillColor = decayColor(phase) * flashBright * edgeBrightness;

      // During flash moment, override to white (still with edge gradient)
      fillColor = mix(fillColor, vec3(2.5) * edgeBrightness, isFlashing * fillAlpha);

      col += fillColor * fillAlpha * (1.0 - phase * phase) * u_glowIntensity * 0.5;

      // ── Layer 2: Shape afterglow outline ──
      float edgeWidth = 0.006 + 0.003 * (1.0 - phase);
      float edge = smoothstep(edgeWidth, edgeWidth * 0.3, abs(d));
      float edgeFade = 1.0 - phase * phase * phase;
      vec3 edgeColor = decayColor(phase * 0.85) * edgeFade;

      // Edge is brighter than fill
      col += edgeColor * edge * u_glowIntensity * 1.2;

      // ── Layer 3: Edge bloom (soft glow) ──
      // Wider and softer during flash, tightens as shape decays
      float bloomWidthFlash = isStrong ? 0.08 : 0.05;
      float bloomWidthDecay = 0.015 + 0.015 * (1.0 - phase);
      float bloomWidth = mix(bloomWidthDecay, bloomWidthFlash, isFlashing);
      float bloom = exp(-abs(d) / bloomWidth);
      float bloomIntensity = mix(0.3, 1.8 * beatMul, isFlashing) * (1.0 - phase);
      vec3 bloomColor = decayColor(phase * 0.7);
      // Add warm tint to hottest point of bloom
      vec3 warmBloom = mix(bloomColor, bloomColor + vec3(0.15, 0.1, 0.05), bloom * isFlashing);
      col += warmBloom * bloom * bloomIntensity * u_glowIntensity * 0.4;

      // Extra hot bloom during flash — warm-tinted white core
      if (age < 0.25) {
        float hotBloomWidth = isStrong ? 0.10 : 0.06;
        float hotBloom = exp(-abs(d) / hotBloomWidth) * isFlashing;
        col += vec3(0.95, 0.92, 0.85) * hotBloom * u_glowIntensity * 0.7 * beatMul;
      }

      // ── Layer 4: Chromatic fringe ──
      // Pronounced RGB split at edges, especially during mid-decay (cyan→magenta)
      float fringePeak = sin(clamp(phase * PI, 0.0, PI));
      float fringeAmount = fringePeak * 0.035;
      if (fringeAmount > 0.001) {
        vec2 fringeDir = normalize(localP + vec2(0.001));
        // Wider fringe sampling for more visible separation
        float dR = evalShape(localP + fringeDir * fringeAmount, shape.type, shape.scale);
        float dB = evalShape(localP - fringeDir * fringeAmount, shape.type, shape.scale);
        // Also sample at half-offset for a softer outer halo
        float dR2 = evalShape(localP + fringeDir * fringeAmount * 0.5, shape.type, shape.scale);
        float dB2 = evalShape(localP - fringeDir * fringeAmount * 0.5, shape.type, shape.scale);
        float fringeEdgeW = edgeWidth * 2.0;
        float edgeR = smoothstep(fringeEdgeW, fringeEdgeW * 0.2, abs(dR));
        float edgeB = smoothstep(fringeEdgeW, fringeEdgeW * 0.2, abs(dB));
        float edgeR2 = smoothstep(fringeEdgeW * 1.5, fringeEdgeW * 0.3, abs(dR2));
        float edgeB2 = smoothstep(fringeEdgeW * 1.5, fringeEdgeW * 0.3, abs(dB2));
        float fringeFade = edgeFade * 0.8;
        col.r += (edgeR + edgeR2 * 0.5) * fringeFade * 0.5;
        col.b += (edgeB + edgeB2 * 0.5) * fringeFade * 0.5;
      }
    }
  }

  // ── Layer 6: Scanline overlay ──
  float scanline = sin(fragCoord.y * 1.5) * 0.5 + 0.5;
  scanline = 0.92 + scanline * 0.08;
  col *= scanline;

  // ── Vignette ──
  vec2 vc = uv - 0.5;
  float vig = 1.0 - dot(vc, vc) * 1.8;
  vig = clamp(vig, 0.0, 1.0);
  vig = pow(vig, 0.5);
  col *= vig;

  // ── Film grain ──
  float grain = (fract(sin(dot(fragCoord, vec2(12.9898, 78.233)) + fract(t * 0.1) * 100.0) * 43758.5453) - 0.5) * 0.025;
  col += grain;

  // ── ACES tone mapping ──
  col = ACESFilm(col);

  // ── Gamma correction ──
  col = pow(max(col, 0.0), vec3(0.95));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_sweep;
uniform float u_intensity;
uniform vec2 u_mouse;

#define PI 3.14159265359

// ── Hash & noise for fog ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash3(vec3 p) {
  return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453);
}

// ── 3D value noise ──
float noise3d(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float n000 = hash3(i);
  float n100 = hash3(i + vec3(1.0, 0.0, 0.0));
  float n010 = hash3(i + vec3(0.0, 1.0, 0.0));
  float n110 = hash3(i + vec3(1.0, 1.0, 0.0));
  float n001 = hash3(i + vec3(0.0, 0.0, 1.0));
  float n101 = hash3(i + vec3(1.0, 0.0, 1.0));
  float n011 = hash3(i + vec3(0.0, 1.0, 1.0));
  float n111 = hash3(i + vec3(1.0, 1.0, 1.0));
  float nx00 = mix(n000, n100, f.x);
  float nx10 = mix(n010, n110, f.x);
  float nx01 = mix(n001, n101, f.x);
  float nx11 = mix(n011, n111, f.x);
  float nxy0 = mix(nx00, nx10, f.y);
  float nxy1 = mix(nx01, nx11, f.y);
  return mix(nxy0, nxy1, f.z);
}

// ── FBM (4 octaves) ──
float fbm(vec3 p) {
  float v = 0.0;
  float a = 0.5;
  vec3 shift = vec3(100.0);
  for (int i = 0; i < 4; i++) {
    v += a * noise3d(p);
    p = p * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

// ── Color palette with hue rotation ──
vec3 coneColor(int idx, float hueShift) {
  vec3 col;
  if (idx == 0) col = vec3(1.0, 0.0, 0.5);
  else if (idx == 1) col = vec3(0.5, 0.05, 1.0);
  else if (idx == 2) col = vec3(0.1, 0.35, 1.0);
  else if (idx == 3) col = vec3(0.85, 0.0, 0.85);
  else if (idx == 4) col = vec3(0.15, 0.2, 1.0);
  else col = vec3(0.0, 0.8, 0.95);

  // Apply slow hue rotation
  float angle = hueShift;
  float cosA = cos(angle);
  float sinA = sin(angle);
  // Approximate hue rotation via luminance-preserving rotation
  float lum = dot(col, vec3(0.299, 0.587, 0.114));
  vec3 grey = vec3(lum);
  vec3 diff = col - grey;
  // Rotate in the plane perpendicular to the luminance axis
  vec3 axis1 = normalize(vec3(1.0, -1.0, 0.0));
  vec3 axis2 = normalize(vec3(0.5, 0.5, -1.0));
  float d1 = dot(diff, axis1);
  float d2 = dot(diff, axis2);
  vec3 rotated = grey + axis1 * (d1 * cosA - d2 * sinA) + axis2 * (d1 * sinA + d2 * cosA);
  return clamp(rotated, 0.0, 1.0);
}

void main() {
  // UV: 0..1 range, y=0 at bottom, y=1 at top
  vec2 fragUV = gl_FragCoord.xy / u_res;
  // Aspect-corrected UV centered at (0.5, 1.0) for top-origin cones
  float aspect = u_res.x / u_res.y;
  vec2 uv = fragUV;
  uv.x = (uv.x - 0.5) * aspect;  // centered horizontally, aspect corrected
  // uv.y goes 0 (bottom) to 1 (top)

  float t = u_time * u_sweep;
  float intensity = u_intensity;

  // ── Mouse attraction: bend beams toward cursor ──
  vec2 mouseUV = vec2(-1.0);
  if (u_mouse.x > 0.0) {
    mouseUV = u_mouse / u_res;
    mouseUV.x = (mouseUV.x - 0.5) * aspect;
  }

  // ── Fog base: 3D FBM noise drifting slowly ──
  vec3 fogCoord = vec3(fragUV * 3.0, t * 0.08);
  fogCoord.y -= t * 0.03;  // slow upward drift
  fogCoord.x += t * 0.015; // slight sideways drift
  float fogDensity = fbm(fogCoord);

  // Second fog layer for more detail
  vec3 fogCoord2 = vec3(fragUV * 6.0 + 50.0, t * 0.12);
  fogCoord2.y -= t * 0.05;
  float fogDetail = fbm(fogCoord2);
  float fog = fogDensity * 0.5 + fogDetail * 0.5;
  fog = fog * fog * 1.5;  // boost contrast for visible wisps

  // ── Accumulate light from all cones ──
  vec3 col = vec3(0.0);

  // Bounded hue oscillation (stays in cool/neon range)
  float hueShift = sin(t * 0.07) * 0.2;

  // Global beat pulse (~1.5 second period)
  float globalBeat = pow(abs(sin(t * PI / 1.5)), 8.0) * 0.2;

  // ── Far layer: 3 cones (indices 0-2) ──
  // These are dimmer, move slower, slightly blurred
  for (int i = 0; i < 3; i++) {
    float fi = float(i);

    // Origin spread along top edge
    float originX = (fi - 1.0) * 0.4 * aspect;  // spread across top
    originX += sin(t * 0.07 + fi * 2.5) * 0.1 * aspect;  // slight drift
    vec2 origin = vec2(originX, 1.05);  // just above top edge

    // Sweep angle: smooth sinusoidal, slower for far layer
    float baseAngle = PI * 0.5;  // pointing downward (toward y=0)
    float sweepAmp = 0.4 + fi * 0.1;
    float sweepFreq = 0.3 + fi * 0.11;
    float theta = sin(t * sweepFreq * 0.7 + fi * 1.9) * sweepAmp;

    // Direction of cone center (pointing downward from top)
    vec2 dir = vec2(sin(theta), -cos(theta));

    // Mouse attraction: smoothly bend beam toward cursor
    if (mouseUV.x > -0.5) {
      vec2 toMouse = mouseUV - origin;
      float mouseAngle = atan(toMouse.x, -toMouse.y);
      float attraction = 0.3 / (1.0 + length(toMouse) * 2.0);
      float angleDiff = mouseAngle - theta;
      // Normalize angle diff to [-PI, PI] to prevent wrapping jumps
      angleDiff = mod(angleDiff + PI, PI * 2.0) - PI;
      float blended = theta + angleDiff * attraction;
      dir = vec2(sin(blended), -cos(blended));
    }

    // Vector from origin to current pixel
    vec2 toPixel = uv - origin;

    // Project onto cone axis
    float along = dot(toPixel, dir);

    // Perpendicular distance from cone axis
    float perp = abs(toPixel.x * dir.y - toPixel.y * dir.x);

    // Wide cone for far layer
    float halfWidth = 0.13 + fi * 0.015;
    float coneWidth = halfWidth * max(along, 0.0) + 0.012;

    // Soft gaussian falloff from center
    float inCone = exp(-perp * perp / (coneWidth * coneWidth * 0.55));

    // Only illuminate in front of origin (along > 0)
    inCone *= smoothstep(0.0, 0.08, along);

    // Distance falloff (dimmer farther from source)
    inCone *= exp(-along * along * 0.15);

    // Fog modulation: light scattering through smoke
    float fogMod = 0.25 + fog * 0.75;
    float volumetric = inCone * fogMod;

    // Far layer: reduced brightness and slightly blurred (wider cone)
    float farOpacity = 0.35;

    vec3 coneCol = coneColor(i, hueShift + fi * 0.15);
    col += coneCol * volumetric * farOpacity * intensity * (1.0 + globalBeat);
  }

  // ── Near layer: 3 cones (indices 3-5) ──
  // Brighter, sharper, faster movement
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    int colorIdx = i + 3;

    // Origin spread along top edge, offset from far layer
    float originX = (fi - 1.0) * 0.5 * aspect + 0.15 * aspect;
    originX += sin(t * 0.1 + fi * 3.1 + 1.0) * 0.08 * aspect;
    vec2 origin = vec2(originX, 1.02);

    // Sweep angle: smooth sinusoidal + beat snaps
    float sweepAmp = 0.5 + fi * 0.08;
    float sweepFreq = 0.4 + fi * 0.13;
    float theta = sin(t * sweepFreq + fi * 2.3 + 0.7) * sweepAmp;

    // Beat snap: smooth rhythmic accent on 1-2 cones at a time
    float beatFreq = 1.8 + fi * 0.4;
    float snap = pow(abs(sin(t * beatFreq)), 6.0);
    // Smooth gate so snaps fade in/out rather than pop
    float snapGate = smoothstep(0.5, 0.85, sin(t * 0.7 + fi * 2.094));
    theta += snap * snapGate * 0.18 * sin(t * beatFreq * 0.5);

    vec2 dir = vec2(sin(theta), -cos(theta));

    // Mouse attraction: smoothly bend beam toward cursor
    if (mouseUV.x > -0.5) {
      vec2 toMouse = mouseUV - origin;
      float mouseAngle = atan(toMouse.x, -toMouse.y);
      float attraction = 0.4 / (1.0 + length(toMouse) * 2.0);
      float angleDiff = mouseAngle - theta;
      angleDiff = mod(angleDiff + PI, PI * 2.0) - PI;
      float blended = theta + angleDiff * attraction;
      dir = vec2(sin(blended), -cos(blended));
    }

    vec2 toPixel = uv - origin;
    float along = dot(toPixel, dir);
    float perp = abs(toPixel.x * dir.y - toPixel.y * dir.x);

    // Wider cone for cinematic spotlights
    float halfWidth = 0.11 + fi * 0.012;
    float coneWidth = halfWidth * max(along, 0.0) + 0.01;

    // Gaussian falloff with bright core
    float inCone = exp(-perp * perp / (coneWidth * coneWidth * 0.4));
    // Bright center line within cone
    float coreLine = exp(-perp * perp / (coneWidth * coneWidth * 0.04));
    inCone = inCone + coreLine * 0.4;
    inCone *= smoothstep(0.0, 0.06, along);
    inCone *= exp(-along * along * 0.1);

    // Fog modulation
    float fogMod = 0.2 + fog * 0.8;
    float volumetric = inCone * fogMod;

    // Near layer: bright
    float nearOpacity = 0.75;

    vec3 coneCol = coneColor(colorIdx, hueShift + fi * 0.15 + 0.5);
    col += coneCol * volumetric * nearOpacity * intensity * (1.0 + globalBeat);
  }

  // ── Intersection bloom: additive blending already handles this ──
  // Where cones overlap, color adds up. Boost those bright areas toward white.
  float brightness = dot(col, vec3(0.299, 0.587, 0.114));
  // Push overlapping areas toward white (desaturate at high brightness)
  float whiteBlend = smoothstep(0.4, 1.2, brightness);
  col = mix(col, vec3(brightness * 1.3), whiteBlend * 0.5);

  // ── Ground haze: fog pooling on the dance floor ──
  float groundHaze = smoothstep(0.2, 0.0, fragUV.y);
  float hazeFog = fbm(vec3(fragUV.x * 4.0, fragUV.y * 2.0, t * 0.05 + 10.0));
  col += col * groundHaze * 0.3;
  // Subtle ambient haze at floor level
  col += vec3(0.06, 0.03, 0.1) * groundHaze * hazeFog * intensity;

  // ── Exponential tone mapping ──
  float exposure = 2.0;
  col = 1.0 - exp(-col * exposure);

  // ── Film grain ──
  float grain = hash(gl_FragCoord.xy + fract(u_time) * 100.0) * 0.04 - 0.02;
  col += grain;

  // ── Vignette (corners only) ──
  vec2 vigUV = fragUV - 0.5;
  float vigDist = dot(vigUV, vigUV);
  float vig = 1.0 - vigDist * 0.8;
  vig = clamp(vig, 0.0, 1.0);
  col *= vig;

  // Clamp to valid range
  col = clamp(col, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_bassFreq;
uniform float u_bassIntensity;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash / noise ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash3(vec3 p) {
  return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

// ── Rotation ──
mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// ── Beat-synced displacement ──
// Returns height displacement at a mesh point, combining multiple wave modes
float displacement(vec2 p, float t, float bassFreq, float intensity) {
  float period = 1.0 / max(bassFreq, 0.01);
  float phase = t / period;
  float beatFrac = fract(phase);

  // Sharp attack, exponential decay per beat
  float envelope = exp(-beatFrac * 3.5);

  // Previous beat residue for overlapping waves
  float prevEnv = exp(-(beatFrac + 1.0) * 3.5);
  float prevEnv2 = exp(-(beatFrac + 2.0) * 3.5);

  float dist = length(p);
  float angle = atan(p.y, p.x);

  // Wave mode 1: concentric ripples from center — primary bass hit
  float wave1 = sin(dist * 14.0 - beatFrac * 22.0) * envelope;

  // Wave mode 2: slower, wider concentric from center (prev beat residue)
  float wave2 = sin(dist * 9.0 - (beatFrac + 1.0) * 16.0) * prevEnv * 0.6;

  // Wave mode 3: second prev beat — even wider, fainter
  float wave3 = sin(dist * 6.0 - (beatFrac + 2.0) * 12.0) * prevEnv2 * 0.3;

  // Wave mode 4: standing wave pattern (cross-hatch)
  float standing = (sin(p.x * 18.0) * sin(p.y * 18.0)) * envelope * 0.3;

  // Wave mode 5: radial drumhead modes (angular patterns)
  float radialMode = sin(dist * 22.0) * cos(angle * 3.0) * envelope * 0.2;
  radialMode += sin(dist * 16.0) * cos(angle * 5.0 + 1.0) * prevEnv * 0.1;

  // Wave mode 6: off-center ripple source (drifts slowly)
  vec2 offCenter = vec2(0.3 * sin(t * 0.2), 0.25 * cos(t * 0.25));
  float dist2 = length(p - offCenter);
  float wave6 = sin(dist2 * 12.0 - beatFrac * 18.0) * envelope * 0.35;

  // Mouse ripple origin
  float mouseWave = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mouseNorm = (u_mouse / u_res - 0.5) * vec2(u_res.x / u_res.y, 1.0);
    float mouseDist = length(p - mouseNorm);
    mouseWave = sin(mouseDist * 16.0 - beatFrac * 20.0) * envelope * 0.7;
    mouseWave += sin(mouseDist * 10.0 - (beatFrac + 1.0) * 14.0) * prevEnv * 0.4;
    mouseWave *= 1.0 / (1.0 + mouseDist * 3.0);
  }

  // Low-frequency dome push — the whole mesh pushes out on beat
  float dome = (1.0 - smoothstep(0.0, 1.0, dist)) * envelope * 0.8;

  float h = (wave1 + wave2 + wave3 + standing + radialMode + wave6 + mouseWave + dome) * intensity;

  // Subtle idle vibration when between beats
  float idle = sin(dist * 8.0 + t * 3.0) * 0.03 * (1.0 - envelope);
  idle += sin(dist * 5.0 - t * 1.5) * 0.015 * (1.0 - envelope);
  h += idle * intensity;

  return h;
}

// ── Compute normal from displacement via forward differences ──
vec3 calcNormal(vec2 p, float t, float bassFreq, float intensity, float hc) {
  float eps = 0.002;
  float hx = displacement(p + vec2(eps, 0.0), t, bassFreq, intensity);
  float hy = displacement(p + vec2(0.0, eps), t, bassFreq, intensity);
  vec3 n = normalize(vec3(-(hx - hc) / eps * 0.35, -(hy - hc) / eps * 0.35, 1.0));
  return n;
}

// ── Hexagonal grid distance ──
// Returns: x = distance to nearest hex edge, y,z = hex cell ID
vec3 hexGrid(vec2 p, float scale) {
  p *= scale;
  vec2 r = vec2(1.0, 1.732);
  vec2 h = r * 0.5;
  vec2 a = mod(p, r) - h;
  vec2 b = mod(p - h, r) - h;
  vec2 g;
  if (dot(a, a) < dot(b, b)) {
    g = a;
  } else {
    g = b;
  }
  float edgeDist = 0.5 - max(abs(g.x) * 1.0 + abs(g.y) * 0.577, abs(g.y) * 1.155);
  vec2 cellId = p - g;
  return vec3(edgeDist, cellId);
}

// ── Fresnel approximation ──
float fresnel(float cosTheta, float f0) {
  return f0 + (1.0 - f0) * pow(1.0 - cosTheta, 5.0);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;
  float t = u_time;

  // Centered UV with aspect correction
  vec2 cuv = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);

  // ═══════════════════════════════════════════
  // Camera / view setup — slightly off-axis
  // ═══════════════════════════════════════════
  // Subtle camera drift for life
  float camDriftX = sin(t * 0.15) * 0.03;
  float camDriftY = cos(t * 0.12) * 0.02;

  // Off-axis tilt: rotate the UV plane to simulate angled view
  // Perspective foreshortening — compress vertical axis
  float tiltAngle = 0.35 + camDriftY;
  float foreshorten = 0.7 + camDriftY * 0.5;

  vec2 meshUV = cuv;
  meshUV.x += camDriftX;
  meshUV.y = meshUV.y / foreshorten;
  meshUV.y += 0.08;

  // Slight rotation for off-axis look
  meshUV = rot2(0.06 + sin(t * 0.08) * 0.02) * meshUV;

  // ═══════════════════════════════════════════
  // Displacement — beat-synced wave patterns
  // ═══════════════════════════════════════════
  float h = displacement(meshUV, t, u_bassFreq, u_bassIntensity);
  vec3 N = calcNormal(meshUV, t, u_bassFreq, u_bassIntensity, h);

  // ═══════════════════════════════════════════
  // Hexagonal mesh pattern
  // ═══════════════════════════════════════════
  float meshScale = 45.0;
  vec3 hex = hexGrid(meshUV + N.xy * 0.003, meshScale);
  float hexEdge = hex.x;

  // Wire thickness — the metallic wires of the grille
  float wireWidth = 0.06;
  float wire = 1.0 - smoothstep(0.0, wireWidth, hexEdge);

  // Inner hole mask — what you see through the grille
  float hole = smoothstep(wireWidth, wireWidth + 0.02, hexEdge);

  // Fine secondary grid overlaid (cross-hatch detail at micro level)
  vec2 microGrid = fract(meshUV * meshScale * 3.0 + N.xy * 0.01);
  float microWire = smoothstep(0.04, 0.0, min(microGrid.x, microGrid.y));
  microWire += smoothstep(0.04, 0.0, min(1.0 - microGrid.x, 1.0 - microGrid.y));
  microWire *= 0.15;

  // ═══════════════════════════════════════════
  // Lighting setup
  // ═══════════════════════════════════════════
  // View direction (from camera)
  vec3 V = normalize(vec3(-cuv.x * 0.3, -cuv.y * 0.3 + 0.2, 1.0));

  // Beat envelope for light modulation
  float period = 1.0 / max(u_bassFreq, 0.01);
  float bFrac = fract(t / period);
  float bEnv = exp(-bFrac * 3.5);

  // Key light — warm amber, sweeps slowly across surface
  vec3 L1 = normalize(vec3(0.4 + sin(t * 0.25) * 0.4, 0.6 + cos(t * 0.18) * 0.3, 1.0));
  float NdL1 = max(dot(N, L1), 0.0);
  vec3 H1 = normalize(L1 + V);
  float NdH1 = max(dot(N, H1), 0.0);
  float spec1 = pow(NdH1, 180.0);
  float spec1med = pow(NdH1, 50.0);
  float spec1soft = pow(NdH1, 12.0);
  vec3 lightCol1 = vec3(1.0, 0.82, 0.55);

  // Fill light — deeper copper/bronze, from the left
  vec3 L2 = normalize(vec3(-0.8 + sin(t * 0.15) * 0.2, 0.4, 0.8));
  float NdL2 = max(dot(N, L2), 0.0);
  vec3 H2 = normalize(L2 + V);
  float NdH2 = max(dot(N, H2), 0.0);
  float spec2 = pow(NdH2, 120.0);
  float spec2soft = pow(NdH2, 25.0);
  vec3 lightCol2 = vec3(0.85, 0.55, 0.3);

  // Accent light — bright gold, moves with beat
  vec3 L3 = normalize(vec3(0.3 + bEnv * 0.3, -0.6, 0.6));
  float NdL3 = max(dot(N, L3), 0.0);
  vec3 H3 = normalize(L3 + V);
  float NdH3 = max(dot(N, H3), 0.0);
  float spec3 = pow(NdH3, 90.0);
  float spec3soft = pow(NdH3, 18.0);
  vec3 lightCol3 = vec3(1.0, 0.7, 0.25);

  // Top-down fill for overall brightness
  vec3 L4 = normalize(vec3(0.0, 0.1, 1.0));
  float NdL4 = max(dot(N, L4), 0.0);

  // Rim/backlight — warm amber edge light
  float NdV = max(dot(N, V), 0.0);
  float rim = pow(1.0 - NdV, 4.0);
  vec3 rimCol = vec3(0.9, 0.55, 0.2);

  // ═══════════════════════════════════════════
  // Material: metallic gunmetal / brushed chrome
  // ═══════════════════════════════════════════
  vec3 baseColor = vec3(0.38, 0.32, 0.25);
  baseColor += vec3(0.035, 0.025, 0.015) * noise(meshUV * 30.0);
  baseColor += vec3(0.02, 0.015, 0.01) * noise(meshUV * 80.0 + 5.0);

  // Strong metallic fresnel
  float f0 = 0.75;
  float fres = fresnel(NdV, f0);

  // ═══════════════════════════════════════════
  // Compose wire material
  // ═══════════════════════════════════════════
  // Diffuse — generous for visible wire brightness
  vec3 diffuse = baseColor * (NdL1 * lightCol1 * 1.0 + NdL2 * lightCol2 * 0.5 + NdL3 * lightCol3 * 0.25 + NdL4 * 0.4);
  // Strong ambient — ensures wires are always clearly visible as metal
  diffuse += baseColor * 0.18;
  // Hemisphere ambient — warm amber above, darker below
  vec3 hemiAmb = mix(vec3(0.04, 0.03, 0.02), vec3(0.08, 0.06, 0.04), N.y * 0.5 + 0.5);
  diffuse += hemiAmb;

  // Specular — the star of the show
  vec3 specular = vec3(0.0);
  // Key: sharp peak + broad medium + very wide bloom
  specular += spec1 * lightCol1 * 3.5;
  specular += spec1med * lightCol1 * 1.2;
  specular += spec1soft * lightCol1 * 0.25;
  // Fill: sharp + broad
  specular += spec2 * lightCol2 * 2.5;
  specular += spec2soft * lightCol2 * 0.5;
  // Accent: magenta — sharp + broad
  specular += spec3 * lightCol3 * 3.0;
  specular += spec3soft * lightCol3 * 0.4;
  specular *= fres;

  // Beat flare on specular
  specular *= 1.0 + bEnv * 1.0 * u_bassIntensity;

  // Anisotropic edge highlight on the wire ridge
  float wireCenter = abs(hexEdge - wireWidth * 0.5) / max(wireWidth, 0.001);
  float aniso = pow(max(1.0 - wireCenter, 0.0), 3.0);
  specular += aniso * wire * vec3(0.55, 0.4, 0.2) * fres * 0.5;

  // Wire color composition
  vec3 wireCol = diffuse + specular;
  wireCol += rim * rimCol * 0.5;

  // Micro scratches catching light
  wireCol += microWire * vec3(0.15, 0.1, 0.06) * fres;

  // ═══════════════════════════════════════════
  // Hole interior — dark void with depth
  // ═══════════════════════════════════════════
  vec3 holeCol = vec3(0.015, 0.01, 0.006);
  // Speaker cone behind the mesh — subtle presence
  float coneRefl = max(dot(N, vec3(0.0, 0.0, 1.0)), 0.0);
  holeCol += vec3(0.03, 0.02, 0.01) * coneRefl;

  // Beat pulse visible in holes — cone movement + light leak
  float conePush = max(h * 0.4, 0.0);
  holeCol += vec3(0.06, 0.04, 0.02) * conePush;
  // Warm amber light leaking through grille on beat
  holeCol += vec3(0.2, 0.12, 0.04) * bEnv * 0.35 * u_bassIntensity;
  // Copper accent leak
  holeCol += vec3(0.12, 0.06, 0.02) * bEnv * 0.15 * u_bassIntensity;

  // ═══════════════════════════════════════════
  // Combine wire + hole
  // ═══════════════════════════════════════════
  vec3 col = mix(holeCol, wireCol, wire);

  // Add micro-wire overlay even on holes (very fine secondary mesh)
  col += microWire * vec3(0.02, 0.018, 0.025) * (1.0 - hole * 0.7);

  // ═══════════════════════════════════════════
  // Beat-synced global effects
  // ═══════════════════════════════════════════
  // Color wash on beat — alternates amber and copper
  vec3 beatColor = mix(vec3(0.5, 0.3, 0.1), vec3(0.4, 0.2, 0.08), sin(t * 0.4) * 0.5 + 0.5);
  col += beatColor * bEnv * 0.03 * u_bassIntensity;

  // ═══════════════════════════════════════════
  // Environment reflection on wire surface
  // ═══════════════════════════════════════════
  // Rich fake environment map — studio HDRI-like
  vec3 refl = reflect(-V, N);
  vec3 envCol = vec3(0.03, 0.03, 0.06);
  // Warm overhead gradient
  envCol += vec3(0.12, 0.08, 0.06) * pow(max(refl.y, 0.0), 2.0);
  // Warm side gradient
  envCol += vec3(0.15, 0.08, 0.03) * pow(max(-refl.x, 0.0), 2.0);
  // Copper accent below
  envCol += vec3(0.2, 0.1, 0.04) * pow(max(-refl.y, 0.0), 3.0);
  // Bright studio softbox reflection
  float softbox = pow(max(dot(refl, normalize(vec3(0.2, 0.8, 0.5))), 0.0), 8.0);
  envCol += vec3(0.3, 0.28, 0.25) * softbox;
  // Beat-pulsed environment brightness
  envCol *= 1.0 + bEnv * 0.5 * u_bassIntensity;
  col += envCol * fres * wire * 0.5;

  // ═══════════════════════════════════════════
  // Post processing
  // ═══════════════════════════════════════════
  // Vignette — macro lens effect
  vec2 vc = uv - 0.5;
  float vig = 1.0 - dot(vc, vc) * 2.0;
  vig = smoothstep(0.0, 1.0, vig);
  col *= vig;

  // Subtle depth-of-field blur at edges (darken + desaturate)
  float dofDist = length(cuv);
  float dof = smoothstep(0.3, 0.8, dofDist);
  col = mix(col, col * vec3(0.7, 0.65, 0.75), dof * 0.3);

  // Film grain — macro photography feel
  float grain = hash(gl_FragCoord.xy + fract(t * 7.3) * 100.0);
  col += (grain - 0.5) * 0.018;

  // Subtle chromatic aberration at vignette edges
  float ca = dofDist * 0.003;
  col.r += (hash(gl_FragCoord.xy * 0.5 + 1.0) - 0.5) * ca;
  col.b += (hash(gl_FragCoord.xy * 0.5 + 2.0) - 0.5) * ca;

  // Tone mapping — Reinhard with high white point + gentle gamma lift
  col = col / (col + vec3(1.5));
  col = pow(max(col, vec3(0.0)), vec3(0.88));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;

uniform float u_time;
uniform vec2 u_res;
uniform float u_waveSpeed;
uniform float u_sparkle;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718
#define SQRT3 1.7320508

// ── Hash functions for per-sequin variation ──
float hash21(vec2 p) {
  p = fract(p * vec2(233.34, 851.73));
  p += dot(p, p + 23.45);
  return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
  float n = hash21(p);
  return vec2(n, hash21(p + n * 47.0));
}

// ── Hexagonal tiling ──
// Returns: xy = local coords within hex cell, zw = cell ID
vec4 hexTile(vec2 p, float scale) {
  p *= scale;
  // Two candidate grids offset by half a cell
  vec2 s = vec2(1.0, SQRT3);
  vec2 halfS = s * 0.5;

  // Grid A
  vec2 aBase = floor(p / s);
  vec2 aLocal = mod(p, s) - halfS;

  // Grid B (offset)
  vec2 pOff = p - halfS;
  vec2 bBase = floor(pOff / s);
  vec2 bLocal = mod(pOff, s) - halfS;

  // Pick nearest center
  float dA = dot(aLocal, aLocal);
  float dB = dot(bLocal, bLocal);

  // Use step to avoid branching
  float pick = step(dA, dB);
  vec2 localCoord = mix(bLocal, aLocal, pick);
  vec2 cellId = mix(bBase + vec2(0.5), aBase, pick);

  return vec4(localCoord, cellId);
}

// ── Wave field: multiple interfering wave sources ──
float waveField(vec2 cellPos, float t) {
  float w = 0.0;

  // Wave 1: diagonal sweep
  w += sin(dot(cellPos, vec2(0.7, 0.5)) * 3.5 - t * 2.8) * 0.35;

  // Wave 2: horizontal ripple
  w += sin(cellPos.x * 4.2 + t * 1.9) * 0.25;

  // Wave 3: radial pulse from offset center
  float r1 = length(cellPos - vec2(-0.3, 0.2));
  w += sin(r1 * 6.0 - t * 3.2) * 0.2 * smoothstep(1.2, 0.0, r1);

  // Wave 4: slower diagonal from opposite direction
  w += sin(dot(cellPos, vec2(-0.4, 0.8)) * 2.8 - t * 1.5) * 0.2;

  // Wave 5: secondary radial from other side
  float r2 = length(cellPos - vec2(0.4, -0.3));
  w += sin(r2 * 5.0 - t * 2.4) * 0.15 * smoothstep(1.0, 0.0, r2);

  return w;
}

// ── Specular calculation for a tilted sequin disc ──
// tiltAngle: how much the sequin is tilted by the wave
// tiltDir: direction of the tilt (2D angle)
// Returns specular intensity
float sequinSpecular(float tiltAngle, float tiltDir, vec2 uv) {
  // Sequin normal: starts as (0,0,1), tilted by wave
  float ct = cos(tiltAngle);
  float st = sin(tiltAngle);
  float cd = cos(tiltDir);
  float sd = sin(tiltDir);

  // Normal of tilted disc
  vec3 N = vec3(st * cd, st * sd, ct);

  // Light direction (from upper-right, slightly behind camera)
  vec3 L = normalize(vec3(0.4, 0.6, 0.9));

  // View direction (straight on)
  vec3 V = vec3(0.0, 0.0, 1.0);

  // Reflection of light off sequin surface
  vec3 R = reflect(-L, N);

  // Specular: how well reflection aligns with view
  float spec = max(dot(R, V), 0.0);

  // Very tight specular for mirror-like sequins
  spec = pow(spec, 48.0);

  // Secondary broader highlight for ambient sheen
  float sheen = pow(max(dot(R, V), 0.0), 8.0) * 0.15;

  return spec + sheen;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  float t = u_time * u_waveSpeed;

  // ── Hexagonal grid of sequins ──
  float sequinScale = 38.0; // density of sequins
  vec4 hex = hexTile(uv, sequinScale);
  vec2 localPos = hex.xy;  // position within cell
  vec2 cellId = hex.zw;    // which cell

  // ── Per-sequin random variation ──
  vec2 rnd = hash22(cellId);
  float sizeVar = 0.85 + rnd.x * 0.3;       // size variation
  float baseTilt = (rnd.y - 0.5) * 0.15;     // resting tilt offset
  float reflVar = 0.7 + rnd.x * 0.3;         // reflectivity variation
  float phaseOff = rnd.y * TAU;               // phase offset for shimmer

  // ── Sequin disc shape ──
  float discRadius = 0.42 * sizeVar;
  float dist = length(localPos);
  float disc = smoothstep(discRadius, discRadius - 0.06, dist);

  // Subtle edge bevel highlight
  float bevel = smoothstep(discRadius, discRadius - 0.04, dist)
              - smoothstep(discRadius - 0.04, discRadius - 0.08, dist);

  // ── World position of this sequin (for wave sampling) ──
  vec2 worldPos = cellId / sequinScale;

  // ── Wave-driven tilt ──
  float wave = waveField(worldPos, t);

  // Add subtle individual shimmer
  float shimmer = sin(t * 3.0 + phaseOff) * 0.04;

  // Tilt angle from wave + individual variation
  float tiltAngle = wave * 0.85 + baseTilt + shimmer;

  // Tilt direction: follows the wave gradient
  // Approximate gradient with offset samples
  float waveH = waveField(worldPos + vec2(0.01, 0.0), t);
  float waveV = waveField(worldPos + vec2(0.0, 0.01), t);
  float tiltDir = atan(waveV - wave, waveH - wave);

  // ── Mouse light source: extra specular from cursor ──
  float mouseSpec = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    float mDist = length(worldPos - mUV);
    float mInfluence = exp(-mDist * mDist * 6.0);
    // Light from mouse position
    vec3 mLightDir = normalize(vec3(mUV.x - worldPos.x, mUV.y - worldPos.y, 0.5));
    float ct = cos(tiltAngle);
    float st2 = sin(tiltAngle);
    float cd = cos(tiltDir);
    float sd = sin(tiltDir);
    vec3 mN = vec3(st2 * cd, st2 * sd, ct);
    vec3 mR = reflect(-mLightDir, mN);
    float mS = pow(max(dot(mR, vec3(0.0, 0.0, 1.0)), 0.0), 32.0);
    mouseSpec = mS * mInfluence * 1.5;
  }

  // ── Specular flash ──
  float spec = sequinSpecular(tiltAngle, tiltDir, uv);
  spec *= reflVar * u_sparkle;
  spec += mouseSpec * reflVar;

  // ── Color composition ──
  // Dark base: sequin that is tilted away from light
  vec3 darkSequin = vec3(0.02, 0.015, 0.01);

  // Mid-tone: ambient copper reflection
  vec3 copperMid = vec3(0.78, 0.58, 0.42);

  // Bright flash: hot amber/gold when specular aligns
  vec3 amberFlash = vec3(1.0, 0.82, 0.55);

  // Hot white-gold for peak brightness
  vec3 hotGold = vec3(1.0, 0.92, 0.72);

  // Base sequin color depends on tilt (how much it faces camera)
  float facing = cos(tiltAngle) * 0.5 + 0.5;
  facing = clamp(facing, 0.0, 1.0);

  // Warm ambient: even dark sequins have a hint of warmth
  vec3 ambient = mix(darkSequin, vec3(0.05, 0.035, 0.02), facing * 0.6);

  // Build up the specular flash in layers
  vec3 sequinColor = ambient;

  // Broad warm sheen
  float sheenAmount = pow(max(facing, 0.0), 3.0) * 0.2 * reflVar;
  sequinColor += copperMid * sheenAmount;

  // Specular flash
  float flashLow = smoothstep(0.0, 0.3, spec);
  float flashHigh = smoothstep(0.3, 0.8, spec);
  float flashPeak = smoothstep(0.7, 1.0, spec);
  sequinColor += copperMid * flashLow * 0.5;
  sequinColor += amberFlash * flashHigh * 0.8;
  sequinColor += hotGold * flashPeak * 1.2;

  // Bevel edge catches light differently
  sequinColor += copperMid * bevel * facing * 0.3;

  // ── Background between sequins ──
  // Dark gap with very subtle warm tone
  vec3 bgColor = vec3(0.012, 0.008, 0.005);

  // ── Final mix: disc mask selects sequin vs gap ──
  vec3 col = mix(bgColor, sequinColor, disc);

  // ── Global lighting: subtle gradient from light direction ──
  vec2 uvSafe = uv + vec2(0.0001);
  float globalLight = 0.85 + 0.15 * dot(normalize(uvSafe), vec2(0.4, 0.6));
  col *= globalLight;

  // ── Vignette ──
  float vig = 1.0 - smoothstep(0.4, 1.3, length(uv));
  col *= 0.6 + 0.4 * vig;

  // ── Warm gamma correction ──
  col = pow(max(col, vec3(0.0)), vec3(0.93, 0.97, 1.04));

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_lightSpeed;
uniform float u_tileScale;
uniform float u_animMode;
uniform float u_waveSpeed;
uniform float u_waveDelay;
uniform float u_waveDir;
uniform vec2 u_mouse;
uniform vec2 u_click;
uniform float u_clickTime;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Pseudo-random hash ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 hash2(vec2 p) {
  return vec2(
    fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453),
    fract(sin(dot(p, vec2(269.5, 183.3))) * 43758.5453)
  );
}

// ── Smooth value noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── Tile grid with jitter ──
// Returns: xy = local coord within tile, zw = tile ID
vec4 tileGrid(vec2 p, float scale) {
  vec2 sp = p * scale;
  vec2 id = floor(sp);
  vec2 f = fract(sp);

  // Jitter tile boundaries slightly for organic look
  vec2 jitter = hash2(id) * 0.12 - 0.06;
  f -= jitter;

  return vec4(f, id);
}

// ── Per-tile normal (tilted surface) ──
vec3 tileNormal(vec2 id) {
  float h1 = hash(id * 1.731 + 17.3);
  float h2 = hash(id * 2.419 + 31.7);

  // Slight random tilt - each tile angled differently
  float tiltX = (h1 - 0.5) * 0.35;
  float tiltY = (h2 - 0.5) * 0.35;

  return normalize(vec3(tiltX, tiltY, 1.0));
}

// ── Grout detection ──
float groutMask(vec2 f, float groutWidth) {
  vec2 edge = smoothstep(vec2(0.0), vec2(groutWidth), f) *
              smoothstep(vec2(0.0), vec2(groutWidth), vec2(1.0) - f);
  return edge.x * edge.y;
}

// ── Surface micro-roughness within a tile ──
float tileRoughness(vec2 f, vec2 id) {
  // Subtle bumps on tile surface (faceted glass / tesserae)
  float h = hash(id + 99.0);
  float n1 = noise(f * 8.0 + id * 3.7);
  float n2 = noise(f * 16.0 + id * 7.1 + 50.0);
  return n1 * 0.6 + n2 * 0.4;
}

// ── Wave flip: configurable direction, speed, delay ──
// dir: 0=left-to-right, 1=right-to-left, 2=top-to-bottom, 3=bottom-to-top
vec2 waveFlip(vec2 tileCenter, float rawTime, vec2 aspect) {
  float sweepDur = u_waveSpeed;
  float cycleDur = sweepDur + u_waveDelay;
  float cycleT = mod(rawTime, cycleDur);
  float waveCount = floor(rawTime / cycleDur);
  float isOddWave = mod(waveCount, 2.0);

  // Ease-in-out cubic for smooth sweep
  float sweepRaw = clamp(cycleT / sweepDur, 0.0, 1.0);
  float sweep = sweepRaw * sweepRaw * (3.0 - 2.0 * sweepRaw);

  // Direction: project tile position onto wave axis
  float dir = floor(u_waveDir + 0.5);
  float axisLen = aspect.x;
  float tilePos = tileCenter.x;
  if (dir == 1.0) { tilePos = aspect.x - tileCenter.x; }
  else if (dir == 2.0) { tilePos = 1.0 - tileCenter.y; axisLen = 1.0; }
  else if (dir == 3.0) { tilePos = tileCenter.y; axisLen = 1.0; }

  float waveX = sweep * (axisLen + 0.6) - 0.3;

  // Per-tile stagger
  float tileRand = hash(tileCenter * 31.7 + vec2(17.3, 59.1));
  float stagger = tileRand * 0.06;
  float dist = tilePos - waveX + stagger;

  // Wide wave front
  float flipProgress = smoothstep(0.5, -0.3, dist);
  float flipAngle = (isOddWave + flipProgress) * PI;

  // Transition intensity
  float inTransition = smoothstep(0.6, 0.0, abs(dist + 0.1));
  return vec2(flipAngle, inTransition);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  vec2 aspect = vec2(u_res.x / u_res.y, 1.0);
  vec2 p = uv * aspect;
  float t = u_time * u_lightSpeed;

  // ── Tile grid ──
  float scale = 18.0 * u_tileScale;
  vec4 tile = tileGrid(p, scale);
  vec2 f = tile.xy;
  vec2 id = tile.zw;

  // ── Grout ──
  float groutW = 0.06;
  float tMask = groutMask(f, groutW);

  // ── Per-tile properties ──
  float tileHash = hash(id);
  float tileHash2 = hash(id + 200.0);
  float tileHash3 = hash(id + 400.0);
  vec3 N = tileNormal(id);

  // Add micro-surface variation within tile
  float roughness = tileRoughness(f, id);
  N = normalize(N + vec3(
    (roughness - 0.5) * 0.12,
    (noise(f * 12.0 + id * 5.3) - 0.5) * 0.12,
    0.0
  ));

  // ── Wave flip animation with 3D perspective ──
  vec2 tileCenter = (id + 0.5) / scale;
  vec2 flipData = waveFlip(tileCenter, u_time, aspect);
  float flipAngle = flipData.x * u_animMode;
  float inTransition = flipData.y * u_animMode;

  // Click-triggered radial flip wave (use raw pixel position for distance)
  if (u_clickTime > 0.0) {
    vec2 clickP = u_click / u_res * aspect;
    vec2 pixelP = gl_FragCoord.xy / u_res * aspect;
    float clickAge = u_time - u_clickTime;
    float radDist = length(pixelP - clickP);
    float waveFront = clickAge * 1.2;
    float inWave = smoothstep(waveFront + 0.15, waveFront - 0.1, radDist);
    inWave *= smoothstep(0.0, 0.1, clickAge) * smoothstep(3.0, 1.5, clickAge);
    float clickFlip = inWave * PI;
    flipAngle += clickFlip;
    inTransition = max(inTransition, inWave);
  }

  float cosFlip = cos(flipAngle);
  float abscos = abs(cosFlip);
  float dir = floor(u_waveDir + 0.5);
  bool flipVertical = (dir == 2.0 || dir == 3.0);

  // 3D perspective: compress tile along flip axis
  if (flipVertical) {
    f.y = (f.y - 0.5) / max(abscos, 0.04) + 0.5;
  } else {
    f.x = (f.x - 0.5) / max(abscos, 0.04) + 0.5;
  }
  float inBounds = step(0.0, f.x) * step(f.x, 1.0) * step(0.0, f.y) * step(f.y, 1.0);
  tMask *= inBounds;

  // Back side: cosFlip < 0
  float isBack = step(cosFlip, 0.0);

  // Rotate normal around flip axis (Y for horizontal, X for vertical)
  float sinFlip = sin(flipAngle);
  vec3 flippedN;
  if (flipVertical) {
    flippedN = vec3(N.x, N.y * cosFlip + N.z * sinFlip, -N.y * sinFlip + N.z * cosFlip);
  } else {
    flippedN = vec3(N.x * cosFlip + N.z * sinFlip, N.y, -N.x * sinFlip + N.z * cosFlip);
  }
  N = normalize(mix(N, flippedN, u_animMode));

  // Back side: generate fresh normal facing camera with different variation
  if (isBack > 0.5) {
    vec3 backN = tileNormal(id + 500.0);
    float backRough = tileRoughness(f, id + 500.0);
    backN = normalize(backN + vec3(
      (backRough - 0.5) * 0.15,
      (noise(f * 14.0 + id * 3.7) - 0.5) * 0.15,
      0.0
    ));
    N = backN;
    roughness = backRough;
  }

  // ── Moving light sources ──
  // Light 1: main overhead sweep (slow figure-eight)
  vec3 light1Pos = vec3(
    aspect.x * 0.5 + sin(t * 0.7) * aspect.x * 0.4,
    0.5 + cos(t * 0.53) * 0.4,
    0.8 + sin(t * 0.31) * 0.15
  );

  // Light 2: secondary, slower, offset orbit
  vec3 light2Pos = vec3(
    aspect.x * 0.5 + cos(t * 0.43 + 2.0) * aspect.x * 0.35,
    0.5 + sin(t * 0.37 + 1.5) * 0.35,
    0.7 + cos(t * 0.29) * 0.1
  );

  // Light 3: gentle background fill, very slow
  vec3 light3Pos = vec3(
    aspect.x * 0.5 + sin(t * 0.19 + 4.0) * aspect.x * 0.25,
    0.5 + cos(t * 0.23 + 3.0) * 0.25,
    1.2
  );

  // ── Per-tile specular calculation ──
  vec3 tileWorldPos = vec3(p, 0.0);
  vec3 viewDir = normalize(vec3(aspect.x * 0.5, 0.5, 1.5) - tileWorldPos);

  // Light 1 specular
  vec3 L1 = normalize(light1Pos - tileWorldPos);
  vec3 H1 = normalize(L1 + viewDir);
  float NdotH1 = max(dot(N, H1), 0.0);
  float spec1 = pow(NdotH1, 80.0 + tileHash * 60.0);
  float diff1 = max(dot(N, L1), 0.0);

  // Light 2 specular
  vec3 L2 = normalize(light2Pos - tileWorldPos);
  vec3 H2 = normalize(L2 + viewDir);
  float NdotH2 = max(dot(N, H2), 0.0);
  float spec2 = pow(NdotH2, 60.0 + tileHash2 * 80.0);
  float diff2 = max(dot(N, L2), 0.0);

  // Light 3 specular (broader, softer)
  vec3 L3 = normalize(light3Pos - tileWorldPos);
  vec3 H3 = normalize(L3 + viewDir);
  float NdotH3 = max(dot(N, H3), 0.0);
  float spec3 = pow(NdotH3, 30.0 + tileHash3 * 20.0);
  float diff3 = max(dot(N, L3), 0.0);

  // Combined specular
  float specTotal = spec1 * 1.2 + spec2 * 0.9 + spec3 * 0.4;
  float diffTotal = diff1 * 0.5 + diff2 * 0.35 + diff3 * 0.25;

  // ── Slow breathing / pulsing ──
  float breathe = 1.0 + sin(t * 0.6) * 0.08 + sin(t * 0.37 + 1.0) * 0.05;
  specTotal *= breathe;
  diffTotal *= breathe;

  // ── Wave flip: 3D shading + golden flash on back side ──
  float flipFlash = isBack * smoothstep(0.3, 0.7, inTransition);
  float flipGlow = inTransition * inTransition * 0.3;

  // ── Per-tile shimmer (individual tiles catch light at random moments) ──
  float shimmerPhase = tileHash * TAU + t * (0.8 + tileHash2 * 1.5);
  float shimmer = pow(max(sin(shimmerPhase), 0.0), 16.0);
  // Second shimmer layer for more organic feel
  float shimmer2Phase = tileHash3 * TAU + t * (0.5 + tileHash * 0.7) + 2.0;
  float shimmer2 = pow(max(sin(shimmer2Phase), 0.0), 24.0);
  // Blend shimmer: reduce original shimmer when in wave flip mode
  float shimmerBlend = 1.0 - u_animMode;
  float shimmerTotal = (shimmer * 0.6 + shimmer2 * 0.4) * shimmerBlend;

  // ── Gold color palette ──
  vec3 groutColor = vec3(0.03, 0.02, 0.01);
  vec3 darkGold   = vec3(0.12, 0.09, 0.05);
  vec3 medGold    = vec3(0.45, 0.32, 0.14);
  vec3 brightGold = vec3(0.78, 0.58, 0.24);
  vec3 flashGold  = vec3(1.0, 0.85, 0.55);
  vec3 hotGold    = vec3(1.0, 0.95, 0.80);

  // ── Per-tile base color variation ──
  // Each tile has a slightly different base tone
  float baseVar = tileHash;
  vec3 tileBase = mix(darkGold, medGold, smoothstep(0.0, 0.5, baseVar));
  tileBase = mix(tileBase, brightGold, smoothstep(0.5, 0.85, baseVar));

  // Subtle warm/cool variation per tile
  tileBase *= 0.9 + tileHash2 * 0.2;

  // ── Build tile color with lighting ──
  vec3 tileColor = tileBase;

  // Diffuse lighting adds warmth
  tileColor += tileBase * diffTotal * 0.6;

  // Specular highlights: gold to white-hot
  vec3 specColor = mix(brightGold, flashGold, smoothstep(0.0, 0.5, specTotal));
  specColor = mix(specColor, hotGold, smoothstep(0.5, 1.0, specTotal));
  tileColor += specColor * specTotal * 1.4;

  // Shimmer flashes (brief bright catches)
  vec3 shimmerColor = mix(flashGold, hotGold, shimmerTotal);
  tileColor += shimmerColor * shimmerTotal * 0.7;

  // ── Wave flip: 3D depth shading ──
  float flipShade = mix(1.0, abscos * 0.7 + 0.3, inTransition);
  tileColor *= flipShade;
  // Back side: warmer golden tint to differentiate front/back
  tileColor = mix(tileColor, tileColor * vec3(1.2, 1.05, 0.85), isBack * 0.6);
  // Edge-on glow (thin bright line at the moment of flip)
  float edgeOnGlow = pow(1.0 - abscos, 4.0) * inTransition;
  tileColor += medGold * edgeOnGlow * 0.25 * u_animMode;

  // ── Micro-facet sparkle within tiles ──
  // Small bright point when roughness noise aligns with light
  float microSpec = pow(roughness, 4.0) * specTotal * 3.0;
  tileColor += flashGold * microSpec * 0.3;

  // ── Edge highlighting: tiles catch more light at beveled edges ──
  float edgeDist = min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y));
  float edgeHighlight = smoothstep(0.15, 0.05, edgeDist);
  tileColor += brightGold * edgeHighlight * (diffTotal + specTotal * 0.5) * 0.15;

  // ── Composite: tile or grout ──
  vec3 col = mix(groutColor, tileColor, tMask);

  // ── Subtle grout depth: darker where grout is deeper ──
  float groutDepth = 1.0 - tMask;
  col -= vec3(0.01, 0.008, 0.005) * groutDepth * (1.0 - smoothstep(0.0, 0.03, edgeDist));

  // ── Global warm glow: light pools that move across the wall ──
  float glow1 = smoothstep(0.7, 0.0, length(p - light1Pos.xy));
  float glow2 = smoothstep(0.6, 0.0, length(p - light2Pos.xy));
  col += medGold * glow1 * 0.06;
  col += medGold * glow2 * 0.04;

  // ── Vignette for depth and focus ──
  vec2 vigUv = uv * 2.0 - 1.0;
  float vig = 1.0 - dot(vigUv, vigUv) * 0.35;
  vig = max(vig, 0.0);
  vig = smoothstep(0.0, 1.0, vig);
  col *= 0.5 + vig * 0.5;

  // ── Tone mapping (ACES-like for rich highlights) ──
  col = col * (2.51 * col + 0.03) / (col * (2.43 * col + 0.59) + 0.14);

  // ── Slight warmth push ──
  col = pow(col, vec3(0.95, 1.0, 1.1));

  gl_FragColor = vec4(col, 1.0);
}

