  { vec2 nb = vec2( 1.0, -1.0); vec2 cid = i + nb; vec2 h = hash2(cid + vec2(200.0)); vec2 pt = nb + h * 0.75 + 0.125; pt.x += sin(t * 0.03 + h.x * 10.0) * 0.03; pt.y += cos(t * 0.025 + h.y * 10.0) * 0.03; float d = dot(pt - f, pt - f); if (d < minDist) { secondDist = minDist; minDist = d; nearestCell = cid; } else if (d < secondDist) { secondDist = d; } }
  { vec2 nb = vec2(-1.0,  0.0); vec2 cid = i + nb; vec2 h = hash2(cid + vec2(200.0)); vec2 pt = nb + h * 0.75 + 0.125; pt.x += sin(t * 0.03 + h.x * 10.0) * 0.03; pt.y += cos(t * 0.025 + h.y * 10.0) * 0.03; float d = dot(pt - f, pt - f); if (d < minDist) { secondDist = minDist; minDist = d; nearestCell = cid; } else if (d < secondDist) { secondDist = d; } }
  { vec2 nb = vec2( 0.0,  0.0); vec2 cid = i + nb; vec2 h = hash2(cid + vec2(200.0)); vec2 pt = nb + h * 0.75 + 0.125; pt.x += sin(t * 0.03 + h.x * 10.0) * 0.03; pt.y += cos(t * 0.025 + h.y * 10.0) * 0.03; float d = dot(pt - f, pt - f); if (d < minDist) { secondDist = minDist; minDist = d; nearestCell = cid; } else if (d < secondDist) { secondDist = d; } }
  { vec2 nb = vec2( 1.0,  0.0); vec2 cid = i + nb; vec2 h = hash2(cid + vec2(200.0)); vec2 pt = nb + h * 0.75 + 0.125; pt.x += sin(t * 0.03 + h.x * 10.0) * 0.03; pt.y += cos(t * 0.025 + h.y * 10.0) * 0.03; float d = dot(pt - f, pt - f); if (d < minDist) { secondDist = minDist; minDist = d; nearestCell = cid; } else if (d < secondDist) { secondDist = d; } }
  { vec2 nb = vec2(-1.0,  1.0); vec2 cid = i + nb; vec2 h = hash2(cid + vec2(200.0)); vec2 pt = nb + h * 0.75 + 0.125; pt.x += sin(t * 0.03 + h.x * 10.0) * 0.03; pt.y += cos(t * 0.025 + h.y * 10.0) * 0.03; float d = dot(pt - f, pt - f); if (d < minDist) { secondDist = minDist; minDist = d; nearestCell = cid; } else if (d < secondDist) { secondDist = d; } }
  { vec2 nb = vec2( 0.0,  1.0); vec2 cid = i + nb; vec2 h = hash2(cid + vec2(200.0)); vec2 pt = nb + h * 0.75 + 0.125; pt.x += sin(t * 0.03 + h.x * 10.0) * 0.03; pt.y += cos(t * 0.025 + h.y * 10.0) * 0.03; float d = dot(pt - f, pt - f); if (d < minDist) { secondDist = minDist; minDist = d; nearestCell = cid; } else if (d < secondDist) { secondDist = d; } }
  { vec2 nb = vec2( 1.0,  1.0); vec2 cid = i + nb; vec2 h = hash2(cid + vec2(200.0)); vec2 pt = nb + h * 0.75 + 0.125; pt.x += sin(t * 0.03 + h.x * 10.0) * 0.03; pt.y += cos(t * 0.025 + h.y * 10.0) * 0.03; float d = dot(pt - f, pt - f); if (d < minDist) { secondDist = minDist; minDist = d; nearestCell = cid; } else if (d < secondDist) { secondDist = d; } }

  float edge = sqrt(secondDist) - sqrt(minDist);
  return vec3(sqrt(minDist), edge, hash(nearestCell + vec2(200.0)));
}

// ── Kintsugi crack reveal — cracks appear, glow, heal, new ones form ──
float crackReveal(float cellHash, float t) {
  // Each crack region has its own phase
  float phase = cellHash * PI * 2.0;
  float cycle = t * 0.12;
  // Slow breathing: cracks brighten and dim on overlapping cycles
  float reveal = sin(cycle + phase) * 0.5 + 0.5;
  reveal *= sin(cycle * 0.7 + phase * 1.3) * 0.3 + 0.7;
  // Sharpen the reveal curve — more defined on/off
  reveal = smoothstep(0.15, 0.65, reveal);
  return reveal;
}

// ── Gold dust particles near cracks ──
float goldDust(vec2 p, float t, float crackProximity) {
  float dust = 0.0;
  // Layer 1: small particles
  vec2 dp1 = p * 30.0 + vec2(t * 0.2, t * 0.15);
  float d1 = noise(dp1);
  d1 = smoothstep(0.72, 0.78, d1);
  dust += d1 * 0.6;
  // Layer 2: tinier sparkles
  vec2 dp2 = p * 55.0 + vec2(-t * 0.3, t * 0.25);
  float d2 = noise(dp2);
  d2 = smoothstep(0.78, 0.82, d2);
  dust += d2 * 0.4;
  // Layer 3: rare bright motes
  vec2 dp3 = p * 18.0 + vec2(t * 0.08, -t * 0.12);
  float d3 = noise(dp3);
  d3 = smoothstep(0.82, 0.86, d3);
  // Pulsing brightness
  d3 *= 0.5 + 0.5 * sin(t * 2.0 + d3 * 20.0);
  dust += d3 * 0.8;
  // Particles only appear near cracks
  dust *= crackProximity;
  return dust;
}

void main() {
  vec2 fragCoord = gl_FragCoord.xy;
  vec2 p = (fragCoord - u_res * 0.5) / min(u_res.x, u_res.y);
  vec2 mouseShift = vec2(0.0);
  if (u_mouse.x > 0.0) {
    vec2 mNorm = (u_mouse / u_res - 0.5);
    mouseShift = -mNorm * 0.12;
  }
  float t = u_time * u_crackSpeed;

  // ────────────────────────────────────────────
  // 1. MULTI-SCALE VORONOI CRACK NETWORK
  //    Each layer shifts differently for parallax depth
  // ────────────────────────────────────────────

  // Large primary cracks — foreground, least shift
  vec3 coarse = kintsugiVoronoi((p + mouseShift * 0.8) * 2.5, t, 0.6);
  float coarseEdge = coarse.y;
  float coarseCellHash = coarse.z;

  // Medium secondary cracks — middle depth
  vec3 medium = fineVoronoi((p + mouseShift * 1.8) * 5.5, t);
  float mediumEdge = medium.y;
  float mediumCellHash = medium.z;

  // Fine hairline cracks — deepest, most shift
  vec3 micro = microVoronoi((p + mouseShift * 3.0) * 14.0, t);
  float microEdge = micro.y;

  // ────────────────────────────────────────────
  // 2. CRACK REVEAL ANIMATION
  // Cracks appear, glow bright, then heal away
  // ────────────────────────────────────────────

  float coarseReveal = crackReveal(coarseCellHash, t);
  float mediumReveal = crackReveal(mediumCellHash, t * 1.3 + 1.0);
  // Micro-cracks follow the coarse ones
  float microReveal = mix(coarseReveal, mediumReveal, 0.5);

  // ────────────────────────────────────────────
  // 3. CRACK LINE INTENSITIES
  // Narrow bright core + wide soft glow falloff
  // ────────────────────────────────────────────

  // Coarse cracks: widest gold lines
  float coarseCrack = smoothstep(0.08, 0.0, coarseEdge) * coarseReveal;
  float coarseGlow  = smoothstep(0.22, 0.0, coarseEdge) * coarseReveal;
  float coarseBloom = smoothstep(0.45, 0.0, coarseEdge) * coarseReveal;

  // Medium cracks: thinner, subtler
  float medCrack = smoothstep(0.06, 0.0, mediumEdge) * mediumReveal * 0.7;
  float medGlow  = smoothstep(0.16, 0.0, mediumEdge) * mediumReveal * 0.5;

  // Micro-cracks: hairline, very subtle
  float microCrack = smoothstep(0.04, 0.0, microEdge) * microReveal * 0.25;
  float microGlow  = smoothstep(0.10, 0.0, microEdge) * microReveal * 0.15;

  // Combined crack intensities
  float crackCore = max(coarseCrack, max(medCrack, microCrack));
  float crackGlow = max(coarseGlow, max(medGlow, microGlow));
  float crackBloom = coarseBloom;

  // ────────────────────────────────────────────
  // 4. DARK CERAMIC SURFACE
  // Subtle texture on the plates between cracks
  // ────────────────────────────────────────────

  // Base dark surface color
  vec3 darkBase = vec3(0.03, 0.025, 0.02);
  vec3 darkTex  = vec3(0.06, 0.045, 0.03);

  // Subtle ceramic grain per Voronoi cell
  float grain = fbm(p * 8.0 + coarseCellHash * 40.0);
  float fineGrain = noise(p * 30.0 + mediumCellHash * 60.0) * 0.5;

  // Surface varies subtly per plate
  float plateTone = 0.3 + grain * 0.4 + fineGrain * 0.3;
  vec3 surface = mix(darkBase, darkTex, plateTone);

  // Plate edge highlight — subtle depth cue
  vec3 plateHighlight = vec3(0.10, 0.07, 0.04);
  float edgeHighlight = smoothstep(0.5, 0.15, coarse.x) * 0.3;
  surface += plateHighlight * edgeHighlight;

  // ────────────────────────────────────────────
  // 5. GOLDEN CRACK COLORING
  // Bright molten gold core, warm amber falloff
  // ────────────────────────────────────────────

  vec3 goldCore   = vec3(1.0, 0.82, 0.55);
  vec3 goldEdge   = vec3(0.78, 0.58, 0.24);
  vec3 goldHot    = vec3(1.0, 0.92, 0.72);

  // Molten gold flowing along cracks — turbulence texture
  float flowTurb = fbm(p * 6.0 + t * vec2(0.08, -0.06));
  float flowTurb2 = fbm(p * 10.0 + t * vec2(-0.05, 0.07) + vec2(30.0));
  float moltenFlow = flowTurb * 0.6 + flowTurb2 * 0.4;

  // Gold temperature varies along the crack
  float goldTemp = crackCore * (0.6 + moltenFlow * 0.4);
  goldTemp = clamp(goldTemp, 0.0, 1.0);

  // Gold color gradient: edge -> core -> hot center
  vec3 goldColor = mix(goldEdge, goldCore, smoothstep(0.2, 0.6, goldTemp));
  goldColor = mix(goldColor, goldHot, smoothstep(0.6, 1.0, goldTemp));

  // Emissive brightness for the crack core
  float emissive = smoothstep(0.3, 1.0, crackCore);
  goldColor += goldHot * emissive * emissive * 0.5;

  // ────────────────────────────────────────────
  // 6. COMPOSITE: SURFACE + GOLD
  // ────────────────────────────────────────────

  // Warm glow cast onto surface near cracks
  vec3 warmCast = goldEdge * crackGlow * 0.4 * u_glowIntensity;
  surface += warmCast;

  // Wider bloom — very subtle amber haze near cracks
  surface += vec3(0.12, 0.08, 0.03) * crackBloom * 0.25 * u_glowIntensity;

  // Blend gold into surface where cracks exist
  float blendFactor = smoothstep(0.0, 0.12, crackCore);
  vec3 col = mix(surface, goldColor, blendFactor);

  // Additional glow layer on top (additive)
  col += goldEdge * crackGlow * 0.3 * u_glowIntensity;

  // ────────────────────────────────────────────
  // 7. GOLD DUST PARTICLES
  // Tiny floating motes near crack lines
  // ────────────────────────────────────────────

  float crackProximity = smoothstep(0.5, 0.0, coarseEdge) * coarseReveal;
  crackProximity = max(crackProximity, smoothstep(0.3, 0.0, mediumEdge) * mediumReveal * 0.5);
  float dust = goldDust(p, u_time, crackProximity);
  col += goldHot * dust * 0.35 * u_glowIntensity;

  // ────────────────────────────────────────────
  // 8. SUBSURFACE WARMTH
  // Faint gold glow beneath the surface even where cracks are fading
  // ────────────────────────────────────────────

  float subsurface = crackBloom * 0.15 * u_glowIntensity;
  col += vec3(0.08, 0.05, 0.02) * subsurface;

  // Slow global breathing — the gold pulses gently
  float breathe = sin(u_time * 0.15) * 0.08 + 0.92;
  col *= breathe;

  // ────────────────────────────────────────────
  // 9. VIGNETTE
  // ────────────────────────────────────────────

  float edgeDist = length(p * vec2(1.0, 1.1));
  float vignette = 1.0 - smoothstep(0.4, 1.3, edgeDist);
  col *= 0.5 + vignette * 0.5;

  // ────────────────────────────────────────────
  // 10. TONE MAPPING + COLOR GRADING
  // ────────────────────────────────────────────

  // Soft tone map to preserve dark mood
  col = col / (1.0 + col * 0.15);

  // Push warm — darks stay neutral, golds stay rich
  col = pow(col, vec3(0.95, 1.0, 1.1));

  // Slight contrast enhancement
  col = clamp(col, 0.0, 1.0);
  col = col * col * (3.0 - 2.0 * col) * 0.7 + col * 0.3;

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_rotationSpeed;
uniform float u_complexity;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718
#define PHI 1.6180339887

// ── Rotation matrix ──
mat2 rot(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// ── Golden color palette ──
vec3 gold(float t) {
  vec3 a = vec3(0.45, 0.32, 0.14);
  vec3 b = vec3(0.45, 0.35, 0.2);
  vec3 c = vec3(1.0, 0.8, 0.5);
  vec3 d = vec3(0.0, 0.1, 0.25);
  return a + b * cos(TAU * (c * t + d));
}

// ── Smooth repetition for SDF ──
float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

// ── Hexagonal distance ──
float hexDist(vec2 p) {
  p = abs(p);
  return max(p.x + p.y * 0.577350269, p.y * 1.154700538);
}

// ── Triangle distance ──
float triDist(vec2 p) {
  float k = sqrt(3.0);
  p.x = abs(p.x) - 1.0;
  p.y = p.y + 1.0 / k;
  if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
  p.x -= clamp(p.x, -2.0, 0.0);
  return -length(p) * sign(p.y);
}

// ── Flower of Life petal ──
float flowerPetal(vec2 p, float r) {
  float d = 1e9;
  for (int i = 0; i < 6; i++) {
    float a = float(i) * TAU / 6.0;
    vec2 c = vec2(cos(a), sin(a)) * r;
    d = min(d, length(p - c) - r);
  }
  return d;
}

// ── Star polygon ──
float starDist(vec2 p, float r, int n, float inset) {
  float an = PI / float(n);
  float en = PI / float(n);
  vec2 acs = vec2(cos(an), sin(an));
  vec2 ecs = vec2(cos(en), sin(en));
  float bn = mod(atan(p.x, p.y), 2.0 * an) - an;
  p = length(p) * vec2(cos(bn), abs(sin(bn)));
  p -= r * acs;
  p += ecs * clamp(-dot(p, ecs), 0.0, r * acs.y / ecs.y);
  return length(p) * sign(p.x);
}

// ── Sacred geometry layer compositing ──
float sacredRing(vec2 p, float radius, float width) {
  return abs(length(p) - radius) - width;
}

// ── Mandala layer ──
float mandalaLayer(vec2 uv, float time, float layer, float totalLayers) {
  float t = layer / totalLayers;
  float radius = 0.08 + t * 0.38;

  // Differential rotation — inner faster, outer slower, some counter-rotating
  float speed = u_rotationSpeed * (1.5 - t * 1.2);
  float direction = mod(layer, 2.0) < 1.0 ? 1.0 : -1.0;
  float rot_angle = time * speed * direction + layer * PHI;
  vec2 p = rot(rot_angle) * uv;

  float d = 1e9;
  float symmetry = 6.0 + floor(layer * 1.5);

  // Angular repetition for symmetry
  float angle = atan(p.y, p.x);
  float r = length(p);
  float sector = TAU / symmetry;
  float a = mod(angle + sector * 0.5, sector) - sector * 0.5;
  vec2 sp = vec2(cos(a), sin(a)) * r;

  // ── Concentric ring ──
  float ring = abs(r - radius) - 0.003 * (1.0 + t);
  d = min(d, ring);

  // ── Petal arcs (flower of life inspiration) ──
  float petalR = radius * 0.35 / PHI;
  vec2 petalCenter = vec2(radius, 0.0);
  float petal = abs(length(sp - petalCenter) - petalR) - 0.002;
  d = min(d, petal);

  // ── Inner petal arc ──
  vec2 innerPetalCenter = vec2(radius * 0.65, 0.0);
  float innerPetalR = radius * 0.25;
  float innerPetal = abs(length(sp - innerPetalCenter) - innerPetalR) - 0.0015;
  d = min(d, innerPetal);

  // ── Radial spokes ──
  float spoke = abs(sp.y) - 0.001;
  float spokeMask = smoothstep(radius - 0.05, radius - 0.01, r) * smoothstep(radius + 0.05, radius + 0.01, r);
  d = min(d, spoke / max(spokeMask, 0.001));

  // ── Hexagonal elements at intersections ──
  float hexR = 0.012 + t * 0.008;
  vec2 hexPos = vec2(radius, 0.0);
  float hex = hexDist(sp - hexPos) - hexR;
  d = min(d, hex);

  // ── Diamond/triangular detail at half-radius ──
  if (layer > 1.0) {
    vec2 triPos = vec2(radius * 0.5, 0.0);
    vec2 tp = (sp - triPos) * 60.0;
    float tri = triDist(tp) / 60.0;
    d = min(d, tri);
  }

  return d;
}

// ── Spiral arms based on golden ratio ──
float goldenSpiral(vec2 uv, float time) {
  float r = length(uv);
  float a = atan(uv.y, uv.x);

  // Golden spiral: r = PHI^(2*theta/PI)
  float spiralPhase = log(max(r, 0.001)) / log(PHI) * PI * 0.5;
  float spiralD = abs(mod(a - spiralPhase + time * u_rotationSpeed * 0.2 + PI, TAU) - PI);
  spiralD = min(spiralD, abs(mod(a - spiralPhase + time * u_rotationSpeed * 0.2 + PI + PI, TAU) - PI));

  // Fade spiral intensity with radius
  float fade = smoothstep(0.0, 0.05, r) * smoothstep(0.5, 0.35, r);
  return spiralD * fade + (1.0 - fade);
}

// ── Fractal detail — repeating at smaller scales ──
float fractalDetail(vec2 uv, float time) {
  float d = 1e9;
  float scale = 1.0;
  float intensity = 0.0;

  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    vec2 p = uv * scale;
    p = rot(time * u_rotationSpeed * (0.1 + fi * 0.05) * (mod(fi, 2.0) < 1.0 ? 1.0 : -1.0)) * p;

    // Hexagonal tiling at this scale
    float hexSize = 0.15 / scale;
    vec2 hexUV = p;
    float hx = hexDist(mod(hexUV + hexSize, hexSize * 2.0) - hexSize);
    float hexLine = abs(hx - hexSize * 0.4) - 0.001 * scale;
    intensity += smoothstep(0.003, 0.0, hexLine) * (0.15 / (1.0 + fi));

    scale *= PHI;
  }
  return intensity;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  uv = rot(u_mouse.x) * uv;
  float t = u_time;
  float complexity = u_complexity;

  // ── Accumulated glow ──
  vec3 col = vec3(0.0);
  float r = length(uv);

  // ── Object mask — keep mandala centered with dark surround ──
  float objectRadius = 0.48;
  float objectFade = smoothstep(objectRadius, objectRadius * 0.7, r);

  // ── Build sacred geometry mandala layers ──
  float totalGlow = 0.0;

  for (int i = 0; i < 8; i++) {
    if (float(i) >= complexity) break;
    float fi = float(i);
    float layerD = mandalaLayer(uv, t, fi, complexity);

    // Convert SDF to glow — sharp lines with soft bloom
    float lineGlow = 0.0025 / (abs(layerD) + 0.0025);
    float bloom = 0.008 / (abs(layerD) + 0.008) * 0.3;
    float layerIntensity = (lineGlow + bloom);

    // Color varies per layer — golden gradient from warm amber to bright gold
    float colorT = fi / complexity + t * 0.02;
    vec3 layerColor = gold(colorT);

    // Inner layers are brighter
    float brightness = 1.0 - fi / complexity * 0.5;

    col += layerColor * layerIntensity * brightness * 0.6;
    totalGlow += layerIntensity * brightness;
  }

  // ── Golden ratio spiral arms ──
  float spiral = goldenSpiral(uv, t);
  float spiralGlow = 0.015 / (spiral + 0.015);
  col += gold(0.7 + t * 0.01) * spiralGlow * 0.25;

  // ── Fractal hexagonal detail overlay ──
  float fractal = fractalDetail(uv, t);
  col += gold(0.3 + t * 0.03) * fractal * 0.4;

  // ── Central glowing point — pulses subtly ──
  float centerPulse = 0.8 + 0.2 * sin(t * 1.5);
  float centerGlow = 0.01 / (r * r + 0.01) * centerPulse;
  vec3 centerColor = vec3(1.0, 0.92, 0.7); // bright white-gold
  col += centerColor * centerGlow * 0.08;

  // ── Secondary center ring pulse ──
  float ringPulse = 0.9 + 0.1 * sin(t * 2.3 + 1.0);
  float innerRing = abs(r - 0.03 * ringPulse) - 0.002;
  float innerRingGlow = 0.003 / (abs(innerRing) + 0.003);
  col += vec3(1.0, 0.88, 0.6) * innerRingGlow * 0.3;

  // ── Outer boundary ring — ornate edge ──
  float outerRing = abs(r - objectRadius + 0.01) - 0.003;
  float outerGlow = 0.004 / (abs(outerRing) + 0.004);
  col += gold(0.5 + t * 0.015) * outerGlow * 0.35;

  // ── Second outer ring — slightly inside ──
  float outerRing2 = abs(r - objectRadius + 0.035) - 0.002;
  float outerGlow2 = 0.003 / (abs(outerRing2) + 0.003);
  col += gold(0.6) * outerGlow2 * 0.2;

  // ── Decorative dots at outer ring intersections ──
  float dotAngle = atan(uv.y, uv.x);
  float dotSymmetry = 12.0;
  float dotA = mod(dotAngle + PI / dotSymmetry, TAU / dotSymmetry) - PI / dotSymmetry;
  vec2 dotP = vec2(cos(dotA), sin(dotA)) * r;
  vec2 dotCenter = vec2(objectRadius - 0.01, 0.0);
  float dot = length(dotP - dotCenter) - 0.008;
  float dotGlow = 0.004 / (abs(dot) + 0.004);
  col += vec3(1.0, 0.9, 0.65) * dotGlow * 0.3;

  // ── Apply object mask ──
  col *= objectFade;

  // ── Subtle warm ambient radial glow behind the mandala ──
  float ambientGlow = exp(-r * r * 6.0) * 0.06;
  col += vec3(0.3, 0.2, 0.08) * ambientGlow;

  // ── Tone mapping ──
  col = col / (1.0 + col * 0.4);

  // ── Slight warmth boost ──
  col = pow(col, vec3(0.95, 0.98, 1.05));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_dripSpeed;
uniform float u_blobCount;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define MAX_BLOBS 12

// ── Hash for noise / grain ──
float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// ── Value noise ──
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// ── Smooth min for metaball blending (polynomial) ──
// k controls how smoothly the surfaces merge
float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

// ── Metaball field evaluation ──
// Returns the combined metaball field value at point p
// Uses inverse-distance "energy" formulation for classic metaball look
float metaballField(vec2 p, float t, float speed, float count) {
  float energy = 0.0;
  float numBlobs = 4.0 + count * 8.0; // 4 to 12 blobs

  // ── Emitter group 1: Rising blobs from bottom-left ──
  for (int i = 0; i < MAX_BLOBS; i++) {
    if (float(i) >= numBlobs) break;
    float fi = float(i);
    float phase = fi * 1.618 + fi * fi * 0.13; // golden-ratio spacing

    // Base position: spread across bottom, rise upward
    float riseSpeed = (0.3 + 0.4 * fract(fi * 0.618)) * speed;
    float riseCycle = mod(t * riseSpeed + phase * 0.7, 3.5) - 1.0;

    // X position: oscillate laterally as they rise
    float xBase = sin(phase * 2.39996) * 0.45;
    float xWobble = sin(t * speed * 0.8 + phase * 3.1) * 0.12;
    float xDrift = sin(riseCycle * 2.0 + phase) * 0.08;
    float bx = xBase + xWobble + xDrift;

    // Y position: rise from bottom, wrap around
    float by = -0.7 + riseCycle * 0.9;

    // Size varies per blob and pulses gently
    float baseSize = 0.04 + 0.03 * fract(phase * 0.317);
    float pulse = 1.0 + 0.15 * sin(t * speed * 1.5 + phase * 4.7);
    float radius = baseSize * pulse;

    // Metaball contribution: r^2 / d^2 formulation
    float d = length(p - vec2(bx, by));
    energy += (radius * radius) / (d * d + 0.0001);
  }

  return energy;
}

// ── Tendril field: stretched vertical noise that creates trailing wisps ──
float tendrilField(vec2 p, float t, float speed) {
  // Vertically stretched noise for upward-dripping feel
  float n1 = vnoise(vec2(p.x * 6.0, p.y * 2.0 - t * speed * 0.6) + 10.0);
  float n2 = vnoise(vec2(p.x * 12.0 + 3.7, p.y * 4.0 - t * speed * 0.8) + 20.0);
  float n3 = vnoise(vec2(p.x * 3.0 + 7.1, p.y * 1.5 - t * speed * 0.4));

  // Combine: large tendril shapes + fine detail
  float tendrils = n1 * 0.5 + n2 * 0.3 + n3 * 0.2;

  // Sharpen into tendril-like strands
  tendrils = smoothstep(0.35, 0.65, tendrils);

  // Fade tendrils toward top (they dissipate)
  tendrils *= smoothstep(0.6, -0.3, p.y);

  // Stronger at bottom where "drips" originate
  tendrils *= 0.6 + 0.4 * smoothstep(0.0, -0.5, p.y);

  return tendrils;
}

// ── Vignette ──
float vignette(vec2 uv) {
  float d = length(uv * vec2(0.9, 1.0));
  return smoothstep(1.3, 0.4, d);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / u_res.y;
  float aspect = u_res.x / u_res.y;
  float t = u_time;
  float speed = u_dripSpeed;
  float count = u_blobCount;

  // ── Background: deep dark with subtle warm radial gradient ──
  float bgDist = length(uv * vec2(0.8, 1.0));
  vec3 col = vec3(0.025, 0.018, 0.015) * (1.0 - bgDist * 0.3);
  col = max(col, vec3(0.0));

  // ── Mouse-driven drip source ──
  float mouseField = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / u_res.y;
    float mr = 0.06;
    float md = length(uv - mUV);
    mouseField = (mr * mr) / (md * md + 0.0001);
    // Add smaller orbiting blobs around mouse
    for (int i = 0; i < 3; i++) {
      float fi = float(i);
      float angle = t * speed * 1.5 + fi * 2.094;
      vec2 offset = vec2(cos(angle), sin(angle)) * 0.08;
      float smr = 0.03;
      float smd = length(uv - mUV - offset);
      mouseField += (smr * smr) / (smd * smd + 0.0001);
    }
  }

  // ── Evaluate metaball field ──
  float field = metaballField(uv, t, speed, count) + mouseField;

  // ── Tendril contribution: adds to the field ──
  float tendrils = tendrilField(uv, t, speed);

  // Combine: metaballs are the main blobs, tendrils add trailing wisps
  // tendrils contribute a fraction of metaball energy
  float combinedField = field + tendrils * 0.6;

  // ── Isosurface thresholds for layered coloring ──
  // The metaball "surface" is where field crosses a threshold
  float threshold = 1.0;

  // Outer glow: neon halo around the blob surfaces
  float outerGlow = smoothstep(threshold * 0.15, threshold * 0.5, combinedField);

  // Surface: sharper blob boundary for neon look
  float surface = smoothstep(threshold * 0.4, threshold * 0.7, combinedField);

  // Inner: brighter core inside the blobs
  float inner = smoothstep(threshold * 0.8, threshold * 1.8, combinedField);

  // Hot core: brightest center
  float core = smoothstep(threshold * 2.0, threshold * 4.0, combinedField);

  // ── Color palette: vibrant neon amber (HDR values > 1.0 for bloom) ──
  // Deep amber glow (outermost)
  vec3 glowColor = vec3(1.2, 0.55, 0.10);

  // Bright neon surface
  vec3 surfaceColor = vec3(2.5, 1.3, 0.40);

  // Intense inner
  vec3 innerColor = vec3(3.5, 2.0, 0.70);

  // White-hot core
  vec3 coreColor = vec3(5.0, 4.0, 2.5);

  // ── Compose the blob color ──
  // Start with glow — push hard for neon effect
  vec3 blobCol = glowColor * outerGlow * 1.0;

  // Add surface color
  blobCol = mix(blobCol, surfaceColor, surface * 0.95);

  // Brighten inner areas
  blobCol = mix(blobCol, innerColor, inner * 0.95);

  // Hot core highlights
  blobCol = mix(blobCol, coreColor, core * 1.0);

  // ── Surface edge highlight: rim lighting effect ──
  // Brighter at the edge of the surface (where gradient is steep)
  float edgeBand = surface * (1.0 - inner);
  blobCol += vec3(1.8, 1.0, 0.3) * edgeBand * 0.8;

  // ── Tendril coloring: slightly different from main blobs ──
  float tendrilVis = tendrils * (1.0 - surface * 0.5);
  vec3 tendrilColor = vec3(1.4, 0.7, 0.20) * tendrilVis * 0.7;
  blobCol += tendrilColor;

  // ── Add blob color to scene ──
  col += blobCol;

  // ── Ambient upward-flowing noise: background movement ──
  float ambientFlow = vnoise(vec2(uv.x * 3.0, uv.y * 1.5 - t * speed * 0.2) + 50.0);
  ambientFlow = smoothstep(0.4, 0.6, ambientFlow) * 0.06;
  col += vec3(0.2, 0.12, 0.06) * ambientFlow;

  // ── Subtle secondary blobs: small, fast, for liveliness ──
  float microField = 0.0;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float phase = fi * 2.39996 + 100.0;
    float mSpeed = (0.5 + 0.3 * fract(phase * 0.618)) * speed;
    float mCycle = mod(t * mSpeed + phase, 2.8) - 0.8;
    float mx = sin(phase * 1.7) * 0.5 + sin(t * speed + phase * 2.3) * 0.1;
    float my = -0.6 + mCycle * 0.8;
    float mr = 0.015 + 0.01 * sin(t * speed * 2.0 + phase);
    float md = length(uv - vec2(mx, my));
    microField += (mr * mr) / (md * md + 0.0001);
  }
  float microSurface = smoothstep(0.8, 1.5, microField);
  float microCore = smoothstep(1.5, 3.0, microField);
  col += vec3(1.8, 1.0, 0.30) * microSurface * 0.7;
  col += vec3(3.0, 2.2, 1.0) * microCore * 0.8;

  // ── Film grain ──
  float grain = (hash(gl_FragCoord.xy + fract(t * 43.758) * 1000.0) - 0.5) * 0.025;
  col += grain;

  // ── Vignette ──
  col *= vignette(uv);

  // ── Tone mapping: ACES filmic (preserves bright neon punch) ──
  col = max(col, vec3(0.0));
  col = col * (2.51 * col + 0.03) / (col * (2.43 * col + 0.59) + 0.14);
  col = pow(col, vec3(0.90));

  // ── Warm shadow push ──
  float lum = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(col, col * vec3(1.06, 0.97, 0.90), smoothstep(0.05, 0.0, lum) * 0.3);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_rippleSpeed;
uniform float u_moonGlow;
uniform vec2 u_mouse;
uniform float u_tilt;
uniform float u_waves;

#define PI 3.14159265359
#define WAVE_LAYERS 7

// ── Multi-directional waves with analytical normals ──
vec4 sea(vec2 p, float t) {
  float h = 0.0;
  vec2 dh = vec2(0.0);
  float freq = 1.0;
  float baseAmp = 0.2 * u_waves;
  // Higher intensity = slower amplitude decay = more high-freq energy (choppier)
  float decay = mix(0.55, 0.38, clamp(u_waves / 3.0, 0.0, 1.0));
  float amp = baseAmp;
  float angle = 0.0;
  for (int i = 0; i < WAVE_LAYERS; i++) {
    float c = cos(angle);
    float s = sin(angle);
    // Rotate sampling position per layer (breaks alignment)
    vec2 pp = vec2(c * p.x + s * p.y, -s * p.x + c * p.y);
    float fi = float(i);
    float spd = sqrt(freq) * 0.8;
    // Sample along y of rotated space + per-layer offset
    float phase = (pp.y + fi) * freq - t * spd;
    float sn = sin(phase);
    float cn = cos(phase);
    h += sn * amp;
    // Derivative in rotated space, then rotate back
    float dy = freq * amp * cn;
    dh += vec2(-s * dy, c * dy);
    angle += fi + 1.2;
    freq *= 1.3;
    amp *= decay;
  }
  vec3 N = normalize(vec3(-dh.x, 1.0, -dh.y));
  return vec4(h, N);
}

// ── Moon direction in 3D ──
vec3 moonDir() {
  return normalize(vec3(0.15, 0.35, 1.0));
}

// Simple hash for moon texture
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// ── Night sky color with textured moon disc ──
vec3 skyColor(vec3 rd) {
  vec3 md = moonDir();
  // Warm base tones — blue scheme hue-rotates these to cool moonlit blue
  vec3 skyDark = vec3(0.06, 0.03, 0.02);
  vec3 skyHoriz = vec3(0.09, 0.05, 0.04);
  vec3 sky = mix(skyHoriz, skyDark, max(rd.y, 0.0));
  vec3 moonCol = vec3(0.98, 0.92, 0.85);
  float moonDot = max(dot(rd, md), 0.0);
  float moonAngle = acos(clamp(moonDot, 0.0, 1.0));
  float moonRadius = 0.04;
  float disc = smoothstep(moonRadius, moonRadius * 0.7, moonAngle);
  // Crater texture — project rd onto moon-tangent plane
  if (disc > 0.0) {
    vec3 up = vec3(0.0, 1.0, 0.0);
    vec3 right = normalize(cross(up, md));
    vec3 mup = cross(md, right);
    vec2 muv = vec2(dot(rd - md, right), dot(rd - md, mup)) * 25.0;
    float crater = hash(floor(muv * 2.0)) * 0.25;
    crater += hash(floor(muv * 4.0)) * 0.15;
    float darkening = 1.0 - crater * smoothstep(moonRadius * 0.9, moonRadius * 0.4, moonAngle);
    // Slight limb darkening
    float limb = smoothstep(0.0, moonRadius, moonAngle);
    darkening *= mix(1.0, 0.7, limb * limb);
    sky += moonCol * disc * 0.85 * darkening;
  }
  // Bloom (scales with moonGlow, disc does not)
  sky += moonCol * 0.25 * pow(moonDot, 40.0) * u_moonGlow;
  sky += moonCol * 1.2 * pow(moonDot, 400.0) * u_moonGlow;
  return sky;
}

void main() {
  float aspect = u_res.x / u_res.y;
  vec2 uv = -1.0 + 2.0 * gl_FragCoord.xy / u_res;
  uv.x *= aspect;
  float t = u_time * u_rippleSpeed;

  // ── 3D Camera — tilt: 0=horizontal, 0.5=default, 1=top-down ──
  float tiltRad = u_tilt * 0.7;
  vec3 ro = vec3(0.0, 8.0, 0.0);
  vec3 ww = normalize(vec3(0.0, -sin(tiltRad), cos(tiltRad)));
  vec3 uu = normalize(cross(vec3(0.0, 1.0, 0.0), ww));
  vec3 vv = normalize(cross(ww, uu));
  vec3 rd = normalize(uv.x * uu + uv.y * vv + 2.5 * ww);

  vec3 md = moonDir();
  vec3 moonCol = vec3(0.98, 0.92, 0.85);

  // ── Sky (above horizon) ──
  vec3 sky = skyColor(rd);
  vec3 col = sky;

  // ── Ray-plane intersection (water at y=0) ──
  float dsea = -ro.y / rd.y;

  if (dsea > 0.0) {
    vec3 wp = ro + dsea * rd;

    // ── Sample waves ──
    vec4 s = sea(wp.xz, t);
    float h = s.x;
    vec3 nor = s.yzw;

    // ── Mouse ripple — concentric rings that affect normals ──
    if (u_mouse.x > 0.0) {
      vec2 mUV = -1.0 + 2.0 * u_mouse / u_res;
      mUV.x *= aspect;
      vec3 mrd = normalize(mUV.x * uu + mUV.y * vv + 2.5 * ww);
      float mdsea = -ro.y / mrd.y;
      if (mdsea > 0.0) {
        vec3 mwp = ro + mdsea * mrd;
        vec2 mdelta = wp.xz - mwp.xz;
        float md2 = length(mdelta);
        float mfreq = 4.0;
        float mphase = md2 * mfreq - t * 5.0;
        float mamp = exp(-md2 * 0.15) * 0.4 * u_waves;
        h += sin(mphase) * mamp;
        // Analytical normal contribution from mouse ripple
        float mcos = cos(mphase) * mamp * mfreq;
        vec2 mgrad = md2 > 0.01 ? (mdelta / md2) * mcos : vec2(0.0);
        nor = normalize(nor + vec3(-mgrad.x, 0.0, -mgrad.y) * 2.0);
      }
    }
    // Flatten normal with distance (perspective detail fade)
    nor = mix(nor, vec3(0.0, 1.0, 0.0), smoothstep(0.0, 300.0, dsea));

    // ── Fresnel ──
    float fre = clamp(1.0 - dot(-nor, rd), 0.0, 1.0);
    fre = pow(fre, 3.0);

    // ── Diffuse moonlight ──
    float dif = mix(0.25, 1.0, max(dot(nor, md), 0.0));

    // ── Reflection & refraction ──
    vec3 refl = skyColor(reflect(rd, nor));
    vec3 seaCol1 = vec3(0.05, 0.02, 0.01);
    vec3 seaCol2 = vec3(0.10, 0.06, 0.04);
    vec3 refr = seaCol1 + dif * moonCol * seaCol2 * 0.15 * u_moonGlow;

    col = mix(refr, 0.9 * refl, fre);

    // ── Wave crest highlight ──
    float atten = max(1.0 - dsea * dsea * 0.0005, 0.0);
    col += seaCol2 * (wp.y - h) * 1.5 * atten;

    // ── Distance fog (fade to sky at horizon) ──
    col = mix(col, sky, 1.0 - exp(-0.008 * dsea));
  }

  // ── Gamma ──
  col = pow(max(col, vec3(0.0)), vec3(0.85));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_coronaSize;
uniform float u_rayIntensity;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash for star field and grain ──
float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// ── Value noise ──
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// ── FBM for corona rays (3 octaves, cheap) ──
float fbm3(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 3; i++) {
    v += a * vnoise(p);
    p = rot * p * 2.1 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}

// ── FBM 4 octaves for finer detail ──
float fbm4(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.866, 0.5, -0.5, 0.866);
  for (int i = 0; i < 4; i++) {
    v += a * vnoise(p);
    p = rot * p * 2.05 + vec2(3.1, 7.4);
    a *= 0.48;
  }
  return v;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  float t = u_time;
  float coronaSize = u_coronaSize;
  float rayIntensity = u_rayIntensity;

  // ── Polar coordinates ──
  float r = length(uv);
  float a = atan(uv.y, uv.x);

  // ── Background: deep space ──
  vec3 col = vec3(0.005, 0.003, 0.008);

  // ── Star field — sparse hash-based points ──
  vec2 starGrid = floor(gl_FragCoord.xy / 3.0);
  float starHash = hash(starGrid * 0.73 + vec2(13.7, 29.3));
  float starBright = step(0.997, starHash);
  // Twinkle
  float twinkle = sin(t * 1.5 + starHash * 100.0) * 0.4 + 0.6;
  starBright *= twinkle * hash(starGrid * 1.31 + vec2(7.1, 3.9));
  // Fade stars near corona
  starBright *= smoothstep(0.15, 0.45, r);
  col += vec3(0.7, 0.75, 0.9) * starBright * 0.6;

  // ── Eclipse disc parameters ──
  float discRadius = 0.15;
  float chromoRadius = discRadius + 0.008;

  // ── Slow corona rotation ──
  float rotAngle = a + t * 0.05;

  // ── Corona ray noise — multiple octaves at different speeds ──
  // Octave 1: broad rays, slow
  float ray1 = fbm3(vec2(rotAngle * 3.0, r * 4.0 - t * 0.08));
  // Octave 2: medium detail, medium speed
  float ray2 = fbm3(vec2(rotAngle * 7.0 + 5.0, r * 6.0 - t * 0.12));
  // Octave 3: fine streaks, faster
  float ray3 = fbm4(vec2(rotAngle * 13.0 + 10.0, r * 8.0 - t * 0.18));

  // Combine rays with weighting
  float rays = ray1 * 0.5 + ray2 * 0.3 + ray3 * 0.2;

  // ── Angular asymmetry — corona streamers vary in length ──
  float asymmetry = 0.7 + 0.3 * sin(a * 2.0 + 0.5) * sin(a * 3.0 + t * 0.02);
  asymmetry += 0.15 * sin(a * 5.0 + 1.7);
  rays *= asymmetry;

  // ── Radial falloff for corona ──
  float coronaOuter = discRadius + 0.35 * coronaSize;
  float radialFalloff = smoothstep(coronaOuter, discRadius + 0.02, r);
  radialFalloff *= smoothstep(discRadius - 0.01, discRadius + 0.03, r);

  // ── Extended ray reach — rays extend further than base corona ──
  float rayReach = discRadius + 0.6 * coronaSize;
  float rayFalloff = smoothstep(rayReach, discRadius + 0.03, r);
  rayFalloff *= smoothstep(discRadius - 0.01, discRadius + 0.03, r);

  // ── Corona color gradient: warm amber inner to deep orange outer ──
  float colorMix = smoothstep(discRadius, coronaOuter, r);
  vec3 innerColor = vec3(1.0, 0.75, 0.30);
  vec3 outerColor = vec3(0.8, 0.35, 0.08);
  vec3 coronaColor = mix(innerColor, outerColor, colorMix);

  // ── Apply corona base glow ──
  float coronaGlow = radialFalloff * (0.4 + rays * 0.6);
  col += coronaColor * coronaGlow * 1.2 * rayIntensity;

  // ── Apply extended ray streaks ──
  float rayStreak = rayFalloff * pow(rays, 1.5) * 0.8;
  col += mix(coronaColor, outerColor, 0.5) * rayStreak * rayIntensity;

  // ── Bright inner corona ring (chromosphere) ──
  float chromoDist = abs(r - chromoRadius);
  float chromo = exp(-chromoDist * chromoDist / 0.00008);
  // Modulate with subtle noise for unevenness
  float chromoNoise = fbm3(vec2(rotAngle * 10.0, t * 0.2));
  chromo *= 0.7 + chromoNoise * 0.5;
  vec3 chromoColor = vec3(1.0, 0.85, 0.5);
  col += chromoColor * chromo * 2.5 * rayIntensity;

  // ── Hot inner edge — very tight bright ring ──
  float innerEdge = exp(-pow((r - discRadius) * 80.0, 2.0));
  innerEdge *= smoothstep(discRadius - 0.02, discRadius + 0.005, r);
  col += vec3(1.0, 0.95, 0.8) * innerEdge * 3.0;

  // ── Solar wind — fine radial streaks via cheap hash ──
  float windA = floor((a + t * 0.02) * 80.0);
  float windR2 = floor((r - t * 0.06) * 100.0);
  float wind = hash(vec2(windA, windR2));
  wind = smoothstep(0.95, 1.0, wind);
  float windFade = smoothstep(discRadius, discRadius + 0.05, r);
  windFade *= smoothstep(rayReach + 0.08, discRadius + 0.06, r);
  col += vec3(1.0, 0.85, 0.55) * wind * windFade * 0.06 * rayIntensity;

  // ── Bloom / lens flare ──
  // Soft wide glow around the corona
  float bloomDist = max(r - discRadius, 0.0);
  float bloom = exp(-bloomDist * 2.5);
  bloom *= smoothstep(discRadius - 0.05, discRadius + 0.01, r);
  col += vec3(0.4, 0.25, 0.1) * bloom * 0.25 * rayIntensity;

  // Very wide subtle bloom
  float wideBloom = exp(-r * 1.2) * 0.15;
  col += vec3(0.3, 0.18, 0.06) * wideBloom * rayIntensity;

  // Horizontal lens streak — soft and wide, not a sharp line
  float streak = exp(-uv.y * uv.y * 80.0) * exp(-abs(r - discRadius) * 5.0);
  streak *= smoothstep(discRadius - 0.02, discRadius + 0.05, r);
  col += vec3(0.6, 0.4, 0.2) * streak * 0.08 * rayIntensity;

  // ── Dark moon disc ──
  float disc = smoothstep(discRadius + 0.003, discRadius - 0.003, r);
  col *= 1.0 - disc;
  // Very faint lunar surface noise
  float lunarNoise = vnoise(uv * 40.0) * 0.008;
  col += vec3(lunarNoise * 0.5, lunarNoise * 0.4, lunarNoise * 0.3) * disc;

  // ── Diamond ring effect — follows cursor when active ──
  float diamondAngle = sin(t * 0.02) * PI;
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    diamondAngle = atan(mUV.y, mUV.x);
  }
  vec2 diamondDir = vec2(cos(diamondAngle), sin(diamondAngle));
  float diamondDot = dot(normalize(uv), diamondDir);
  float diamond = smoothstep(0.96, 1.0, diamondDot);
  float diamondR = smoothstep(discRadius + 0.025, discRadius, r);
  diamondR *= smoothstep(discRadius - 0.015, discRadius, r);
  float diamondGlow = diamond * diamondR;
  float diamondBoost = u_mouse.x > 0.0 ? 2.5 : 1.5;
  col += vec3(1.0, 0.95, 0.8) * diamondGlow * diamondBoost * rayIntensity;
  // Diamond bloom — soft radial spread
  float dBloomR = exp(-pow((r - discRadius) * 20.0, 2.0));
  float dBloomA = smoothstep(0.92, 1.0, diamondDot);
  col += vec3(0.5, 0.35, 0.15) * dBloomR * dBloomA * (diamondBoost * 0.4) * rayIntensity;

  // ── Mouse: corona brightens toward cursor direction ──
  if (u_mouse.x > 0.0) {
    float angleToCursor = dot(normalize(uv), diamondDir);
    float coronaPull = smoothstep(0.3, 1.0, angleToCursor);
    coronaPull *= smoothstep(discRadius, discRadius + 0.25, r);
    coronaPull *= smoothstep(0.6, discRadius + 0.05, r);
    col += vec3(0.8, 0.55, 0.25) * coronaPull * 0.15 * rayIntensity;
  }

  // ── Film grain ──
  float grain = (hash(gl_FragCoord.xy + fract(t * 43.0) * 1000.0) - 0.5) * 0.015;
  col += grain;

  // ── Vignette — darker sky away from corona ──
  float vig = 1.0 - smoothstep(0.3, 1.1, r);
  col *= 0.7 + 0.3 * vig;

  // ── Tone mapping — keep blacks deep ──
  col = max(col, vec3(0.0));
  // Soft highlight compression
  col = col / (1.0 + col * 0.3);
  // Slight warm push in shadows
  float lum = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(col, col * vec3(1.06, 0.97, 0.90), smoothstep(0.05, 0.0, lum) * 0.2);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_rotationSpeed;
uniform float u_brilliance;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Rotation matrix ──
mat2 rot(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// ── Hash for randomness ──
float hash(vec2 p) {
  p = fract(p * vec2(443.897, 441.423));
  p += dot(p, p.yx + 19.19);
  return fract((p.x + p.y) * p.x);
}

// ── Smooth noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── Hexagonal distance field ──
// Returns (cell center distance, cell ID) for Voronoi-like facets
vec4 hexGrid(vec2 p) {
  // Hexagonal grid constants
  vec2 s = vec2(1.0, 1.7320508); // 1, sqrt(3)
  vec2 h = s * 0.5;

  // Two offset grids
  vec2 a = mod(p, s) - h;
  vec2 b = mod(p - h, s) - h;

  // Pick closest center
  vec2 ga = dot(a, a) < dot(b, b) ? a : b;
  vec2 cellId = p - ga;

  // Hex distance
  vec2 ab = abs(ga);
  float hexDist = max(dot(ab, normalize(vec2(1.0, 1.7320508))), ab.x);

  return vec4(ga, hexDist, hash(cellId));
}

// ── Triangular grid for facet patterns ──
float triGrid(vec2 p) {
  vec2 q = vec2(p.x + p.y * 0.57735, p.y * 1.1547);
  vec2 i = floor(q);
  vec2 f = fract(q);
  float triId = step(f.x + f.y, 1.0);
  float edge = min(min(f.x, f.y), abs(1.0 - f.x - f.y));
  return edge;
}

// ── Diamond facet SDF — brilliant cut top-down view ──
// Concentric facet rings like a real brilliant-cut diamond
float brilliantFacets(vec2 uv, float time) {
  float r = length(uv);
  float a = atan(uv.y, uv.x);

  // Table facet (center octagon)
  float table = smoothstep(0.12, 0.11, r);

  // Star facets (8-fold, inner ring)
  float starAngle = mod(a + PI / 8.0, PI / 4.0) - PI / 8.0;
  float starR = r - 0.18;
  float star = abs(starAngle) * 8.0 / PI;
  float starEdge = smoothstep(0.01, 0.0, abs(starR) - star * 0.08);

  // Kite facets (8-fold, main crown)
  float kiteAngle = mod(a, PI / 4.0) - PI / 8.0;
  float kiteEdge = smoothstep(0.01, 0.0, abs(kiteAngle) * r * 6.0 - 0.02);
  float kiteRing = smoothstep(0.01, 0.0, abs(r - 0.28) - 0.005);

  // Upper girdle facets (16-fold)
  float ugAngle = mod(a, PI / 8.0) - PI / 16.0;
  float ugEdge = smoothstep(0.01, 0.0, abs(ugAngle) * r * 10.0 - 0.02);
  float ugRing = smoothstep(0.01, 0.0, abs(r - 0.38) - 0.005);

  // Girdle outline
  float girdle = smoothstep(0.01, 0.0, abs(r - 0.45) - 0.008);

  // Combine facet edges
  float edges = max(max(starEdge, kiteEdge), max(ugEdge, girdle));
  edges = max(edges, kiteRing);
  edges = max(edges, ugRing);

  // Radial lines every 22.5 degrees (16-fold symmetry)
  float radial16 = mod(a, PI / 8.0) - PI / 16.0;
  float radLine16 = smoothstep(0.008, 0.0, abs(radial16) * r * 4.0 - 0.004);
  radLine16 *= step(0.12, r) * step(r, 0.46);

  // Radial lines every 45 degrees (8-fold)
  float radial8 = mod(a + PI / 8.0, PI / 4.0) - PI / 8.0;
  float radLine8 = smoothstep(0.006, 0.0, abs(radial8) * r * 5.0 - 0.003);
  radLine8 *= step(0.12, r) * step(r, 0.46);

  edges = max(edges, max(radLine16 * 0.5, radLine8));

  return edges;
}

// ── Prismatic spectral color from wavelength ──
// More physically-based spectral mapping for diamond fire
vec3 spectral(float t) {
  t = fract(t);
  vec3 c = vec3(0.0);
  // Red
  c.r = smoothstep(0.0, 0.15, t) - smoothstep(0.35, 0.5, t);
  c.r += smoothstep(0.8, 0.95, t);
  // Green
  c.g = smoothstep(0.15, 0.35, t) - smoothstep(0.55, 0.75, t);
  // Blue
  c.b = smoothstep(0.4, 0.6, t) - smoothstep(0.75, 0.95, t);
  // Boost intensity — vivid saturated spectral fire
  c = pow(c, vec3(0.6));
  return c * 3.0;
}

// ── Diamond caustic: light concentration through faceted refraction ──
float diamondCaustic(vec2 uv, float time, float scale, float rotation) {
  vec2 p = rot(rotation) * uv * scale;

  // Hexagonal Voronoi for facet structure
  vec4 hex = hexGrid(p);
  float cellRand = hex.w;

  // Each facet refracts light at its own angle
  // The refraction angle changes slowly as the diamond "rotates"
  float facetAngle = cellRand * TAU + time * 0.3;
  vec2 refract = vec2(cos(facetAngle), sin(facetAngle)) * 0.3;

  // Displaced coordinates — where light ends up after refraction
  vec2 displaced = p + refract * (1.0 + 0.5 * sin(time * 0.7 + cellRand * 10.0));

  // Second layer of facet structure on displaced coords
  vec4 hex2 = hexGrid(displaced * 1.5);

  // Caustic brightness = how much the mapping compresses space
  // Bright where multiple input rays converge to same output point
  float edgeDist = hex.z;
  float caustic = 1.0 - smoothstep(0.0, 0.4, edgeDist);

  // Sharp bright folds from displaced field
  float fold = 1.0 - smoothstep(0.0, 0.25, hex2.z);
  fold = pow(fold, 2.0);

  // Interference between original and refracted patterns
  float interference = sin(displaced.x * 8.0 + time * 0.5) * sin(displaced.y * 8.0 - time * 0.4);
  interference = pow(abs(interference), 1.5) * 0.5;

  return caustic * 0.3 + fold * 0.5 + interference * 0.2;
}

// ── Scintillation: the sparkle flashes of a diamond ──
float scintillation(vec2 uv, float time) {
  float sparkle = 0.0;

  // Multiple scales of sparkle points
  for (float i = 0.0; i < 3.0; i++) {
    float sc = 5.0 + i * 4.0;
    vec2 grid = floor(uv * sc);
    vec2 f = fract(uv * sc) - 0.5;

    float h = hash(grid + i * 100.0);
    float phase = h * TAU + time * (1.5 + h * 2.0);

    // Sharp, brief flashes — like catching light on a facet edge
    float flash = pow(max(sin(phase), 0.0), 48.0);

    // Only at the cell center
    float dist = length(f);
    float point = smoothstep(0.15, 0.0, dist);

    sparkle += flash * point * (1.0 - i * 0.25);
  }

  return sparkle;
}

// ── Star burst for bright sparkle highlights ──
float starBurst(vec2 uv, float time) {
  float r = length(uv);
  float a = atan(uv.y, uv.x);

  // 4-point star
  float star4 = pow(abs(cos(a * 2.0)), 64.0) / (r * 20.0 + 1.0);
  // 6-point star
  float star6 = pow(abs(cos(a * 3.0)), 64.0) / (r * 25.0 + 1.0);

  return (star4 + star6 * 0.5) * smoothstep(0.5, 0.0, r);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  if (u_mouse.x > 0.0) {
    vec2 mNorm = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    uv += (mNorm - uv) * 0.2;
  }
  float t = u_time;
  float rotSpeed = u_rotationSpeed;
  float brilliance = u_brilliance;

  // ── Gentle overall rotation to simulate diamond turning in light ──
  float globalRot = t * rotSpeed * 0.1;
  vec2 uvRot = rot(globalRot) * uv;

  // ════════════════════════════════════════════
  // LAYER 1: Faceted crystalline geometry
  // The underlying diamond structure
  // ════════════════════════════════════════════

  // Brilliant-cut facet pattern (subtle structural overlay)
  float facetPattern = brilliantFacets(uvRot * 2.2, t);

  // Triangular facet grid at multiple scales
  float tri1 = triGrid(rot(t * 0.05) * uv * 8.0);
  float tri2 = triGrid(rot(-t * 0.07 + 1.0) * uv * 12.0);
  float triEdges = smoothstep(0.04, 0.0, tri1) * 0.3 + smoothstep(0.03, 0.0, tri2) * 0.15;

  // Hexagonal facet structure — very subtle, just edge hints
  vec4 mainHex = hexGrid(rot(t * 0.06) * uv * 6.0);
  float hexEdges = smoothstep(0.44, 0.40, mainHex.z) - smoothstep(0.40, 0.36, mainHex.z);
  float hexOutline = smoothstep(0.45, 0.43, mainHex.z) - smoothstep(0.43, 0.41, mainHex.z);

  // ════════════════════════════════════════════
  // LAYER 2: Caustic light patterns — the "fire"
  // Light concentrating through faceted refraction
  // ════════════════════════════════════════════

  // Multiple caustic layers at different scales and rotations
  // Simulates light from crown facets, pavilion facets, and girdle
  float c1 = diamondCaustic(uv, t, 3.0, t * rotSpeed * 0.15);
  float c2 = diamondCaustic(uv, t * 1.1 + 10.0, 5.0, -t * rotSpeed * 0.12 + PI * 0.3);
  float c3 = diamondCaustic(uv, t * 0.9 + 20.0, 8.0, t * rotSpeed * 0.08 + PI * 0.7);

  float caustics = c1 * 0.5 + c2 * 0.3 + c3 * 0.2;
  caustics = pow(caustics, 1.3) * 3.5;

  // ════════════════════════════════════════════
  // LAYER 3: Chromatic dispersion — prismatic rainbow
  // Each wavelength refracts at a different angle
  // ════════════════════════════════════════════

  // Sample caustics with wavelength-dependent offsets
  // This creates the rainbow fringing that diamonds are famous for
  float dispersion = 0.018 * (1.0 + caustics * 0.3);
  float dispAngle = t * rotSpeed * 0.3 + atan(uv.y, uv.x) * 0.5;

  // Red channel — longest wavelength, least refraction
  vec2 rOff = vec2(cos(dispAngle), sin(dispAngle)) * dispersion;
  float cR = diamondCaustic(uv + rOff, t, 3.0, t * rotSpeed * 0.15);
  cR += diamondCaustic(uv + rOff, t * 1.1 + 10.0, 5.0, -t * rotSpeed * 0.12 + PI * 0.3) * 0.6;

  // Green channel — middle wavelength
  vec2 gOff = vec2(cos(dispAngle + TAU / 3.0), sin(dispAngle + TAU / 3.0)) * dispersion;
  float cG = diamondCaustic(uv + gOff, t, 3.0, t * rotSpeed * 0.15);
  cG += diamondCaustic(uv + gOff, t * 1.1 + 10.0, 5.0, -t * rotSpeed * 0.12 + PI * 0.3) * 0.6;

  // Blue channel — shortest wavelength, most refraction
  vec2 bOff = vec2(cos(dispAngle + TAU * 2.0 / 3.0), sin(dispAngle + TAU * 2.0 / 3.0)) * dispersion;
  float cB = diamondCaustic(uv + bOff, t, 3.0, t * rotSpeed * 0.15);
  cB += diamondCaustic(uv + bOff, t * 1.1 + 10.0, 5.0, -t * rotSpeed * 0.12 + PI * 0.3) * 0.6;

  // Chromatic difference — where colors separate, we see rainbow
  vec3 chromatic = vec3(cR, cG, cB);
  float chrDiff = abs(cR - cG) + abs(cG - cB) + abs(cB - cR);

  // ════════════════════════════════════════════
  // LAYER 4: Spectral fire — the colored flashes
  // ════════════════════════════════════════════

  // Phase-based spectral color at each point
  float specPhase = atan(cR - cG, cG - cB) / TAU + 0.5;
  specPhase += t * 0.03 + length(uv) * 0.5;
  vec3 fireColor = spectral(specPhase);

  // Second spectral layer — broader patches of color
  float specPhase2 = noise(uvRot * 3.0 + t * 0.2) + t * 0.05;
  vec3 fireColor2 = spectral(specPhase2);

  // ════════════════════════════════════════════
  // LAYER 5: Scintillation — point sparkles
  // ════════════════════════════════════════════

  float sparkle = scintillation(uvRot, t * rotSpeed);

  // Star bursts at bright caustic nodes
  float starTotal = 0.0;
  for (float i = 0.0; i < 4.0; i++) {
    float sc = 4.0 + i * 3.0;
    vec2 grid = floor(rot(i * 0.7 + t * 0.03) * uv * sc);
    vec2 center = (grid + 0.5) / sc;
    center = rot(-i * 0.7 - t * 0.03) * center;
    float h = hash(grid + i * 77.0);
    float phase = h * TAU + t * (1.0 + h);
    float flash = pow(max(sin(phase), 0.0), 24.0);
    float star = starBurst((uv - center) * sc * 0.8, t) * flash;
    starTotal += star * 0.35;
  }

  // ════════════════════════════════════════════
  // COMPOSITING — build the final diamond look
  // ════════════════════════════════════════════

  vec3 col = vec3(0.0);

  // Base: cool white caustic light (diamond brilliance)
  vec3 whiteLight = vec3(0.92, 0.95, 1.0);
  col += whiteLight * caustics * 1.2;

  // Chromatic caustics — subtle separation gives depth
  col += chromatic * 0.5 * brilliance;

  // Prismatic fire — rainbow colors at edges of caustic folds
  float fireMask = smoothstep(0.03, 0.25, chrDiff) * caustics;
  col += fireColor * fireMask * 2.5 * brilliance;
  col += fireColor2 * caustics * 0.6 * brilliance;

  // Facet geometry overlay — ghost-like structural hints visible only in bright areas
  vec3 facetColor = vec3(0.7, 0.75, 0.85);
  float structureMask = smoothstep(0.1, 0.5, caustics);
  col += facetColor * facetPattern * 0.04 * structureMask;
  col += facetColor * triEdges * hexEdges * 0.03 * (0.3 + structureMask * 0.7);
  col += vec3(0.8, 0.85, 0.95) * hexOutline * 0.025 * (0.2 + structureMask * 0.8);

  // Scintillation sparkles — bright white flashes
  vec3 sparkleColor = vec3(1.0, 0.98, 0.95);
  col += sparkleColor * sparkle * 3.5 * brilliance;

  // Star bursts with spectral color
  float starSpec = fract(t * 0.15 + starTotal * 2.0);
  col += mix(vec3(1.0, 0.97, 0.92), spectral(starSpec), 0.5) * starTotal * 2.5 * brilliance;

  // ── Warm amber base tone — consistent with gallery palette ──
  vec3 amber = vec3(0.78, 0.58, 0.42);
  col += amber * caustics * 0.08;

  // ── Center diamond brilliance — brighter toward center ──
  float centerGlow = smoothstep(0.6, 0.0, length(uv));
  col *= 0.8 + centerGlow * 0.8;

  // ── Occasional intense fire flash — "hearts and arrows" ──
  float flashPhase = sin(t * rotSpeed * 1.7 + uvRot.x * 4.0) *
                     cos(t * rotSpeed * 2.3 + uvRot.y * 3.0);
  float intenseFlash = pow(max(flashPhase, 0.0), 10.0) * 3.5;
  float flashSpec = fract(t * 0.2 + atan(uvRot.y, uvRot.x) / TAU);
  col += spectral(flashSpec) * intenseFlash * centerGlow * brilliance;

  // ── Subtle animated prismatic sweep — light moving across diamond ──
  float sweep = sin(uv.x * 3.0 + uv.y * 2.0 + t * rotSpeed * 0.5);
  sweep = pow(max(sweep, 0.0), 4.0) * 0.35;
  col += spectral(t * 0.1 + uv.x * 0.3) * sweep * brilliance;

  // ── Vignette — darker at edges ──
  float vig = 1.0 - dot(uv, uv) * 0.35;
  vig = max(vig, 0.0);
  col *= vig;

  // ── Tone mapping — ACES filmic, preserves sparkle peaks and saturation ──
  col *= 2.2;
  col = col * (2.51 * col + 0.03) / (col * (2.43 * col + 0.59) + 0.14);

  // ── Slight cool-warm contrast ──
  col = pow(col, vec3(0.97, 0.98, 1.03));

  // ── Minimum ambient so dark areas read as very dark, not pure black ──
  col += vec3(0.008, 0.008, 0.012);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_morphSpeed;
uniform float u_blobCount;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718
#define MAX_STEPS 48
#define MAX_DIST 20.0
#define SURF_DIST 0.002
#define BLOB_MAX 6

// Precomputed blob data — set once per pixel in main(),
// read many times in scene(). Avoids redundant trig across
// ~120 scene() calls per hit pixel (march + normal + shadow + AO).
vec3 g_pos[BLOB_MAX];
vec3 g_radStretch[BLOB_MAX];
mat2 g_rotXY[BLOB_MAX];
mat2 g_rotYZ[BLOB_MAX];
int g_count;

float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

float sdEllipsoid(vec3 p, vec3 r) {
  float k0 = length(p / r);
  float k1 = length(p / (r * r));
  return k0 * (k0 - 1.0) / k1;
}

float scene(vec3 p) {
  float d = MAX_DIST;
  for (int i = 0; i < BLOB_MAX; i++) {
    if (i >= g_count) break;
    vec3 q = p - g_pos[i];
    q = vec3(g_rotXY[i] * q.xy, q.z);
    q = vec3(q.x, g_rotYZ[i] * q.yz);
    d = smin(d, sdEllipsoid(q, g_radStretch[i]), 0.6);
  }
  return d;
}

// Tetrahedron normal — 4 scene evals instead of 6
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(0.002, -0.002);
  return normalize(
    e.xyy * scene(p + e.xyy) +
    e.yyx * scene(p + e.yyx) +
    e.yxy * scene(p + e.yxy) +
    e.xxx * scene(p + e.xxx)
  );
}

float softShadow(vec3 ro, vec3 rd, float mint, float maxt, float k) {
  float res = 1.0;
  float ph = 1e10;
  float t = mint;
  for (int i = 0; i < 16; i++) {
    float h = scene(ro + rd * t);
    if (h < 0.001) return 0.0;
    float y = h * h / (2.0 * ph);
    float d = sqrt(h * h - y * y);
    res = min(res, k * d / max(0.0, t - y));
    ph = h;
    t += h;
    if (t > maxt) break;
  }
  return clamp(res, 0.0, 1.0);
}

float calcAO(vec3 p, vec3 n) {
  float occ = 0.0;
  float sca = 1.0;
  for (int i = 0; i < 3; i++) {
    float h = 0.01 + 0.12 * float(i) / 2.0;
    float d = scene(p + h * n);
    occ += (h - d) * sca;
    sca *= 0.95;
  }
  return clamp(1.0 - 3.0 * occ, 0.0, 1.0);
}

float fresnel(float cosTheta, float f0) {
  return f0 + (1.0 - f0) * pow(1.0 - cosTheta, 5.0);
}

vec3 envMap(vec3 rd) {
  float y = rd.y * 0.5 + 0.5;
  vec3 sky = mix(
    vec3(0.02, 0.015, 0.01),
    vec3(0.08, 0.05, 0.03),
    y
  );
  float sun = pow(max(dot(rd, normalize(vec3(2.0, 3.0, 1.0))), 0.0), 32.0);
  sky += vec3(1.0, 0.85, 0.6) * sun * 0.5;
  float fill = pow(max(dot(rd, normalize(vec3(-2.0, 1.0, -1.0))), 0.0), 8.0);
  sky += vec3(0.6, 0.35, 0.3) * fill * 0.15;
  float rim = pow(max(dot(rd, normalize(vec3(0.0, 0.5, -2.0))), 0.0), 16.0);
  sky += vec3(0.8, 0.5, 0.25) * rim * 0.2;
  return sky;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  float t = u_time;
  float speed = t * u_morphSpeed;

  // Precompute all blob data once (positions, radii, rotations)
  g_count = int(u_blobCount);
  for (int i = 0; i < BLOB_MAX; i++) {
    if (i >= g_count) break;
    float fi = float(i);
    float phase = fi * TAU / 6.0;
    g_pos[i] = vec3(
      sin(speed * 0.7 + phase) * 0.8 + sin(speed * 0.3 + phase * 2.3) * 0.3,
      cos(speed * 0.5 + phase * 1.4) * 0.6 + sin(speed * 0.8 + phase * 0.7) * 0.25,
      sin(speed * 0.6 + phase * 1.8) * 0.5 + cos(speed * 0.4 + phase * 2.1) * 0.2
    );
    float base = 0.45 + fi * 0.03;
    float pulse = sin(speed * 1.2 + fi * 1.7) * 0.08 + sin(speed * 0.5 + fi * 3.1) * 0.05;
    float r = base + pulse;
    float sx = 1.0 + sin(speed * 0.9 + fi * 2.3) * 0.25;
    float sy = 1.0 + cos(speed * 0.7 + fi * 1.9) * 0.2;
    float sz = 1.0 + sin(speed * 1.1 + fi * 2.7) * 0.2;
    float norm = pow(1.0 / (sx * sy * sz), 0.333);
    g_radStretch[i] = vec3(r) * vec3(sx, sy, sz) * norm;
    float ca = cos(speed * 0.3 + fi * 1.1), sa = sin(speed * 0.3 + fi * 1.1);
    g_rotXY[i] = mat2(ca, -sa, sa, ca);
    float cb = cos(speed * 0.2 + fi * 0.9), sb = sin(speed * 0.2 + fi * 0.9);
    g_rotYZ[i] = mat2(cb, -sb, sb, cb);
  }

  // ── Mouse: attract blobs toward cursor (per-blob, distance-based) ──
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    vec3 mouseWorld = vec3(mUV.x * 3.0, mUV.y * 3.0, 0.5);
    for (int i = 0; i < BLOB_MAX; i++) {
      if (i >= g_count) break;
      vec3 toMouse = mouseWorld - g_pos[i];
      float mDist = length(toMouse);
      float pull = 0.6 / (1.0 + mDist * mDist * 2.0);
      g_pos[i] += toMouse * pull;
    }
  }

  vec3 ro = vec3(0.0, 0.3, 3.8);
  vec3 target = vec3(0.0);
  vec3 fwd = normalize(target - ro);
  vec3 right = normalize(cross(fwd, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, fwd);
  vec3 rd = normalize(fwd * 1.5 + right * uv.x + up * uv.y);

  // Bounding sphere early-out — skip raymarch for rays that miss entirely
  float bsB = dot(ro, rd);
  float bsC = dot(ro, ro) - 6.25;
  float bsDisc = bsB * bsB - bsC;

  float totalDist = 0.0;
  float dist;
  vec3 p;
  bool hit = false;

  if (bsDisc > 0.0) {
    float sqrtDisc = sqrt(bsDisc);
    float t0 = -bsB - sqrtDisc;
    float t1 = -bsB + sqrtDisc;
    if (t1 > 0.0) {
      totalDist = max(t0, 0.0);
      float marchLimit = min(t1, MAX_DIST);
      for (int i = 0; i < MAX_STEPS; i++) {
        p = ro + rd * totalDist;
        dist = scene(p);
        if (dist < SURF_DIST) { hit = true; break; }
        if (totalDist > marchLimit) break;
        totalDist += dist;
      }
    }
  }

  vec3 col = vec3(0.0);

  if (hit) {
    vec3 n = calcNormal(p);
    vec3 v = normalize(ro - p);

    float surfaceVar = sin(p.x * 5.0 + t * 0.3) * sin(p.y * 7.0 + t * 0.2) * sin(p.z * 6.0 + t * 0.4);
    vec3 baseColor = vec3(0.85, 0.65, 0.3);
    vec3 roseColor = vec3(0.8, 0.5, 0.45);
    vec3 copperColor = vec3(0.75, 0.45, 0.25);

    float colorMix1 = sin(p.x * 3.0 + p.z * 2.0 + t * u_morphSpeed * 0.4) * 0.5 + 0.5;
    float colorMix2 = sin(p.y * 4.0 - p.x * 2.5 + t * u_morphSpeed * 0.3) * 0.5 + 0.5;
    vec3 albedo = mix(baseColor, roseColor, colorMix1 * 0.3);
    albedo = mix(albedo, copperColor, colorMix2 * 0.25);

    float metallic = 0.9;
    float roughness = 0.15;

    vec3 lightDir1 = normalize(vec3(2.0, 3.0, 1.5));
    vec3 lightCol1 = vec3(1.0, 0.9, 0.75) * 1.6;
    vec3 lightDir2 = normalize(vec3(-2.0, 1.0, -1.0));
    vec3 lightCol2 = vec3(0.7, 0.4, 0.35) * 0.6;
    vec3 lightDir3 = normalize(vec3(0.0, 0.5, -2.0));
    vec3 lightCol3 = vec3(0.9, 0.6, 0.3) * 0.8;

    float diff1 = max(dot(n, lightDir1), 0.0);
    float diff2 = max(dot(n, lightDir2), 0.0);
    float diff3 = max(dot(n, lightDir3), 0.0);

    float specPow = mix(256.0, 32.0, roughness);
    vec3 h1 = normalize(lightDir1 + v);
    vec3 h2 = normalize(lightDir2 + v);
    vec3 h3 = normalize(lightDir3 + v);
    float spec1 = pow(max(dot(n, h1), 0.0), specPow);
    float spec2 = pow(max(dot(n, h2), 0.0), specPow);
    float spec3 = pow(max(dot(n, h3), 0.0), specPow);

    float NdotV = max(dot(n, v), 0.0);
    float fres = fresnel(NdotV, 0.04 + metallic * 0.76);

    float shadow = softShadow(p + n * 0.01, lightDir1, 0.02, 5.0, 16.0);
    float ao = calcAO(p, n);

    vec3 diffuse = albedo * (1.0 - metallic) * (
      lightCol1 * diff1 * shadow +
      lightCol2 * diff2 +
      lightCol3 * diff3
    );

    vec3 specColor = mix(vec3(0.04), albedo, metallic);
    vec3 specular = specColor * (
      lightCol1 * spec1 * shadow * 1.5 +
      lightCol2 * spec2 * 0.8 +
      lightCol3 * spec3 * 1.0
    );

    vec3 reflDir = reflect(-v, n);
    vec3 envRefl = envMap(reflDir);
    vec3 envContrib = envRefl * mix(vec3(0.04), albedo, metallic) * fres;

    float rimFactor = pow(1.0 - NdotV, 4.0);
    vec3 rimColor = vec3(0.9, 0.6, 0.35) * rimFactor * 0.8;

    float subsurface = pow(max(dot(-v, lightDir1), 0.0), 3.0) * (1.0 - metallic) * 0.2;
    vec3 sssColor = vec3(1.0, 0.7, 0.4) * subsurface;

    col = diffuse + specular + envContrib + rimColor + sssColor;
    col *= ao;

    float topSpec = pow(max(dot(n, h1), 0.0), 512.0) * shadow;
    col += vec3(1.0, 0.98, 0.92) * topSpec * 2.0;

  } else {
    col = vec3(0.012, 0.01, 0.008);
  }

  float floorY = -1.2;
  if (rd.y < 0.0) {
    float floorT = (floorY - ro.y) / rd.y;
    if (floorT > 0.0 && floorT < MAX_DIST && !hit) {
      vec3 floorP = ro + rd * floorT;
      float floorDist = length(floorP.xz);
      float glow = exp(-floorDist * floorDist * 1.5) * 0.15;
      glow *= 0.8 + 0.2 * sin(t * u_morphSpeed * 0.5);
      vec3 glowColor = vec3(0.6, 0.4, 0.2) * glow;
      float caustic = sin(floorP.x * 8.0 + t * 0.5) * sin(floorP.z * 8.0 + t * 0.7);
      caustic = caustic * caustic;
      glowColor += vec3(0.4, 0.25, 0.1) * caustic * glow * 2.0;
      col += glowColor;
    }
  }

  if (!hit) {
    float closestT = max(-dot(ro, rd), 0.0);
    vec3 closestP = ro + rd * closestT;
    float closestDist = length(closestP);
    float atmosGlow = exp(-closestDist * closestDist * 0.8) * 0.08;
    col += vec3(0.5, 0.35, 0.15) * atmosGlow;
  }

  col = col * (2.51 * col + 0.03) / (col * (2.43 * col + 0.59) + 0.14);
  col = pow(col, vec3(0.95, 0.98, 1.04));
  float vig = 1.0 - dot(uv, uv) * 0.25;
  col *= vig;

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_flowSpeed;
uniform float u_foldDepth;
uniform vec2 u_mouse;

// --- Simplex noise ---
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289v2(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x * 34.0) + 1.0) * x); }

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187, 0.366025403784439,
                     -0.577350269189626, 0.024390243902439);
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);
  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod289v2(i);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

// Smooth FBM — 3 octaves for organic warping
float smoothFbm(vec2 p, float t) {
  float val = 0.0;
  float amp = 0.55;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 3; i++) {
    val += amp * snoise(p + t * 0.1);
    p = rot * p * 1.9;
    amp *= 0.42;
  }
  return val;
}

// Silk fabric height field
// Folds run predominantly along one direction (like draped fabric)
// with gentle cross-folds and organic variation
float silkHeight(vec2 uv, float t) {
  // Rotate into fabric-aligned coordinates — folds run diagonally
  float angle = 0.45;
  float ca = cos(angle); float sa = sin(angle);
  vec2 fuv = vec2(ca * uv.x + sa * uv.y, -sa * uv.x + ca * uv.y);

  // Primary folds — long parallel ridges across the fabric
  // These are the dominant feature of draped silk
  float folds = sin(fuv.y * 4.0 + t * 0.3) * 0.30;
  folds += sin(fuv.y * 6.5 + t * 0.45 + 1.0) * 0.16;
  folds += sin(fuv.y * 10.0 + t * 0.55 + 2.5) * 0.07;
  folds += sin(fuv.y * 14.0 + t * 0.7 + 4.0) * 0.03;

  // Slow modulation along the fold direction — folds gather and spread
  float gather = sin(fuv.x * 0.8 + t * 0.15) * 0.4 + 0.6;
  folds *= gather;

  // Gentle cross-folds (much weaker than main folds)
  float cross = sin(fuv.x * 2.0 + fuv.y * 0.5 + t * 0.25 + 3.0) * 0.06;
  cross += sin(fuv.x * 3.5 - fuv.y * 0.8 + t * 0.35 + 5.0) * 0.04;

  // Large billowing motion — the whole fabric breathes
  float billow = sin(uv.x * 0.9 + uv.y * 0.6 + t * 0.2) * 0.15;
  billow += sin(uv.x * 0.5 - uv.y * 1.1 + t * 0.18 + 2.0) * 0.12;

  // Organic noise — very low frequency for natural drape variation
  float organic = smoothFbm(uv * 0.3, t * 0.4) * 0.1;

  return folds + cross + billow + organic;
}

// Surface normal via central differences
vec3 silkNormal(vec2 uv, float t) {
  float eps = 0.003;
  float hC = silkHeight(uv, t);
  float hR = silkHeight(uv + vec2(eps, 0.0), t);
  float hU = silkHeight(uv + vec2(0.0, eps), t);
  // The z-component controls how steep the normals feel
  // Lower = sharper highlights, higher = softer
  return normalize(vec3(hC - hR, hC - hU, eps * 1.0));
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5) * 3.2;

  float t = u_time * u_flowSpeed;

  // Gentle domain warp for organic movement
  vec2 warp = vec2(
    snoise(p * 0.18 + t * 0.05 + vec2(0.0, 4.7)),
    snoise(p * 0.18 + t * 0.04 + vec2(8.3, 0.0))
  ) * 0.25;
  vec2 sp = p + warp;

  // Height and normal of the silk surface
  float h = silkHeight(sp, t) * u_foldDepth;
  vec3 N = silkNormal(sp, t);

  // ── Lighting — warm two-point setup ──
  // Mouse controls light direction for shimmering silk highlights
  vec3 L1 = normalize(vec3(0.3, 0.5, 0.75));
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res - 0.5;
    L1 = normalize(vec3(mUV.x * 1.5, mUV.y * 1.5, 0.75));
  }
  vec3 L2 = normalize(vec3(-0.5, -0.3, 0.65));
  vec3 V = vec3(0.0, 0.0, 1.0);

  // Diffuse
  float d1 = max(dot(N, L1), 0.0);
  float d2 = max(dot(N, L2), 0.0);

  // Wrapped diffuse for softer fill
  float wd1 = max(0.0, (dot(N, L1) + 0.3) / 1.3);

  // Specular lobes — silk has broad sheen + sharp glint
  vec3 H1 = normalize(L1 + V);
  vec3 H2 = normalize(L2 + V);

  // Broad silk sheen
  float sheen1 = pow(max(dot(N, H1), 0.0), 3.0) * 0.4;
  float sheen2 = pow(max(dot(N, H2), 0.0), 4.0) * 0.2;

  // Medium specular
  float spec1 = pow(max(dot(N, H1), 0.0), 18.0);
  float spec2 = pow(max(dot(N, H2), 0.0), 22.0);

  // Sharp glint on fold peaks
  float spark = pow(max(dot(N, H1), 0.0), 90.0);

  // Fresnel rim
  float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

  // ── Color palette — luxurious warm silk ──
  vec3 deepAmber    = vec3(0.45, 0.22, 0.08);
  vec3 richGold     = vec3(0.70, 0.50, 0.16);
  vec3 warmBurgundy = vec3(0.32, 0.07, 0.09);
  vec3 deepRose     = vec3(0.48, 0.16, 0.14);
  vec3 lightSilk    = vec3(1.0, 0.88, 0.55);
  vec3 pearlHL      = vec3(1.0, 0.94, 0.75);

  // Smoothly varying base color across fabric
  float cm1 = smoothstep(-0.3, 0.4, h);
  float cm2 = snoise(sp * 0.25 + t * 0.02 + vec2(13.0, 7.0)) * 0.5 + 0.5;
  float cm3 = snoise(sp * 0.15 + vec2(3.0, 11.0)) * 0.5 + 0.5;

  vec3 baseColor = mix(warmBurgundy, deepAmber, cm1);
  baseColor = mix(baseColor, richGold, cm2 * 0.5);
  baseColor = mix(baseColor, deepRose, cm3 * 0.2);

  // ── Compose final color ──
  vec3 col = baseColor * 0.15; // ambient

  // Primary warm key light
  vec3 lc1 = vec3(1.0, 0.87, 0.58);
  col += baseColor * wd1 * 0.5 * lc1;
  col += baseColor * sheen1 * lc1;
  col += lightSilk * spec1 * 0.6;
  col += pearlHL * spark * 0.5;

  // Secondary cooler fill
  vec3 lc2 = vec3(0.6, 0.5, 0.72);
  col += baseColor * d2 * 0.18 * lc2;
  col += baseColor * sheen2 * lc2;
  col += vec3(0.75, 0.65, 0.85) * spec2 * 0.2;

  // Fresnel edge glow
  col += pearlHL * fresnel * 0.1;

  // ── Traveling shimmer along fold ridges ──
  float angle2 = 0.45;
  float ca2 = cos(angle2); float sa2 = sin(angle2);
  float foldDir = ca2 * sp.x + sa2 * sp.y;
  float shim = sin(foldDir * 4.0 - t * 1.5) * 0.5 + 0.5;
  shim = pow(shim, 18.0);
  col += pearlHL * shim * (spec1 + sheen1 * 0.3) * 0.5;

  // ── Fold shadows — darken valleys ──
  float valley = smoothstep(0.05, -0.25, h);
  col *= 1.0 - valley * 0.5;

  // Deep shadow in lowest folds
  float deepSh = smoothstep(-0.1, -0.45, h);
  col = mix(col, vec3(0.05, 0.02, 0.025), deepSh * 0.45);

  // ── Subtle iridescence ──
  col.r += fresnel * 0.06;
  col.b += fresnel * 0.03;

  // ── Vignette ──
  vec2 vc = uv - 0.5;
  float vig = 1.0 - dot(vc, vc) * 1.4;
  vig = smoothstep(0.0, 1.0, vig);
  col *= vig;

  // Tone mapping + gamma
  col = col / (col + vec3(0.6));
  col = pow(col, vec3(0.9));

  // Floor to near-black
  col = max(col, vec3(0.018, 0.015, 0.013));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_rotationSpeed;
uniform float u_diskIntensity;
uniform float u_starsOnly;
uniform float u_tilt;
uniform float u_rotate;
uniform vec2 u_bhCenter;
uniform float u_bhScale;
uniform float u_chromatic;

// ──── Constants ────
const float PI = 3.14159265359;
const float TAU = 6.28318530718;
const float RS = 1.0;        // Schwarzschild radius
const float ISCO = 3.0;      // Innermost stable circular orbit
const float DISK_IN = 2.2;   // Inner glow edge (infalling material)
const float DISK_OUT = 14.0;  // Outer disk edge

// ──────────────────────────────────────────
// Hash — PCG-inspired, no sin()
// ──────────────────────────────────────────
float hash(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// ──────────────────────────────────────────
// Gradient noise with quintic interpolation
// ──────────────────────────────────────────
float gNoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    return mix(
        mix(hash(i), hash(i + vec2(1, 0)), u.x),
        mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), u.x),
        u.y
    );
}

// ──────────────────────────────────────────
// FBM with domain rotation (reduces grid artifacts)
// ──────────────────────────────────────────
float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    mat2 rot = mat2(0.866, 0.5, -0.5, 0.866); // 30 deg rotation
    for (int i = 0; i < 4; i++) {
        v += a * gNoise(p);
        p = rot * p * 2.03 + vec2(47.0, 13.0);
        a *= 0.49;
    }
    return v;
}
// Lightweight 2-octave noise for subtle effects (nebula etc.)
float fbmLite(vec2 p) {
    float v = 0.5 * gNoise(p);
    p = mat2(0.866, 0.5, -0.5, 0.866) * p * 2.03 + vec2(47.0, 13.0);
    v += 0.25 * gNoise(p);
    return v;
}

// ──────────────────────────────────────────
// Star field — cell-based with spherical UV
// ──────────────────────────────────────────
vec3 starField(vec3 rd) {
    float u = atan(rd.z, rd.x) / TAU + 0.5;
    float v = asin(clamp(rd.y, -0.999, 0.999)) / PI + 0.5;
    vec3 col = vec3(0.0);

    // Bright sparse stars
    {
        vec2 cell = floor(vec2(u, v) * 55.0);
        vec2 f = fract(vec2(u, v) * 55.0);
        vec2 r = vec2(hash(cell), hash(cell + 127.1));
        float d = length(f - r);
        float b = pow(r.x, 10.0) * exp(-d * d * 500.0);
        col += mix(vec3(1.0, 0.65, 0.35), vec3(0.55, 0.75, 1.0), r.y) * b * 4.0;
    }
    // Medium density stars
    {
        vec2 cell = floor(vec2(u, v) * 170.0);
        vec2 f = fract(vec2(u, v) * 170.0);
        vec2 r = vec2(hash(cell + 43.0), hash(cell + 91.0));
        float d = length(f - r);
        float b = pow(r.x, 18.0) * exp(-d * d * 1000.0);
        col += vec3(0.85, 0.88, 1.0) * b * 2.0;
    }
    // Subtle nebula (lite noise — pow(3) crushes detail anyway)
    float n = fbmLite(vec2(u, v) * 3.0) * fbmLite(vec2(u, v) * 5.5 + 10.0);
    col += vec3(0.10, 0.04, 0.14) * pow(n, 3.0);

    return col;
}

// ──────────────────────────────────────────
// Blackbody color (physically motivated)
// ──────────────────────────────────────────
vec3 bbColor(float t) {
    t = clamp(t, 0.0, 2.5);
    vec3 lo = vec3(1.0, 0.18, 0.0);    // deep red     (~1500K)
    vec3 mi = vec3(1.0, 0.55, 0.12);   // orange       (~3500K)
    vec3 hi = vec3(1.0, 0.93, 0.82);   // warm white   (~8000K)
    vec3 hot = vec3(0.65, 0.82, 1.0);  // cool blue-wh (~15000K)
    vec3 c = mix(lo, mi, smoothstep(0.0, 0.3, t));
    c = mix(c, hi, smoothstep(0.3, 0.8, t));
    return mix(c, hot, smoothstep(0.8, 1.8, t));
}

// ──────────────────────────────────────────
// Accretion disk shading
//   Novikov-Thorne temperature profile
//   FBM turbulence + spiral arms
//   Doppler beaming + gravitational redshift
// ──────────────────────────────────────────
vec4 shadeDisk(vec3 hit, vec3 vel, float time) {
    float r = length(hit.xz);
    if (r < DISK_IN * 0.5 || r > DISK_OUT * 1.05) return vec4(0.0);

    // Novikov-Thorne: T proportional to r^-3/4 (1 - sqrt(r_isco/r))^1/4
    float xr = ISCO / r;
    float tProfile = pow(ISCO / r, 0.75) * pow(max(0.001, 1.0 - sqrt(xr)), 0.25);

    // Gravitational redshift: observed temp = emitted * sqrt(1 - RS/r)
    float gRedshift = sqrt(max(0.01, 1.0 - RS / r));
    tProfile *= gRedshift;

    // Disk texture with Keplerian differential rotation
    float phi = atan(hit.z, hit.x);
    float lr = log2(max(r, 0.1));

    // Keplerian angular velocity with a floor so outer disk still moves
    float keplerOmega = sqrt(0.5 * RS / (r * r * r));
    float baseOmega = 0.04; // minimum rotation for outer rings
    float omega = max(keplerOmega, baseOmega) * 10.0;
    float rotAngle = time * omega;
    float ca = cos(rotAngle), sa = sin(rotAngle);
    vec2 rotXZ = vec2(hit.x * ca - hit.z * sa, hit.x * sa + hit.z * ca);

    // FBM turbulence — the primary texture, gives cloudy organic feel
    // Sampled at Keplerian-rotated coords for orbital flow
    float turb = fbm(rotXZ * 1.2 + vec2(lr * 3.0));
    turb = 0.25 + 0.75 * turb;

    // Time-evolving detail layer — single noise call (subtle contribution)
    float timeShift = time * 0.15;
    float detail = gNoise(rotXZ * 3.5 + vec2(100.0 + timeShift, timeShift * 0.7));
    turb *= 0.7 + 0.3 * detail;

    // Concentric ring modulation — visible structure within the clouds
    float ringPhase1 = sin(r * 10.0 + rotAngle * r * 0.3) * 0.5 + 0.5;
    float ringPhase2 = sin(r * 20.0 - rotAngle * r * 0.15) * 0.5 + 0.5;
    float rings = ringPhase1 * 0.55 + ringPhase2 * 0.45;
    rings = 0.5 + 0.5 * rings;
    turb *= rings;

    // Doppler beaming from Keplerian orbital motion
    // Reduced from 3.0 to 2.0 so the receding side stays visible
    float orbSpeed = sqrt(0.5 * RS / max(r, DISK_IN));
    vec3 orbDir = normalize(vec3(-hit.z, 0.0, hit.x));
    float dopplerFactor = 1.0 + 2.0 * dot(normalize(vel), orbDir) * orbSpeed;
    dopplerFactor = max(0.15, dopplerFactor);
    float dopplerBoost = dopplerFactor * dopplerFactor * dopplerFactor;

    // Intensity
    float I = tProfile * turb * 6.0;

    // Edge fades
    float innerFade = smoothstep(DISK_IN * 0.7, DISK_IN * 1.2, r);
    // ISCO fade — emission ramps up beyond ISCO
    float iscoFade = 0.35 + 0.65 * smoothstep(ISCO * 0.85, ISCO * 1.2, r);
    float outerFade = 1.0 - smoothstep(DISK_OUT * 0.55, DISK_OUT, r);
    I *= innerFade * iscoFade * outerFade;

    // Color: temperature + Doppler frequency shift
    // Approaching side: blue-shifted (higher temp), receding: red-shifted (lower temp)
    float colorTemp = tProfile * pow(dopplerFactor, 1.8) * 1.2;
    vec3 col = bbColor(colorTemp) * I * dopplerBoost;

    // Chromatic dispersion: each ring band gets a spectral hue
    if (u_chromatic > 0.01) {
        // Smooth spectral mapping based on radius
        // Uses the actual ring structure phase for band-coherent coloring
        float spectralR = (r - DISK_IN) / (DISK_OUT - DISK_IN);
        float ringP = ringPhase1; // from the ring structure above

        // Combine radial position and ring phase for spectral position
        // This ensures each bright ring band has its own distinct hue
        float hue = spectralR * 0.8 + ringP * 0.4;

        // Full visible spectrum: red → orange → yellow → green → cyan → blue
        vec3 spectrum;
        // Red channel: strong at low hue, returns at high hue (wraps around)
        spectrum.r = (1.0 - smoothstep(0.0, 0.35, hue))  // red at start
                   + smoothstep(0.25, 0.45, hue) * (1.0 - smoothstep(0.55, 0.7, hue)) * 0.7  // orange/yellow
                   + smoothstep(0.85, 1.1, hue) * 0.4; // faint return
        // Green channel: broad peak in the middle (yellow → green → cyan)
        spectrum.g = smoothstep(0.15, 0.4, hue) * (1.0 - smoothstep(0.7, 0.95, hue));
        // Blue channel: peaks at high hue (cyan → blue)
        spectrum.b = smoothstep(0.5, 0.8, hue)
                   + smoothstep(0.85, 1.1, hue) * 0.3; // violet hint
        spectrum = max(spectrum, 0.05);

        // Preserve luminance from the original color
        float luma = dot(col, vec3(0.3, 0.5, 0.2));
        vec3 chromaCol = spectrum * luma * 2.0;

        col = mix(col, chromaCol, u_chromatic * 0.75);
    }

    float alpha = clamp(I * 1.3, 0.0, 0.96);
    return vec4(col, alpha);
}

// ──────────────────────────────────────────
// Main — Schwarzschild geodesic ray tracer
// Uses velocity-Verlet integration of:
//   d²x/dλ² = -1.5 · RS · L² / r⁵ · x
// where L² = |x × v|² is the conserved angular momentum
// ──────────────────────────────────────────
void main() {
    vec2 fc = gl_FragCoord.xy;
    vec2 ctr = (u_bhScale > 0.0 ? u_bhCenter : vec2(0.5)) * u_res;
    float sc = u_bhScale > 0.0 ? u_bhScale : 1.0;
    vec2 uv = (fc - ctr) * sc / u_res.x;

    // Orbital camera
    float camR = 28.0;
    float orbit = u_time * 0.055 * u_rotationSpeed;
    float tilt = 0.25 + u_tilt;

    vec3 eye = vec3(
        camR * cos(orbit) * cos(tilt),
        camR * sin(tilt),
        camR * sin(orbit) * cos(tilt)
    );

    // Look-at basis
    vec3 fwd = normalize(-eye);
    vec3 rt = normalize(cross(fwd, vec3(0.0, 1.0, 0.0)));
    vec3 up = cross(rt, fwd);

    // Roll rotation
    float cr = cos(u_rotate), sr = sin(u_rotate);
    vec3 rr = cr * rt + sr * up;
    vec3 ru = -sr * rt + cr * up;

    vec3 rd = normalize(fwd + uv.x * rr + uv.y * ru);

    // Stars-only bypass
    if (u_starsOnly > 0.5) {
        vec3 s = starField(rd);
        gl_FragColor = vec4(pow(s, vec3(0.45)), 1.0);
        return;
    }

    // ──── Geodesic integration ────
    vec3 pos = eye;
    vec3 vel = rd;

    // Angular momentum (conserved along Schwarzschild geodesic)
    vec3 Lvec = cross(pos, vel);
    float L2 = dot(Lvec, Lvec);

    vec4 diskAccum = vec4(0.0);
    vec3 glow = vec3(0.0);
    bool absorbed = false;
    int diskCrossings = 0;
    float minR = 1000.0; // track closest approach for photon ring

    // Pre-compute loop invariant
    float gravCoeff = -1.5 * RS * L2;

    for (int i = 0; i < 200; i++) {
        float r = length(pos);

        // Adaptive step: fine near BH, coarse far away
        float h = 0.16 * clamp(r - 0.4 * RS, 0.06, 3.5);

        // Schwarzschild geodesic: a = -1.5·RS·L²/r⁵ · x
        float invR2 = 1.0 / (r * r);
        float invR5 = invR2 * invR2 / r;
        vec3 acc = (gravCoeff * invR5) * pos;

        // Velocity-Verlet integration (symplectic, energy-preserving)
        vec3 p1 = pos + vel * h + 0.5 * acc * h * h;
        float r1 = length(p1);
        float invR12 = 1.0 / (r1 * r1);
        float invR15 = invR12 * invR12 / r1;
        vec3 acc1 = (gravCoeff * invR15) * p1;
        vec3 v1 = vel + 0.5 * (acc + acc1) * h;

        // Track closest approach
        minR = min(minR, r1);

        // ── Disk crossing detection (y=0 plane) ──
        if (pos.y * p1.y < 0.0 && diskAccum.a < 0.97) {
            float t = pos.y / (pos.y - p1.y);
            vec3 hit = mix(pos, p1, t);
            vec4 dc = shadeDisk(hit, vel, u_time * u_rotationSpeed);
            dc.rgb *= u_diskIntensity;
            // 1st & 2nd crossings: full (primary disk + secondary image)
            // 3rd+ crossings: heavily attenuated (these create the crispy 1px photon ring)
            if (diskCrossings >= 2) {
                dc.rgb *= 0.15;
                dc.a *= 0.15;
            }
            // Alpha-over compositing
            diskAccum.rgb += dc.rgb * dc.a * (1.0 - diskAccum.a);
            diskAccum.a += dc.a * (1.0 - diskAccum.a);
            // Bloom spillover: bright disk regions bleed glow
            float diskBright = dot(dc.rgb, vec3(0.3, 0.5, 0.2)) * dc.a;
            glow += dc.rgb * 0.04 * max(diskBright - 0.3, 0.0);
            diskCrossings++;
        }

        // ── Glow calculations only when close to BH (negligible contribution beyond r=6) ──
        if (r1 < 6.0) {
            // Soft ambient glow near BH (very diffuse, no sharp peak)
            float pDist = abs(r1 - 1.5 * RS);
            float psGlow = 1.0 / (1.0 + pDist * pDist * 20.0) * h * 0.001 / max(r1 * r1, 0.2);
            glow += vec3(0.8, 0.6, 0.35) * psGlow;

            // Event horizon proximity glow
            float hzGlow = exp(-(r1 - RS) * 3.5) * h * 0.003;
            glow += vec3(0.5, 0.25, 0.08) * max(hzGlow, 0.0);
        }

        // ── Termination ──
        if (r1 < RS * 0.35) { absorbed = true; break; }
        // Early escape: ray moving outward past disk range, deflection negligible
        if (r1 > 25.0 && r1 > r) break;
        if (r1 > 55.0) break;

        pos = p1;
        vel = v1;
    }

    // ──── Final compositing ────
    vec3 col = vec3(0.0);
    if (!absorbed) {
        col = starField(normalize(vel));
    }
    // Disk over background
    col = col * (1.0 - diskAccum.a) + diskAccum.rgb;

    // ── Shadow-edge chromatic fringe ──
    // Replaces the old sharp 1px ring with smooth, wide RGB separation
    float ringDist = abs(minR - 1.5 * RS);
    float chromo = u_chromatic;

    // Soft wide chromatic bands: red/orange outside, blue inside
    // No center "white ring" — purely spectral separation
    float baseChroma = 0.1 + 0.5 * chromo;
    float spread = 0.08 + 0.18 * chromo;
    float falloff = 20.0 + 15.0 * (1.0 - chromo); // wider/softer bands
    float rRing = exp(-(ringDist + spread) * (ringDist + spread) * falloff);
    float bRing = exp(-(ringDist - spread) * (ringDist - spread) * falloff);
    col.r += rRing * 0.3 * baseChroma;
    col.b += bRing * 0.35 * baseChroma;

    // Glow additive
    col += glow;

    // Filmic tone mapping (ACES-inspired) + contrast
    col *= 1.4;
    vec3 a = col * (col + 0.0245786) - 0.000090537;
    vec3 b = col * (0.983729 * col + 0.4329510) + 0.238081;
    col = a / b;

    col = smoothstep(0.0, 1.0, col);
    col = pow(max(col, 0.0), vec3(0.92));

    gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_tunnelSpeed;
uniform float u_spiralIntensity;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash for noise ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// ── Value noise ──
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;

  // Center UV, correct aspect
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);

  float t = u_time;
  float scrollSpeed = u_tunnelSpeed;

  // ── Polar coordinates ──
  float r = length(p);
  float theta = atan(p.y, p.x);

  // ── Steady tunnel depth — NO dolly-zoom, fixed FOV ──
  float depth = 1.0 / (r + 0.04);

  // ── Rotation: auto drift + mouse drag offset ──
  float rotAngle = t * 0.02 + sin(t * 0.07) * 0.15 + u_mouse.x;
  float thetaRot = theta + rotAngle;

  // ── Tunnel texture coordinates ──
  // u = angle (wrapping), v = depth (scrolling forward steadily)
  float tu = thetaRot / TAU;
  float tv = depth - t * scrollSpeed;

  // ── Ring segments ──
  float ringFreq = 10.0;
  float ringCoord = tv * ringFreq / TAU;
  float ringPhase = fract(ringCoord);
  float ringId = floor(ringCoord);

  // Primary rings — clean sharp edges
  float ring = smoothstep(0.0, 0.06, ringPhase) * smoothstep(0.5, 0.44, ringPhase);

  // Secondary thinner accent rings between primaries
  float ringPhase2 = fract(ringCoord * 2.0);
  float ring2 = smoothstep(0.0, 0.03, ringPhase2) * smoothstep(0.5, 0.47, ringPhase2);

  // ── Angular segments (line divisions around the tunnel) ──
  float angSegments = 16.0;
  float angPhase = fract(tu * angSegments);
  float angLine = smoothstep(0.0, 0.025, angPhase) * smoothstep(1.0, 0.975, angPhase);

  // ── Combine into tunnel structure ──
  float structure = ring * angLine;
  // Add thin rings as subtle accent
  structure = max(structure, ring2 * 0.25 * angLine);

  // ── Wave-based ring illumination ──
  // Multiple slow waves propagating outward at different speeds
  // Wave 1: primary outward pulse
  float wave1 = sin(ringId * 0.5 - t * 0.8) * 0.5 + 0.5;
  wave1 = pow(wave1, 3.0);

  // Wave 2: slower, wider inward pulse (counter-direction)
  float wave2 = sin(ringId * 0.3 + t * 0.5) * 0.5 + 0.5;
  wave2 = pow(wave2, 4.0);

  // Wave 3: very slow breathing that lights groups of rings
  float wave3 = sin(ringId * 0.15 - t * 0.35) * 0.5 + 0.5;
  wave3 = pow(wave3, 2.0);

  // Compose ring brightness from overlapping waves
  float ringBrightness = 0.15 + wave1 * 0.5 + wave2 * 0.35 + wave3 * 0.25;
  ringBrightness = clamp(ringBrightness, 0.0, 1.5);

  // Occasional bright flash on specific rings (sparse)
  float flash = pow(max(0.0, sin(ringId * 7.3 - t * 1.2)), 12.0);
  ringBrightness += flash * 0.8;

  structure *= ringBrightness;

  // ── Depth fog: fade rings into void at distance ──
  float depthFade = exp(-r * 3.0);
  // Near the center (deep void), fade to black
  float voidFade = smoothstep(0.0, 0.12, r);
  structure *= depthFade * voidFade;

  // ── Neon edge highlights on ring edges ──
  float edgeHighlight = smoothstep(0.06, 0.02, abs(ringPhase - 0.01));
  edgeHighlight += smoothstep(0.06, 0.02, abs(ringPhase - 0.48));
  edgeHighlight *= angLine * depthFade * voidFade;

  // ── Color scheme — richer palette ──
  // Deep crimson base
  vec3 crimson = vec3(0.80, 0.067, 0.20);
  // Dark purple
  vec3 darkPurple = vec3(0.133, 0.0, 0.20);
  // Neon red accent
  vec3 neonRed = vec3(1.0, 0.133, 0.267);
  // Warm amber highlight
  vec3 amber = vec3(0.784, 0.584, 0.424);
  // Deep magenta for variety
  vec3 magenta = vec3(0.6, 0.05, 0.35);
  // Burnt orange for warm accents
  vec3 burntOrange = vec3(0.85, 0.35, 0.1);

  // ── Per-ring color variation ──
  // Each ring gets a slightly different hue based on its ID
  float colorSel = fract(ringId * 0.618033); // golden ratio spacing
  float colorShift = sin(ringId * 1.7 + t * 0.2) * 0.5 + 0.5;

  // Base tunnel color blends crimson and purple by radius
  float colorDepth = smoothstep(0.0, 0.5, r);
  vec3 tunnelColor = mix(darkPurple, crimson, colorDepth);

  // Vary individual ring colors
  tunnelColor = mix(tunnelColor, magenta, colorSel * 0.3);
  tunnelColor = mix(tunnelColor, crimson * 1.3, colorShift * 0.25);

  // Amber tint on wave-lit rings
  float amberAmount = wave1 * wave3;
  tunnelColor = mix(tunnelColor, amber * 0.8, amberAmount * 0.3);

  // Burnt orange on flash rings
  tunnelColor = mix(tunnelColor, burntOrange, flash * 0.5);

  // ── Edge highlight color varies too ──
  vec3 edgeColor = mix(neonRed, amber, wave2 * 0.4);
  edgeColor = mix(edgeColor, magenta * 1.5, flash * 0.3);

  // ── Composite ──
  vec3 col = vec3(0.0);

  // Base tunnel structure
  col += tunnelColor * structure;

  // Edge highlights with varied color
  col += edgeColor * edgeHighlight * 0.5;

  // Amber glow on bright pulsing rings
  col += amber * wave1 * structure * 0.3;

  // Flash rings get a bright white-amber spike
  col += mix(amber, vec3(1.0, 0.9, 0.7), 0.5) * flash * structure * 0.5;

  // ── Subtle ambient glow from the tunnel void ──
  float ambientGlow = exp(-r * 5.0) * (1.0 - smoothstep(0.0, 0.08, r));
  col += darkPurple * ambientGlow * 0.08;

  // ── Very faint atmospheric haze deeper in tunnel ──
  float haze = exp(-r * 6.0) * 0.02;
  col += mix(darkPurple, crimson * 0.5, 0.3) * haze;

  // ── Vignette ──
  float vig = 1.0 - smoothstep(0.3, 1.1, r);
  col *= 0.55 + 0.45 * vig;

  // ── Film grain ──
  float grain = (fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233)) + fract(u_time * 0.1) * 100.0) * 43758.5453) - 0.5) * 0.02;
  col += grain;

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_flowSpeed;
uniform float u_sheenIntensity;
uniform vec2 u_mouse;

#define PI 3.14159265359

float hash12(vec2 p){
  vec3 p3=fract(vec3(p.xyx)*0.1031);
  p3+=dot(p3,p3.yzx+33.33);
  return fract((p3.x+p3.y)*p3.z);
}

float vnoise(vec2 p){
  vec2 i=floor(p);
  vec2 f=fract(p);
  f=f*f*(3.0-2.0*f);
  float a=hash12(i);
  float b=hash12(i+vec2(1.0,0.0));
  float c=hash12(i+vec2(0.0,1.0));
  float d=hash12(i+vec2(1.0,1.0));
  return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);
}

float fbm3(vec2 p){
  float v=0.0, a=0.5;
  mat2 rot=mat2(0.8,-0.6,0.6,0.8);
  for(int i=0;i<3;i++){
    v+=a*vnoise(p);
    p=rot*p*2.0;
    a*=0.5;
  }
  return v;
}

// 2-octave fbm for back layers (cheaper)
float fbm2(vec2 p){
  float v=0.5*vnoise(p);
  p=mat2(0.8,-0.6,0.6,0.8)*p*2.0;
  v+=0.25*vnoise(p);
  return v;
}

vec2 domainWarp(vec2 p, float t, float scale, float seed){
  return vec2(
    fbm3(p*scale+vec2(1.7+seed,9.2)+t*0.15),
    fbm3(p*scale+vec2(8.3,2.8+seed)-t*0.12)
  );
}

// Cheaper warp for back layers
vec2 domainWarpLite(vec2 p, float t, float scale, float seed){
  return vec2(
    fbm2(p*scale+vec2(1.7+seed,9.2)+t*0.15),
    fbm2(p*scale+vec2(8.3,2.8+seed)-t*0.12)
  );
}

// Per-layer fold: returns vec3(height, gradient.xy)
vec3 fabricFold(vec2 p, float t, float seed, float freq, float flow){
  float ts=t*flow;
  vec2 warp=domainWarp(p+seed*3.7, ts, 1.2, seed);
  vec2 wp=p+warp*0.55;
  float h=0.0; vec2 g=vec2(0.0);

  float f1x=freq*0.7, f1y=freq*0.4;
  float ph1=wp.x*f1x+wp.y*f1y+ts*0.3+seed*2.1;
  h+=sin(ph1)*0.35; g+=cos(ph1)*0.35*vec2(f1x,f1y);

  float f2x=-freq*0.3, f2y=freq*0.9;
  float ph2=wp.x*f2x+wp.y*f2y+ts*0.25+seed*1.3;
  h+=sin(ph2)*0.25; g+=cos(ph2)*0.25*vec2(f2x,f2y);

  float f3=freq*0.6;
  float ph3=(wp.x+wp.y)*f3+ts*0.2+seed*4.5;
  h+=sin(ph3)*0.18; g+=cos(ph3)*0.18*vec2(f3,f3);

  float f4x=freq*1.8, f4y=freq*1.2;
  float ph4=wp.x*f4x+wp.y*f4y-ts*0.35+seed*0.7;
  h+=sin(ph4)*0.08; g+=cos(ph4)*0.08*vec2(f4x,f4y);

  h+=vnoise(wp*freq*0.9+seed*10.0+ts*0.04)*0.12-0.06;
  return vec3(h, g);
}

// Lighter fold for back layers (no 5th wave, no vnoise detail, cheaper warp)
vec3 fabricFoldLite(vec2 p, float t, float seed, float freq, float flow){
  float ts=t*flow;
  vec2 warp=domainWarpLite(p+seed*3.7, ts, 1.2, seed);
  vec2 wp=p+warp*0.55;
  float h=0.0; vec2 g=vec2(0.0);
  float f1x=freq*0.7, f1y=freq*0.4;
  float ph1=wp.x*f1x+wp.y*f1y+ts*0.3+seed*2.1;
  h+=sin(ph1)*0.35; g+=cos(ph1)*0.35*vec2(f1x,f1y);
  float f2x=-freq*0.3, f2y=freq*0.9;
  float ph2=wp.x*f2x+wp.y*f2y+ts*0.25+seed*1.3;
  h+=sin(ph2)*0.25; g+=cos(ph2)*0.25*vec2(f2x,f2y);
  float f3=freq*0.6;
  float ph3=(wp.x+wp.y)*f3+ts*0.2+seed*4.5;
  h+=sin(ph3)*0.18; g+=cos(ph3)*0.18*vec2(f3,f3);
  float f4x=freq*1.8, f4y=freq*1.2;
  float ph4=wp.x*f4x+wp.y*f4y-ts*0.35+seed*0.7;
  h+=sin(ph4)*0.08; g+=cos(ph4)*0.08*vec2(f4x,f4y);
  return vec3(h, g);
}

// Kajiya-Kay anisotropic specular
float kajiyaSpec(vec2 grad, vec3 L, vec3 V, float shine){
  float gl2=dot(grad,grad);
  if(gl2<0.0001) return 0.0;
  vec2 tg=vec2(-grad.y, grad.x)/sqrt(gl2);
  vec3 T=normalize(vec3(tg, 0.0));
  vec3 H=normalize(L+V);
  float TdH=dot(T,H);
  return pow(sqrt(max(1.0-TdH*TdH, 0.0)), shine);
}

// Shade one fabric layer
vec4 shadeLayer(
  vec2 p, float t,
  float seed, float freq, float flow,
  vec3 darkCol, vec3 midCol, vec3 brightCol, vec3 specCol,
  float opacity, float shine,
  vec3 L1, vec3 L2, vec3 V,
  float sheenMul
){
  vec3 fold=opacity<0.35 ? fabricFoldLite(p, t, seed, freq, flow) : fabricFold(p, t, seed, freq, flow);
  float h=fold.x;
  vec2 grad=fold.yz;
  vec3 N=normalize(vec3(-grad*1.8, 1.0));

  // Lighting — strong directional contrast
  float NdL1=max(dot(N, L1), 0.0);
  float NdL2=max(dot(N, L2), 0.0);
  float lit=NdL1*0.75+NdL2*0.12;

  // Fold depth
  float depth=smoothstep(-0.8, 0.4, h);

  // Three-tone fabric shading: dark valleys -> mid -> bright lit peaks
  float shade=lit*depth;
  float midBlend=smoothstep(0.0, 0.35, shade);
  float brightBlend=smoothstep(0.25, 0.7, shade);
  vec3 fabric=mix(darkCol, midCol, midBlend);
  fabric=mix(fabric, brightCol, brightBlend*0.5);

  // Anisotropic specular streaks — sharp silk sheen
  float sp=kajiyaSpec(grad, L1, V, shine)*0.9;
  sp+=kajiyaSpec(grad, L2, V, shine*0.6)*0.15;
  sp*=sheenMul;
  float specPow=sp*sp*sp;
  fabric+=specCol*specPow*0.9;

  // Translucent backlight at peaks
  float trans=smoothstep(0.3, 0.9, depth)*lit*0.08;
  fabric+=vec3(0.45, 0.28, 0.15)*trans;

  // Sparkle — extremely rare, only where specular is strong
  float sparkle=hash12(floor(p*500.0+t*0.7));
  sparkle=step(0.9992, sparkle)*specPow*20.0*sheenMul;
  fabric+=specCol*min(sparkle, 2.0);

  // Alpha: opaque in valleys, can thin at bright peaks
  float alpha=opacity*(0.65+depth*0.35);
  return vec4(fabric, alpha);
}

void main(){
  vec2 uv=gl_FragCoord.xy/u_res;
  float aspect=u_res.x/u_res.y;
  vec2 p=(uv-0.5)*vec2(aspect, 1.0);


  float t=u_time*u_flowSpeed;

  // Primary light — follows cursor for shimmering highlights
  vec3 L1=normalize(vec3(
    0.4+sin(t*0.07)*0.3,
    0.9+cos(t*0.09)*0.15,
    0.8
  ));
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res - 0.5;
    L1 = normalize(vec3(mUV.x * 2.0, mUV.y * 2.0 + 0.5, 0.8));
  }
  vec3 L2=normalize(vec3(
    -0.7+cos(t*0.06)*0.2,
    -0.3+sin(t*0.08)*0.15,
    0.6
  ));
  vec3 V=vec3(0.0, 0.0, 1.0);

  // Background — deep dark with purple tint
  float bgD=length(p);
  vec3 bg=mix(
    vec3(0.055, 0.03, 0.075),
    vec3(0.012, 0.006, 0.02),
    smoothstep(0.0, 1.0, bgD)
  );
  bg+=vec3(0.025, 0.012, 0.035)*exp(-bgD*bgD*2.0);

  // Layer 1: Deep — warm gold/champagne (slowest, most transparent)
  vec4 ly1=shadeLayer(
    p*0.8+vec2(0.15, t*0.015), t,
    0.0, 2.0, 0.5,
    vec3(0.10, 0.06, 0.02),
    vec3(0.50, 0.38, 0.15),
    vec3(0.80, 0.65, 0.32),
    vec3(1.0, 0.92, 0.65),
    0.30, 26.0,
    L1, L2, V,
    u_sheenIntensity*0.7
  );

  // Layer 2: Middle — rose pink
  vec4 ly2=shadeLayer(
    p*1.0+vec2(t*0.012, -0.1), t,
    1.0, 3.2, 0.75,
    vec3(0.08, 0.03, 0.04),
    vec3(0.42, 0.18, 0.22),
    vec3(0.72, 0.38, 0.42),
    vec3(1.0, 0.82, 0.86),
    0.38, 40.0,
    L1, L2, V,
    u_sheenIntensity*0.9
  );

  // Layer 3: Front — soft lavender (fastest, most opaque)
  vec4 ly3=shadeLayer(
    p*1.2+vec2(-t*0.008, t*0.02), t,
    2.0, 4.5, 1.0,
    vec3(0.06, 0.04, 0.10),
    vec3(0.30, 0.22, 0.45),
    vec3(0.58, 0.48, 0.72),
    vec3(1.0, 0.90, 0.97),
    0.50, 55.0,
    L1, L2, V,
    u_sheenIntensity
  );

  // Composite back-to-front
  vec3 col=bg;
  col=mix(col, ly1.rgb, ly1.a);
  col+=vec3(0.35, 0.18, 0.08)*ly1.a*ly2.a*0.08;
  col=mix(col, ly2.rgb, ly2.a);
  col+=vec3(0.30, 0.15, 0.25)*ly2.a*ly3.a*0.06;
  col+=vec3(0.40, 0.25, 0.12)*ly1.a*ly2.a*ly3.a*0.04;
  col=mix(col, ly3.rgb, ly3.a);

  // Subtle backlight glow
  float cov=(ly1.a+ly2.a+ly3.a)*0.333;
  col+=vec3(0.35, 0.20, 0.12)*cov*0.04;

  // Vignette
  float vig=1.0-smoothstep(0.25, 1.15, length(p*vec2(0.85,1.0)));
  col*=0.6+0.4*vig;

  // Saturation boost
  float lum=dot(col, vec3(0.299, 0.587, 0.114));
  col=mix(vec3(lum), col, 1.35);

  // Tone mapping (ACES)
  col=col*(2.51*col+0.03)/(col*(2.43*col+0.59)+0.14);

  // Gamma
  col=pow(max(col,0.0), vec3(0.4545));

  // Film grain
  float grain=hash12(gl_FragCoord.xy+fract(u_time*7.13)*100.0);
  col+=(grain-0.5)*0.015;

  gl_FragColor=vec4(clamp(col,0.0,1.0), 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_heat;
uniform float u_turbulence;
uniform vec2 u_center;
uniform float u_scale;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash functions ──
float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash2(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

// ── Smooth value noise ──
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// ── Gradient noise (returns value + analytical derivatives) ──
vec3 noised(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  vec2 du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  float val = a + (b - a) * u.x + (c - a) * u.y + (a - b - c + d) * u.x * u.y;
  vec2 deriv = du * (vec2(b - a + (a - b - c + d) * u.y, c - a + (a - b - c + d) * u.x));
  return vec3(val, deriv);
}

// ── FBM with rotation between octaves ──
float fbm(vec2 p, int octaves) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    v += a * vnoise(p);
    p = rot * p * 2.05 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}

// ── FBM with derivatives for distortion ──
vec3 fbmd(vec2 p, int octaves) {
  float v = 0.0, a = 0.5;
  vec2 d = vec2(0.0);
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    vec3 n = noised(p);
    v += a * n.x;
    d += a * n.yz;
    p = rot * p * 2.05 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return vec3(v, d);
}

// ── Ridged noise for veins ──
float ridged(vec2 p, int octaves) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    float n = vnoise(p);
    n = 1.0 - abs(n * 2.0 - 1.0);
    n = n * n;
    v += a * n;
    p = rot * p * 2.1 + vec2(3.2, 1.3);
    a *= 0.5;
  }
  return v;
}

// ── Temperature color mapping ──
// Maps a 0-1 temperature value to a rich color palette:
// cool charcoal -> slate blue -> burnt sienna -> deep copper -> bright amber -> white-hot core
vec3 tempColor(float temp, float luminosityVar) {
  // Deep charcoal base
  vec3 c0 = vec3(0.04, 0.04, 0.055);
  // Cool slate blue
  vec3 c1 = vec3(0.08, 0.09, 0.14);
  // Neutral dark warm
  vec3 c2 = vec3(0.18, 0.12, 0.10);
  // Burnt sienna — brighter
  vec3 c3 = vec3(0.70, 0.28, 0.10);
  // Deep copper — bright
  vec3 c4 = vec3(1.2, 0.55, 0.14);
  // Warm amber — bright HDR
  vec3 c5 = vec3(1.8, 1.0, 0.25);
  // Bright amber — very bright HDR
  vec3 c6 = vec3(2.5, 1.6, 0.6);
  // White-hot core — very bright HDR
  vec3 c7 = vec3(3.5, 3.0, 2.5);

  vec3 col;
  if (temp < 0.12) {
    col = mix(c0, c1, temp / 0.12);
  } else if (temp < 0.25) {
    col = mix(c1, c2, (temp - 0.12) / 0.13);
  } else if (temp < 0.38) {
    col = mix(c2, c3, (temp - 0.25) / 0.13);
  } else if (temp < 0.52) {
    col = mix(c3, c4, (temp - 0.38) / 0.14);
  } else if (temp < 0.68) {
    col = mix(c4, c5, (temp - 0.52) / 0.16);
  } else if (temp < 0.85) {
    col = mix(c5, c6, (temp - 0.68) / 0.17);
  } else {
    col = mix(c6, c7, (temp - 0.85) / 0.15);
  }

  // Luminosity variation — brightness modulation
  col *= 1.0 + luminosityVar * 0.25;

  return col;
}

void main() {
  vec2 origin = u_scale > 0.0 ? u_center : vec2(0.5);
  float sc = u_scale > 0.0 ? u_scale : 1.0;
  vec2 uv = (gl_FragCoord.xy - u_res * origin) / (min(u_res.x, u_res.y) * sc);
  float t = u_time;
  float heat = u_heat;
  float turb = u_turbulence;

  // Aspect-corrected radial distance from center
  float dist = length(uv);

  // Mouse: creates a secondary heat source at cursor
  float mouseHeat = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * origin) / (min(u_res.x, u_res.y) * sc);
    float mDist = length(uv - mUV);
    mouseHeat = exp(-mDist * mDist * 4.0);
  }

  // ──────────────────────────────────────────
  // Layer 1: Base temperature field
  // Radial gradient from hot center to cool edges
  // with heavily animated turbulent noise deforming the boundary
  // ──────────────────────────────────────────

  // Multi-scale turbulence applied to the radial distance
  // Use cos/sin of angle instead of raw angle to avoid atan discontinuity seam
  float angle = atan(uv.y, uv.x);
  float ca = cos(angle);
  float sa = sin(angle);

  // Large-scale turbulence — slow breathing of the boundary
  float turb1 = fbm(vec2(ca * 1.5 + sa * 0.7 + t * 0.08, dist * 2.0 - t * 0.05) * 1.8, 5) * turb;

  // Medium-scale turbulence — faster, more detail
  float turb2 = fbm(vec2(ca * 3.0 - sa * 1.5 - t * 0.12, dist * 3.5 + t * 0.07) * 2.5 + vec2(50.0, 30.0), 4) * turb;

  // Fine-scale turbulence — rapid small variations
  float turb3 = fbm(vec2(ca * 5.0 + sa * 2.5 + t * 0.2, dist * 5.0 - t * 0.15) * 3.0 + vec2(100.0, 70.0), 3) * turb;

  // Combine turbulence at different scales
  float turbTotal = turb1 * 0.45 + turb2 * 0.35 + turb3 * 0.2;

  // Deform the radial distance with turbulence
  // The deformation is stronger at medium distances (the transition zone)
  float deformStrength = smoothstep(0.0, 0.3, dist) * smoothstep(0.9, 0.4, dist);
  float deformedDist = dist + (turbTotal - 0.5) * 0.35 * deformStrength;

  // Slow pulsation of the overall hot zone size
  float pulse = sin(t * 0.15) * 0.04 + sin(t * 0.23 + 1.7) * 0.03 + sin(t * 0.37 + 3.1) * 0.02;
  deformedDist -= pulse * heat;

  // Map deformed distance to temperature (0 = cool edge, 1 = hot center)
  float tempRange = 0.65 / heat;
  float temp = 1.0 - smoothstep(0.0, tempRange, deformedDist);
  // Add a sharper core
  float coreBoost = (1.0 - smoothstep(0.0, 0.15 / heat, deformedDist));
  temp = temp * 0.7 + coreBoost * 0.3;
  // Mouse heat source: boost temperature at cursor
  temp += mouseHeat * 0.6;
  temp = clamp(temp, 0.0, 1.0);

  // ──────────────────────────────────────────
  // Layer 2: Color mapping with luminosity variation
  // ──────────────────────────────────────────

  // Luminosity variation from noise — adds color richness
  float lumVar = fbm(uv * 4.0 + t * 0.06, 3) * 2.0 - 1.0;

  vec3 col = tempColor(temp, lumVar);

  // ──────────────────────────────────────────
  // Layer 3: Heat shimmer (UV distortion)
  // Distort the color field based on animated noise derivatives.
  // Strongest in the hot areas, zero at the cool edges.
  // ──────────────────────────────────────────

  // Heat shimmer — distort color using noise derivatives (no re-sampling)
  vec3 shimmerNoise = fbmd(uv * 8.0 + vec2(t * 0.3, t * 0.25), 4);
  float shimmerWave = shimmerNoise.x;
  vec2 shimmerDir = shimmerNoise.yz;

  // Shimmer creates bright/dark ripples in hot areas
  float shimmerStrength = temp * temp * turb;
  float shimmerRipple = dot(shimmerDir, vec2(0.7, 0.7));
  shimmerRipple = shimmerRipple * shimmerRipple * shimmerStrength;
  col += col * shimmerRipple * 0.4;

  // Extra shimmer highlights
  float shimmerHighlight = pow(max(shimmerWave, 0.0), 4.0) * temp * temp;
  col += vec3(1.0, 0.8, 0.4) * shimmerHighlight * 0.2 * heat;

  // ──────────────────────────────────────────
  // Layer 4: Turbulent veins (ridged noise convection currents)
  // Bright amber-gold filaments visible within the hot zone
  // ──────────────────────────────────────────

  // Primary vein network
  float veins1 = ridged(uv * 5.0 + vec2(t * 0.06, -t * 0.04), 4);
  // Secondary vein network at different scale/angle
  float veins2 = ridged(uv * 8.0 + vec2(-t * 0.08, t * 0.05) + vec2(20.0, 40.0), 3);
  // Tertiary fine detail
  float veins3 = ridged(uv * 13.0 + vec2(t * 0.1, t * 0.07) + vec2(60.0, 90.0), 2);

  float veins = veins1 * 0.5 + veins2 * 0.35 + veins3 * 0.15;

  // Sharpen the veins into filaments
  veins = smoothstep(0.3, 0.75, veins);
  veins = pow(veins, 2.0);

  // Veins only visible in the hot zone
  float veinMask = smoothstep(0.15, 0.5, temp) * smoothstep(1.0, 0.7, temp);
  float veinIntensity = veins * veinMask * 0.7 * heat;

  // Vein color — brighter amber-gold against the copper background
  vec3 veinColor = vec3(1.0, 0.72, 0.22);
  // Add slight color variation along the veins
  veinColor = mix(veinColor, vec3(1.0, 0.58, 0.15), veins2);
  col += veinColor * veinIntensity;

  // ──────────────────────────────────────────
  // Layer 5: Ember particles
  // Sparse bright points drifting upward in the hot zone.
  // Computed in the fragment shader using grid-based hashing.
  // ──────────────────────────────────────────

  // Grid for ember placement
  float emberScale = 18.0;
  vec2 emberUV = uv * emberScale;
  // Slow upward drift
  emberUV.y -= t * 0.4;
  // Very slight horizontal wander
  emberUV.x += sin(t * 0.3 + uv.y * 4.0) * 0.15;

  vec2 emberId = floor(emberUV);
  vec2 emberF = fract(emberUV) - 0.5;

  float embers = 0.0;
  // Check 3x3 neighborhood for sub-pixel positioning
  for (int ey = -1; ey <= 1; ey++) {
    for (int ex = -1; ex <= 1; ex++) {
      vec2 neighbor = vec2(float(ex), float(ey));
      vec2 cellId = emberId + neighbor;
      vec2 rnd = hash2(cellId);

      // Sparse: only ~8% of cells have an ember
      if (rnd.x > 0.08) continue;

      // Random position within cell
      vec2 emberPos = neighbor + rnd - 0.5;
      float emberDist = length(emberF - emberPos);

      // Animated brightness — embers flicker and fade in/out
      float phase = hash(cellId + vec2(77.0, 33.0));
      float life = fract(phase + t * 0.08);
      float brightness = sin(life * PI) * sin(life * PI);
      // Extra flicker
      brightness *= 0.5 + 0.5 * sin(t * 5.0 + phase * TAU);

      // Ember glow (very small, bright)
      float glow = smoothstep(0.08, 0.0, emberDist);
      // Tiny bright core
      float core = smoothstep(0.025, 0.0, emberDist) * 2.0;

      embers += (glow + core) * brightness;
    }
  }

  // Map ember grid back to world space for temperature masking
  float emberTemp = temp;
  // Embers only in hot zone
  float emberMask = smoothstep(0.2, 0.5, emberTemp);
  embers *= emberMask;

  // Ember color — bright amber-white
  vec3 emberColor = vec3(1.0, 0.85, 0.5);
  col += emberColor * embers * 0.12 * heat;

  // ──────────────────────────────────────────
  // Layer 6: Film grain
  // Warm-toned noise, denser in the transition zone
  // ──────────────────────────────────────────

  float grainSeed = hash(gl_FragCoord.xy + fract(t * 43.758) * 1000.0);
  float grain = (grainSeed - 0.5);

  // Grain density higher in the transition zone
  float transitionMask = smoothstep(0.1, 0.35, temp) * smoothstep(0.7, 0.35, temp);
  float grainStrength = 0.012 + transitionMask * 0.018;

  // Warm tint to the grain
  vec3 grainColor = vec3(grain * 1.1, grain * 0.95, grain * 0.75);
  col += grainColor * grainStrength;

  // ──────────────────────────────────────────
  // Final adjustments
  // ──────────────────────────────────────────

  // Subtle vignette to deepen the edges further
  float vig = length(uv * 1.1);
  float vignette = 1.0 - smoothstep(0.5, 1.3, vig) * 0.3;
  col *= vignette;

  // ACES filmic tone mapping — preserves bright highlights
  col = col * (2.51 * col + 0.03) / (col * (2.43 * col + 0.59) + 0.14);

  // Ensure no negative values
  col = max(col, vec3(0.0));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_intensity;
uniform float u_crustAmount;
uniform vec2 u_mouse;

#define PI 3.14159265359

// ── Hash & noise primitives ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453123);
}

vec2 hash2(vec2 p) {
  return vec2(
    fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453),
    fract(sin(dot(p, vec2(269.5, 183.3))) * 43758.5453)
  );
}

// Smooth value noise
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM — fractal Brownian motion
float fbm(vec2 p, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    val += amp * noise(p * freq);
    freq *= 2.03;
    amp *= 0.49;
    p += vec2(1.7, 9.2);
  }
  return val;
}

// Ridged noise — great for crack-like structures
float ridgedNoise(vec2 p) {
  return 1.0 - abs(noise(p) * 2.0 - 1.0);
}

// Ridged FBM for crack networks
float ridgedFBM(vec2 p, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  float prev = 1.0;
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    float n = ridgedNoise(p * freq);
    n = n * n;
    val += n * amp * prev;
    prev = n;
    freq *= 2.2;
    amp *= 0.5;
    p += vec2(1.3, 7.1);
  }
  return val;
}

// Voronoi for crust plate boundaries
float voronoi(vec2 p, out vec2 cellCenter) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float minDist = 1.0;
  float secondDist = 1.0;
  cellCenter = vec2(0.0);
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash2(i + neighbor);
      vec2 diff = neighbor + point - f;
      float d = dot(diff, diff);
      if (d < minDist) {
        secondDist = minDist;
        minDist = d;
        cellCenter = i + neighbor + point;
      } else if (d < secondDist) {
        secondDist = d;
      }
    }
  }
  return sqrt(secondDist) - sqrt(minDist);
}

// ── Domain warping for fluid magma motion ──
vec2 warpDomain(vec2 p, float t) {
  // Two layers of warping create churning fluid motion
  vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0) + t * vec2(0.12, -0.08), 5),
    fbm(p + vec2(5.2, 1.3) + t * vec2(-0.09, 0.14), 5)
  );
  vec2 r = vec2(
    fbm(p + 3.5 * q + vec2(1.7, 9.2) + t * vec2(0.06, 0.05), 5),
    fbm(p + 3.5 * q + vec2(8.3, 2.8) + t * vec2(-0.07, 0.08), 5)
  );
  return p + 2.5 * r;
}

// ── Thermal color mapping ──
// Maps temperature 0..1 to magma colors:
// black -> deep red -> orange -> yellow -> white-hot
vec3 magmaColor(float temp) {
  // Use smooth curves for natural-looking thermal gradient
  vec3 c;
  if (temp < 0.15) {
    // Nearly cooled — very dark red/black
    float t = temp / 0.15;
    c = mix(vec3(0.02, 0.005, 0.0), vec3(0.15, 0.02, 0.005), t);
  } else if (temp < 0.35) {
    // Dark red glow
    float t = (temp - 0.15) / 0.2;
    c = mix(vec3(0.15, 0.02, 0.005), vec3(0.55, 0.08, 0.01), t * t);
  } else if (temp < 0.55) {
    // Red to orange
    float t = (temp - 0.35) / 0.2;
    c = mix(vec3(0.55, 0.08, 0.01), vec3(0.9, 0.3, 0.02), t);
  } else if (temp < 0.72) {
    // Orange to bright yellow-orange
    float t = (temp - 0.55) / 0.17;
    c = mix(vec3(0.9, 0.3, 0.02), vec3(1.0, 0.65, 0.08), t);
  } else if (temp < 0.88) {
    // Bright yellow
    float t = (temp - 0.72) / 0.16;
    c = mix(vec3(1.0, 0.65, 0.08), vec3(1.0, 0.9, 0.4), t);
  } else {
    // White-hot
    float t = (temp - 0.88) / 0.12;
    c = mix(vec3(1.0, 0.9, 0.4), vec3(1.0, 1.0, 0.85), t);
  }
  return c;
}

void main() {
  vec2 fragCoord = gl_FragCoord.xy;
  vec2 uv = fragCoord / u_res;
  // Aspect-corrected coordinates centered at origin
  float aspect = u_res.x / u_res.y;
  vec2 p = (fragCoord - u_res * 0.5) / min(u_res.x, u_res.y);

  float t = u_time;

  // Mouse: compute heat eruption at cursor
  float mouseHeat = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mPos = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    float mDist = length(p - mPos);
    mouseHeat = exp(-mDist * mDist * 6.0);
  }

  // ────────────────────────────────────────────
  // UNIFIED MAGMA MATERIAL
  // Everything is computed from the same base field
  // ────────────────────────────────────────────

  // Scale for the magma surface — controls how zoomed in we are
  vec2 magmaUV = p * 3.0;

  // ── 1. Base convection flow ──
  // Domain-warped noise creates the churning fluid motion
  vec2 warped = warpDomain(magmaUV, t * 0.4);
  float baseFlow = fbm(warped, 7);

  // Second warp layer for extra turbulence at different scale
  vec2 warped2 = warpDomain(magmaUV * 1.3 + vec2(50.0), t * 0.35);
  float flow2 = fbm(warped2, 6);

  // Combine flows — this is the main convection pattern
  float convection = baseFlow * 0.6 + flow2 * 0.4;

  // ── 2. Crust formation from Voronoi cells ──
  // The crust forms naturally where the convection cools
  // Moving the voronoi field slowly creates drifting plates
  vec2 crustUV = magmaUV * 0.8 + t * vec2(0.03, -0.02);
  // Warp the crust coordinates by the convection flow itself
  // so the crust moves WITH the magma — unified motion
  crustUV += vec2(baseFlow, flow2) * 0.6;

  vec2 cellCenter;
  float crustEdge = voronoi(crustUV, cellCenter);

  // Second voronoi at different scale for subcracks
  vec2 cellCenter2;
  float subCracks = voronoi(crustUV * 2.5 + vec2(30.0), cellCenter2);

  // ── 3. Temperature field ──
  // This is the master field that controls everything
  // High temp = glowing magma, low temp = dark crust

  // Start with convection as base temperature
  float temp = convection;

  // The cracks (voronoi edges) are WHERE the hot magma shows through
  // Thin edges = bright cracks, wide cells = cooled crust
  float crackGlow = smoothstep(0.12 * u_crustAmount, 0.0, crustEdge);
  float subCrackGlow = smoothstep(0.08 * u_crustAmount, 0.0, subCracks) * 0.4;

  // Crust cools the surface
  float crustMask = smoothstep(0.0, 0.15 * u_crustAmount, crustEdge);
  // Each cell has a slightly different cooling rate
  float cellCool = hash(floor(cellCenter * 100.0)) * 0.3 + 0.5;
  float crustCooling = crustMask * cellCool * u_crustAmount;

  // Apply cooling — crust darkens the temperature
  temp = temp - crustCooling * 0.6;

  // But cracks reveal hot magma beneath
  temp = max(temp, crackGlow * 0.85);
  temp = max(temp, subCrackGlow * 0.5 + temp * 0.5);

  // ── 4. Hot spots — convection upwellings ──
  // These pulse and drift with the flow
  float hotSpotNoise = fbm(magmaUV * 0.5 + t * vec2(0.08, -0.06), 4);
  float hotSpots = smoothstep(0.55, 0.85, hotSpotNoise);
  // Hot spots push temperature up and eat through crust
  temp += hotSpots * 0.35 * u_intensity;

  // Slow, large pulsation — breathing of the lava lake
  float breathe = sin(t * 0.6) * 0.5 + 0.5;
  float breathe2 = sin(t * 0.37 + 2.0) * 0.5 + 0.5;
  temp += breathe * 0.08 + breathe2 * 0.05;

  // ── 5. Ridged detail for a natural look ──
  // Fine ridged noise adds those thin bright veins that lava has
  float veins = ridgedFBM(warped * 1.5 + t * 0.1, 5);
  // Veins are most visible in medium-temperature regions
  float veinMask = smoothstep(0.2, 0.4, temp) * smoothstep(0.8, 0.5, temp);
  temp += veins * veinMask * 0.15;

  // ── 6. Localized brightening events ──
  // Occasional bright flare-ups where crust breaks apart
  float flareNoise = noise(magmaUV * 1.2 + t * vec2(0.3, -0.2));
  float flare = pow(max(flareNoise - 0.65, 0.0) / 0.35, 3.0);
  temp += flare * 0.25 * u_intensity;

  // ── Mouse eruption: boost temperature at cursor ──
  temp += mouseHeat * 0.7;

  // ── Clamp temperature ──
  temp = clamp(temp * u_intensity, 0.0, 1.0);

  // ── 7. Convert temperature to color ──
  vec3 col = magmaColor(temp);

  // ── 8. Emissive glow for very hot areas ──
  // Hot regions cast light that brightens nearby pixels
  // (simulated by a soft bloom on high-temp areas)
  float glow = smoothstep(0.6, 1.0, temp);
  col += vec3(0.3, 0.08, 0.01) * glow * glow * 0.5;

  // ── 9. Crust surface texture ──
  // Cooled crust has subtle surface bumpiness
  float crustDetail = fbm(magmaUV * 8.0 + vec2(cellCool * 20.0), 4);
  float crustShade = crustMask * (0.8 + crustDetail * 0.4);
  // Darken the crust slightly with texture
  col *= mix(1.0, 0.7 + crustDetail * 0.3, crustMask * u_crustAmount * 0.5);

  // ── 10. Heat haze / atmospheric distortion ──
  // Subtle color shift simulating heat shimmer above surface
  float haze = fbm(p * 2.0 + t * vec2(0.15, 0.4), 3);
  float hazeStrength = smoothstep(0.5, 1.0, temp) * 0.08;
  col += vec3(0.15, 0.04, 0.0) * haze * hazeStrength;

  // ── 11. Very subtle cool ambient at edges ──
  // The edge of the "view" into the lava lake darkens slightly
  float edgeDist = length(p * vec2(1.0, 1.3));
  float edgeFade = smoothstep(0.7, 1.4, edgeDist);
  // Edges cool more — thicker crust at the rim
  float edgeCool = edgeFade * 0.3;
  col = mix(col, col * vec3(0.3, 0.1, 0.08), edgeCool);

  // ── 12. Vignette ──
  float vignette = 1.0 - smoothstep(0.5, 1.5, edgeDist);
  col *= 0.65 + vignette * 0.35;

  // ── 13. Tone mapping — prevent harsh clipping ──
  col = col / (1.0 + col * 0.15);

  // ── 14. Final color grading ──
  // Slight push toward warm amber in the midtones
  col = pow(col, vec3(0.95, 1.0, 1.1));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_layerSpeed;
uniform float u_layerCount;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash functions for noise ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float hash3(vec3 p) {
  return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123);
}

// ── Smooth 2D value noise ──
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── FBM (fractal Brownian motion) ──
float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * vnoise(p * freq);
    freq *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// ── Domain-warped noise for organic flowing shapes ──
float warpedNoise(vec2 p, float t, float seed) {
  vec2 q = vec2(
    fbm(p + vec2(seed * 1.7, seed * 2.3) + t * 0.15),
    fbm(p + vec2(seed * 3.1 + 5.2, seed * 1.3 + 1.3) + t * 0.12)
  );
  vec2 r = vec2(
    fbm(p + 4.0 * q + vec2(1.7, 9.2) + t * 0.08),
    fbm(p + 4.0 * q + vec2(8.3, 2.8) + t * 0.1)
  );
  return fbm(p + 3.5 * r);
}

// ── Rotation matrix ──
mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  vec2 aspect = vec2(u_res.x / u_res.y, 1.0);
  vec2 p = uv * aspect;
  float t = u_time * u_layerSpeed;

  // Mouse-driven veil shift
  vec2 mouseShift = vec2(0.0);
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res;
    mouseShift = (mUV - 0.5) * aspect * 0.3;
  }

  // ── Warm amber palette colors per layer ──
  // From deepest (darkest) to frontmost (brightest)
  // Layer 0: deep sepia
  // Layer 1: warm brown
  // Layer 2: copper
  // Layer 3: amber gold
  // Layer 4: bright amber
  // Layer 5: pale gold
  // Layer 6: warm cream

  // ── Accumulate color from back to front ──
  vec3 col = vec3(0.012, 0.01, 0.008); // Dark background base

  int maxLayers = 7;

  for (int i = 0; i < 7; i++) {
    if (float(i) >= u_layerCount) break;

    float fi = float(i);
    float layerFrac = fi / max(u_layerCount - 1.0, 1.0);

    // ── Each layer has unique movement ──
    // Different speed, direction, and scale per layer
    float speed = 0.3 + fi * 0.12;
    float scale = 1.8 + fi * 0.7;
    float angle = fi * 0.7 + 0.3;

    // Parallax offset — deeper layers move slower
    float parallax = 0.3 + layerFrac * 0.7;

    // Direction of drift per layer
    vec2 drift = vec2(
      cos(angle) * speed * t * parallax,
      sin(angle) * speed * t * parallax * 0.7
    );

    // Rotate coordinates slightly per layer for variety
    vec2 lp = (p - 0.5 * aspect + mouseShift * (0.5 + layerFrac * 0.5)) * rot2(fi * 0.4 + t * 0.02 * (fi - 2.5)) + 0.5 * aspect;
    lp = lp * scale + drift;

    // ── Domain-warped noise for flowing veil shape ──
    float n = warpedNoise(lp, t * (0.8 + fi * 0.15), fi * 3.7 + 1.0);

    // ── Shape the veil: soft edges, flowing contours ──
    // Use smoothstep to create soft, curtain-like regions
    float veil = smoothstep(0.25, 0.55, n);
    veil *= smoothstep(0.85, 0.6, n);
    // Broaden some veils for variety
    float broad = smoothstep(0.2, 0.7, n) * 0.5;
    veil = max(veil, broad);

    // ── Occasional transparency fade — reveals deeper layers ──
    // Each layer periodically becomes more transparent
    float fadePhase = t * 0.15 + fi * 1.3;
    float fadeCycle = sin(fadePhase) * 0.5 + 0.5;
    // Occasionally dip to near-zero opacity
    float reveal = smoothstep(0.0, 0.3, fadeCycle);
    // Mix between partial and full transparency
    float opacity = mix(0.08, 0.55, reveal);

    // Deeper layers slightly more opaque to build depth
    opacity *= (0.6 + 0.4 * (1.0 - layerFrac));

    // ── Layer color from the warm amber family ──
    vec3 layerColor;
    if (i == 0) {
      layerColor = vec3(0.12, 0.07, 0.04); // deep sepia
    } else if (i == 1) {
      layerColor = vec3(0.22, 0.12, 0.06); // warm brown
    } else if (i == 2) {
      layerColor = vec3(0.45, 0.25, 0.12); // copper
    } else if (i == 3) {
      layerColor = vec3(0.65, 0.42, 0.15); // amber gold
    } else if (i == 4) {
      layerColor = vec3(0.78, 0.55, 0.22); // bright amber
    } else if (i == 5) {
      layerColor = vec3(0.85, 0.65, 0.35); // pale gold
    } else {
      layerColor = vec3(0.9, 0.75, 0.5); // warm cream
    }

    // ── Subtle color variation within each layer ──
    float colorShift = sin(n * 6.0 + t * 0.3 + fi * 2.0) * 0.05;
    layerColor += colorShift;

    // ── Add subtle inner glow at veil edges ──
    float edgeGlow = smoothstep(0.0, 0.15, veil) * smoothstep(0.5, 0.25, veil);
    vec3 glowColor = layerColor * 1.4 + vec3(0.1, 0.06, 0.02);
    layerColor = mix(layerColor, glowColor, edgeGlow * 0.5);

    // ── Composite this layer over the accumulated color ──
    float alpha = veil * opacity;
    col = mix(col, layerColor, alpha);
  }

  // ── Subtle overall atmospheric glow ──
  // Warm center glow to add depth
  vec2 center = (uv - 0.5) * aspect;
  float centerDist = length(center);
  float atmosGlow = exp(-centerDist * centerDist * 2.0) * 0.04;
  col += vec3(0.6, 0.4, 0.2) * atmosGlow;

  // ── Subtle breathing pulse on the whole image ──
  float breathe = sin(u_time * 0.2) * 0.02 + 1.0;
  col *= breathe;

  // ── Tone mapping (subtle, keep the dark mood) ──
  col = col / (col + 0.5) * 1.1;

  // ── Slight warmth push ──
  col = pow(col, vec3(0.95, 0.98, 1.05));

  // ── Soft vignette ──
  float vig = 1.0 - dot(center / aspect, center / aspect) * 0.6;
  vig = smoothstep(0.0, 1.0, vig);
  col *= vig;

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_symmetry;
uniform float u_patternSpeed;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Rotation matrix ──
mat2 rot(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// ── Hash for pseudo-random values ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// ── Smooth noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── Kaleidoscope UV folding ──
// Folds the UV space into N symmetric mirror segments
vec2 kaleidoscope(vec2 uv, float segments) {
  float angle = atan(uv.y, uv.x);
  float r = length(uv);
  // Fold into segment
  float segAngle = TAU / segments;
  angle = mod(angle, segAngle);
  // Mirror alternate segments for true kaleidoscope
  angle = abs(angle - segAngle * 0.5);
  return vec2(cos(angle), sin(angle)) * r;
}

// ── Sharp geometric stripe pattern ──
float stripePattern(vec2 p, float t) {
  float s1 = step(0.5, fract(p.x * 3.0 + t * 0.3));
  float s2 = step(0.5, fract(p.y * 4.0 - t * 0.2));
  return s1 * 0.5 + s2 * 0.5;
}

// ── Chevron / herringbone pattern ──
float chevronPattern(vec2 p, float t) {
  float y = p.y + t * 0.15;
  float chevron = abs(fract(p.x * 2.0) - 0.5) * 2.0;
  chevron = abs(fract(chevron + y * 3.0) - 0.5) * 2.0;
  return smoothstep(0.3, 0.35, chevron);
}

// ── Diamond / rhombus pattern ──
float diamondPattern(vec2 p, float t) {
  vec2 q = rot(PI * 0.25) * p;
  float d = abs(fract(q.x * 2.5 + t * 0.1) - 0.5) + abs(fract(q.y * 2.5 - t * 0.08) - 0.5);
  return smoothstep(0.4, 0.42, d);
}

// ── Triangle grid pattern ──
float trianglePattern(vec2 p, float t) {
  vec2 q = p * 3.0;
  q.x += floor(q.y) * 0.5;
  vec2 f = fract(q) - 0.5;
  float tri = abs(f.x) + abs(f.y);
  float anim = sin(t * 0.4 + floor(q.x) * 1.3 + floor(q.y) * 0.7) * 0.15;
  return smoothstep(0.45 + anim, 0.47 + anim, tri);
}

// ── Palette: warm gold, deep amber, bright copper, hot pink ──
vec3 palette(float t, float patIdx) {
  // Five key colors that cycle
  vec3 c0 = vec3(0.85, 0.65, 0.15);  // warm gold
  vec3 c1 = vec3(0.60, 0.30, 0.08);  // deep amber
  vec3 c2 = vec3(0.90, 0.50, 0.18);  // bright copper
  vec3 c3 = vec3(0.92, 0.25, 0.45);  // hot pink
  vec3 c4 = vec3(1.00, 0.78, 0.30);  // bright gold

  float phase = fract(t + patIdx * 0.2);
  vec3 col;
  if (phase < 0.2) {
    col = mix(c0, c1, phase / 0.2);
  } else if (phase < 0.4) {
    col = mix(c1, c2, (phase - 0.2) / 0.2);
  } else if (phase < 0.6) {
    col = mix(c2, c3, (phase - 0.4) / 0.2);
  } else if (phase < 0.8) {
    col = mix(c3, c4, (phase - 0.6) / 0.2);
  } else {
    col = mix(c4, c0, (phase - 0.8) / 0.2);
  }
  return col;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  float t = u_time * u_patternSpeed;
  float segments = u_symmetry;

  // ── Rotation: auto + drag offset ──
  float globalRot = t * 0.12 + u_mouse.x;
  uv = rot(globalRot) * uv;

  float r = length(uv);

  // ── Apply kaleidoscope folding ──
  vec2 kuv = kaleidoscope(uv, segments);

  // ── Animate the pattern space ──
  // Radial zoom that breathes in and out
  float zoomPulse = 1.0 + sin(t * 0.35) * 0.15;
  kuv *= zoomPulse;

  // Slowly drift the pattern origin for evolution
  kuv += vec2(t * 0.05, t * 0.03);

  // ── Layer 1: Chevron textile pattern ──
  float chev = chevronPattern(kuv * 1.2, t);

  // ── Layer 2: Diamond facets ──
  float diam = diamondPattern(kuv * 0.8 + vec2(t * 0.02), t * 1.2);

  // ── Layer 3: Stripes (fashion runway stripes) ──
  vec2 stripeUV = rot(t * 0.08) * kuv;
  float stripe = stripePattern(stripeUV * 1.5, t);

  // ── Layer 4: Triangle tessellation ──
  float tri = trianglePattern(kuv * 0.9 + vec2(sin(t * 0.2) * 0.3), t);

  // ── Morph between patterns over time ──
  // Smoothly crossfade between the four pattern layers
  float morphPhase = fract(t * 0.06);
  float m0 = smoothstep(0.0, 0.1, morphPhase) * smoothstep(0.35, 0.25, morphPhase);
  float m1 = smoothstep(0.2, 0.3, morphPhase) * smoothstep(0.55, 0.45, morphPhase);
  float m2 = smoothstep(0.4, 0.5, morphPhase) * smoothstep(0.75, 0.65, morphPhase);
  float m3 = smoothstep(0.6, 0.7, morphPhase) * smoothstep(0.95, 0.85, morphPhase);
  // Ensure there is always something visible
  float mSum = m0 + m1 + m2 + m3;
  if (mSum < 0.3) {
    m0 = max(m0, 0.3);
    m1 = max(m1, 0.2);
  }

  float pattern = chev * m0 + diam * m1 + stripe * m2 + tri * m3;
  // Add a persistent base layer so patterns never fully vanish
  float basePat = diamondPattern(kuv * 1.1, t * 0.7) * 0.35;
  pattern = max(pattern, basePat);

  // ── Second kaleidoscope fold at different scale for depth ──
  vec2 kuv2 = kaleidoscope(uv * 1.3, segments + 2.0);
  kuv2 *= 1.0 + sin(t * 0.25) * 0.1;
  kuv2 += vec2(t * 0.03, -t * 0.04);
  float innerPattern = chevronPattern(kuv2, t * 0.8) * 0.4;
  innerPattern += trianglePattern(kuv2 * 1.2, t * 0.6) * 0.3;

  // ── Color assignment ──
  // Primary pattern color shifts over time
  float colorPhase = t * 0.04 + r * 0.5;
  vec3 col1 = palette(colorPhase, 0.0);
  vec3 col2 = palette(colorPhase + 0.3, 1.0);
  vec3 col3 = palette(colorPhase + 0.6, 2.0);

  // Build the color from pattern layers
  vec3 col = vec3(0.02, 0.015, 0.01); // Dark base

  // Primary kaleidoscope pattern
  col = mix(col, col1 * 1.1, pattern * 0.7);

  // Inner detail pattern with second color
  col = mix(col, col2, innerPattern * 0.5);

  // ── Geometric edge highlights ──
  // Emphasize the fold lines of the kaleidoscope
  float foldAngle = atan(uv.y, uv.x);
  float segAngle = TAU / segments;
  float foldDist = abs(sin(foldAngle * segments * 0.5));
  float foldLine = smoothstep(0.02, 0.0, 1.0 - foldDist) * 0.6;
  // Animate the fold brightness
  foldLine *= 0.5 + 0.5 * sin(t * 0.5 + r * 4.0);
  col += col3 * foldLine;

  // ── Radial gradient layers for depth ──
  // Concentric rings that pulse
  float rings = sin(r * 12.0 - t * 1.5) * 0.5 + 0.5;
  rings = smoothstep(0.4, 0.6, rings) * 0.15;
  col += palette(colorPhase + 0.5, 3.0) * rings * (1.0 - r);

  // ── Bright center focal point ──
  float centerGlow = exp(-r * r * 8.0);
  vec3 centerColor = mix(
    vec3(1.0, 0.85, 0.45),  // bright gold
    vec3(1.0, 0.55, 0.65),  // warm pink-gold
    sin(t * 0.3) * 0.5 + 0.5
  );
  col += centerColor * centerGlow * 0.7;

  // ── Secondary center detail — mandala star ──
  float starAngle = atan(uv.y, uv.x);
  float star = abs(sin(starAngle * segments * 0.5 + t * 0.4));
  star = pow(star, 8.0) * exp(-r * 3.0);
  col += vec3(1.0, 0.9, 0.6) * star * 0.4;

  // ── Hot pink accent flashes ──
  // Fashion-bold color pops that appear and disappear
  float pinkFlash = sin(t * 0.7 + r * 6.0) * cos(foldAngle * 3.0 + t * 0.4);
  pinkFlash = pow(max(pinkFlash, 0.0), 6.0) * 0.8;
  col += vec3(0.95, 0.2, 0.5) * pinkFlash * (1.0 - r * 0.5);

  // ── Outer fade — mandala dissolves at edges ──
  float edgeFade = smoothstep(0.9, 0.5, r);
  col *= edgeFade;

  // ── Subtle noise texture for fabric feel ──
  float tex = noise(gl_FragCoord.xy * 0.5) * 0.04 - 0.02;
  col += tex;

  // ── Tone mapping ──
  col = col / (1.0 + col * 0.3);

  // ── Warmth push ──
  col = pow(max(col, vec3(0.0)), vec3(0.92, 0.96, 1.06));

  // ── Vignette ──
  float vig = 1.0 - dot(uv, uv) * 0.4;
  col *= max(vig, 0.0);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_speed;
uniform float u_glow;
uniform vec2 u_mouse;

// ── Horizon position ──
const float HORIZON = 0.38;

// ── Hash / noise helpers ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── Sun shape with layered glow ──
vec3 sun(vec2 uv, float t) {
  vec2 sunPos = vec2(0.0, HORIZON + 0.18);
  float sunRadius = 0.12;
  float d = length(uv - sunPos);

  // Horizontal scanlines through the sun
  float scanline = 0.0;
  if (uv.y < sunPos.y && uv.y > sunPos.y - sunRadius) {
    float band = (sunPos.y - uv.y) / sunRadius;
    float lineSpacing = 0.028 + band * 0.06;
    float lineY = mod(uv.y + 0.001, lineSpacing);
    scanline = smoothstep(0.0, 0.003, lineY) * smoothstep(lineSpacing, lineSpacing - 0.003, lineY);
    scanline *= smoothstep(0.0, 0.4, band);
  }

  // Sun disc with gradient
  float sunMask = smoothstep(sunRadius + 0.003, sunRadius - 0.003, d);
  vec3 sunColorTop = vec3(1.0, 0.85, 0.1);
  vec3 sunColorBot = vec3(1.0, 0.15, 0.4);
  float sunGradient = smoothstep(sunPos.y + sunRadius, sunPos.y - sunRadius, uv.y);
  vec3 sunCol = mix(sunColorTop, sunColorBot, sunGradient);
  sunCol *= sunMask;

  // Cut out scanline bands from lower half of sun
  sunCol *= mix(1.0, scanline, smoothstep(sunPos.y, sunPos.y - sunRadius, uv.y) * 0.85);

  // Multi-layered glow around the sun
  float glow1 = exp(-d * 4.0) * 0.5;
  float glow2 = exp(-d * 10.0) * 0.3;
  float glow3 = exp(-d * 25.0) * 0.2;
  vec3 glowCol = vec3(1.0, 0.3, 0.5) * glow1 +
                 vec3(1.0, 0.6, 0.2) * glow2 +
                 vec3(1.0, 0.9, 0.5) * glow3;

  return sunCol + glowCol;
}

// ── Sky gradient with stars ──
vec3 sky(vec2 uv, float t) {
  // Deep purple to hot pink to orange gradient
  float skyY = (uv.y - HORIZON) / (1.0 - HORIZON);
  skyY = clamp(skyY, 0.0, 1.0);

  vec3 colBot = vec3(0.6, 0.05, 0.3);   // hot pink at horizon
  vec3 colMid = vec3(0.25, 0.02, 0.35);  // deep purple
  vec3 colTop = vec3(0.02, 0.01, 0.08);  // near black

  vec3 col = mix(colBot, colMid, smoothstep(0.0, 0.35, skyY));
  col = mix(col, colTop, smoothstep(0.25, 0.85, skyY));

  // Horizon haze — warm orange glow right at the horizon
  float hazeStrength = exp(-skyY * 8.0) * 0.7;
  col += vec3(1.0, 0.4, 0.1) * hazeStrength;

  // Stars
  float starField = hash(floor(uv * 200.0));
  float starMask = smoothstep(0.3, 0.9, skyY);
  float twinkle = sin(t * 2.0 + starField * 50.0) * 0.5 + 0.5;
  float star = smoothstep(0.992, 0.999, starField) * starMask * (0.5 + 0.5 * twinkle);
  col += vec3(0.8, 0.7, 1.0) * star;

  // Add sun
  col += sun(uv, t);

  return col;
}

// ── Perspective grid road ──
vec3 grid(vec2 uv, float t) {
  // Road below horizon
  float roadY = HORIZON - uv.y;
  if (roadY <= 0.0) return vec3(0.0);

  // Perspective projection: map screen Y to world Z
  // Higher constant = more grid cells visible = denser grid
  float perspective = 1.5 / roadY;
  float worldX = uv.x * perspective;
  float worldZ = perspective;

  // Forward motion
  float speed = t * u_speed * 3.0;
  worldZ += speed;

  // ── Grid lines ──

  // Z lines (horizontal in perspective, running left-right)
  float zLine = abs(fract(worldZ * 0.5) - 0.5);
  float zLineWidth = clamp(perspective * 0.001, 0.01, 0.12);
  float zGrid = smoothstep(zLineWidth, 0.0, zLine);

  // X lines (vertical in perspective, running into distance)
  float xLine = abs(fract(worldX * 0.25) - 0.5);
  float xLineWidth = clamp(perspective * 0.0005, 0.006, 0.08);
  float xGrid = smoothstep(xLineWidth, 0.0, xLine);

  float gridVal = max(zGrid, xGrid);

  // Distance fade — fade in from horizon, stay visible to camera
  float fadeIn = smoothstep(0.0, 0.05, roadY);

  // Brightness increases slightly near camera for depth cue
  float proxBright = 0.5 + 0.5 * smoothstep(0.0, 0.4, roadY);

  // Grid colors: main neon pink/magenta, with cyan accents
  vec3 gridColor = vec3(0.9, 0.1, 0.6);

  // Accent every 4th line with cyan
  float zMajor = abs(fract(worldZ * 0.125) - 0.5);
  float zMajorLine = smoothstep(zLineWidth * 0.5, 0.0, zMajor);
  float xMajor = abs(fract(worldX * 0.0625) - 0.5);
  float xMajorLine = smoothstep(xLineWidth * 0.5, 0.0, xMajor);
  float majorGrid = max(zMajorLine, xMajorLine);

  vec3 accentColor = vec3(0.1, 0.6, 1.0);
  gridColor = mix(gridColor, accentColor, majorGrid * 0.4);

  // Grid glow — soft bloom around grid lines
  float zGlow = exp(-zLine * 20.0) * 0.25;
  float xGlow = exp(-xLine * 20.0) * 0.2;
  float gridGlow = max(zGlow, xGlow);

  vec3 col = gridColor * gridVal * proxBright * fadeIn;
  col += gridColor * gridGlow * fadeIn * 0.7;

  // Ground base color — very dark with slight purple tint
  vec3 groundColor = vec3(0.02, 0.01, 0.04);
  col += groundColor;

  // Horizon fog glow — warm/pink mist at the horizon
  float fogBand = exp(-roadY * 10.0);
  col += vec3(0.5, 0.1, 0.35) * fogBand * 0.5;

  return col;
}

// ── Side terrain / mountains ──
vec3 mountains(vec2 uv, float t) {
  if (uv.y < HORIZON) return vec3(0.0);

  float mountainY = HORIZON;
  float au = abs(uv.x);

  // Mountain silhouette using layered noise
  float m1 = noise(vec2(au * 3.0, 0.0)) * 0.08;
  float m2 = noise(vec2(au * 8.0, 1.0)) * 0.03;
  float m3 = noise(vec2(au * 20.0, 2.0)) * 0.01;
  float mountainHeight = m1 + m2 + m3;

  // Only show mountains on the sides
  float sideMask = smoothstep(0.15, 0.5, au);
  mountainHeight *= sideMask;

  float mountainTop = HORIZON + mountainHeight;
  float mountainMask = smoothstep(mountainTop + 0.005, mountainTop - 0.002, uv.y);

  // Dark silhouette with subtle purple edge light
  vec3 col = vec3(0.015, 0.005, 0.03) * mountainMask;

  // Edge glow along the mountain ridge
  float edgeDist = abs(uv.y - mountainTop);
  float edgeGlow = exp(-edgeDist * 200.0) * sideMask;
  col += vec3(0.6, 0.1, 0.5) * edgeGlow * 0.3;

  return col;
}

// ── Side grid (ground extending beyond the road) ──
vec3 sideGrid(vec2 uv, float t) {
  float roadY = HORIZON - uv.y;
  if (roadY <= 0.0) return vec3(0.0);

  float perspective = 1.5 / roadY;
  float worldX = uv.x * perspective;
  float worldZ = perspective + t * u_speed * 3.0;

  // Same grid density as the road
  float zLine = abs(fract(worldZ * 0.5) - 0.5);
  float xLine = abs(fract(worldX * 0.25) - 0.5);

  float zLineWidth = clamp(perspective * 0.0008, 0.008, 0.08);
  float xLineWidth = clamp(perspective * 0.0004, 0.004, 0.06);

  float zGrid = smoothstep(zLineWidth, 0.0, zLine);
  float xGrid = smoothstep(xLineWidth, 0.0, xLine);
  float gridVal = max(zGrid, xGrid);

  float fadeIn = smoothstep(0.0, 0.05, roadY);

  // Slightly different color for side terrain grid — purple
  vec3 sideColor = vec3(0.4, 0.05, 0.6);
  return sideColor * gridVal * fadeIn * 0.35;
}

// ── Sun reflection on road ──
vec3 sunReflection(vec2 uv, float t) {
  float roadY = HORIZON - uv.y;
  if (roadY <= 0.0) return vec3(0.0);

  // Reflection of the sun centered on the road
  float reflectWidth = 0.15 / (roadY * 3.0 + 0.3);
  float xDist = abs(uv.x);
  float reflStrength = exp(-xDist * xDist / (reflectWidth * reflectWidth * 0.02));

  // Shimmer effect
  float perspective = 1.5 / roadY;
  float worldZ = perspective + t * u_speed * 3.0;
  float shimmer = noise(vec2(uv.x * 30.0, worldZ * 2.0)) * 0.5 + 0.5;

  // Color gradient from warm to pink
  float gradT = smoothstep(0.0, 0.25, roadY);
  vec3 reflColor = mix(vec3(1.0, 0.5, 0.2), vec3(1.0, 0.15, 0.4), gradT);

  float fadeNear = smoothstep(0.35, 0.05, roadY);
  float fadeFar = smoothstep(0.0, 0.01, roadY);

  return reflColor * reflStrength * shimmer * fadeNear * fadeFar * 0.15;
}

// ── Center road line ──
vec3 centerLine(vec2 uv, float t) {
  float roadY = HORIZON - uv.y;
  if (roadY <= 0.0) return vec3(0.0);

  float perspective = 1.5 / roadY;
  float worldZ = perspective + t * u_speed * 3.0;

  // Dashed center line
  float dashPattern = step(0.5, fract(worldZ * 0.12));

  // Line width in screen space narrows toward horizon
  float lineWidth = 0.003 / (perspective * 0.05 + 0.1);
  lineWidth = clamp(lineWidth, 0.0005, 0.01);

  float lineMask = smoothstep(lineWidth, 0.0, abs(uv.x));
  float distFade = smoothstep(0.0, 0.02, roadY) * smoothstep(0.35, 0.05, roadY);

  return vec3(0.9, 0.8, 0.6) * lineMask * dashPattern * distFade * 0.5;
}

// ── Road edge glow lines ──
vec3 roadEdges(vec2 uv, float t) {
  float roadY = HORIZON - uv.y;
  if (roadY <= 0.0) return vec3(0.0);

  // Road edges converge toward center at horizon
  float roadHalfWidth = roadY * 0.8 + 0.001;

  float leftEdge = abs(uv.x + roadHalfWidth);
  float rightEdge = abs(uv.x - roadHalfWidth);
  float edgeDist = min(leftEdge, rightEdge);

  float lineWidth = 0.002;
  float edgeLine = smoothstep(lineWidth, 0.0, edgeDist);
  float edgeGlow = exp(-edgeDist * 300.0) * 0.4;

  float distFade = smoothstep(0.0, 0.015, roadY) * smoothstep(0.35, 0.02, roadY);

  vec3 edgeColor = vec3(0.1, 0.7, 1.0);
  return edgeColor * (edgeLine + edgeGlow) * distFade;
}

// ── Atmospheric haze particles ──
float haze(vec2 uv, float t) {
  float n1 = noise(uv * 3.0 + vec2(t * 0.1, 0.0));
  float n2 = noise(uv * 7.0 + vec2(0.0, t * 0.15));
  float n3 = noise(uv * 15.0 + vec2(t * 0.05, t * 0.08));
  return (n1 * 0.5 + n2 * 0.3 + n3 * 0.2);
}

// ── Vignette ──
float vignette(vec2 uv) {
  float d = length(uv * vec2(0.8, 1.0));
  return smoothstep(1.2, 0.4, d);
}

// ── CRT scanline effect (subtle) ──
float scanlines(vec2 fragCoord) {
  return 0.95 + 0.05 * sin(fragCoord.y * 3.14159 * 1.5);
}

void main() {
  // ── Mouse: shift vanishing point ──
  vec2 vpShift = vec2(0.0);
  if (u_mouse.x > 0.0) {
    vec2 mNorm = u_mouse / u_res;
    vpShift = (mNorm - 0.5) * vec2(0.3, 0.15);
  }
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / u_res.y - vpShift;
  vec2 screenUV = gl_FragCoord.xy / u_res;
  float t = u_time;

  vec3 col = vec3(0.0);

  // Sky above horizon
  if (uv.y >= HORIZON) {
    col = sky(uv, t);

    // Mountain silhouettes
    vec3 mtn = mountains(uv, t);
    // Mountains are dark, so they replace sky where present
    float mtnMask = step(0.001, mtn.r + mtn.g + mtn.b);
    col = mix(col, mtn, mtnMask * 0.7);
    // Add mountain edge glow on top
    col += mtn * 2.0 * (1.0 - mtnMask);
  }

  // Grid road below horizon
  col += grid(uv, t);

  // Side grid
  col += sideGrid(uv, t);

  // Sun reflection on road surface
  col += sunReflection(uv, t);

  // Road edge glow
  col += roadEdges(uv, t);

  // Center dashed line
  col += centerLine(uv, t);

  // Atmospheric haze near horizon
  float horizonDist = abs(uv.y - HORIZON);
  float hazeMask = exp(-horizonDist * 15.0);
  float hazeVal = haze(uv, t);
  col += vec3(0.5, 0.15, 0.4) * hazeVal * hazeMask * 0.15;

  // Global glow control
  col *= u_glow;

  // Vignette
  col *= vignette(uv);

  // Subtle scanlines for CRT feel
  col *= scanlines(gl_FragCoord.xy);

  // Tone mapping — slight S-curve for richer darks
  col = col / (col + vec3(0.8));
  col = pow(col, vec3(0.95));

  // Very slight chromatic shift at edges
  float chromDist = length(uv * vec2(0.5, 0.7));
  float chromShift = chromDist * 0.003;
  vec3 finalCol;
  vec2 uvR = (gl_FragCoord.xy + vec2(chromShift * u_res.y, 0.0) - u_res * 0.5) / u_res.y;
  vec2 uvB = (gl_FragCoord.xy - vec2(chromShift * u_res.y, 0.0) - u_res * 0.5) / u_res.y;

  // Only apply chroma to the final composite for performance
  finalCol.r = col.r * (1.0 + chromShift * 2.0);
  finalCol.g = col.g;
  finalCol.b = col.b * (1.0 + chromShift * 2.0);

  gl_FragColor = vec4(finalCol, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_flowSpeed;
uniform float u_viscosity;
uniform vec2 u_mouse;

#define PI 3.14159265359

// ── Hash for pseudo-random ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// ── Smooth value noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── FBM with viscosity-controlled octave decay ──
float fbm(vec2 p, float t, float visc) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  float decay = 0.45 + visc * 0.2;
  for (int i = 0; i < 6; i++) {
    val += amp * noise(p * freq + t);
    freq *= 2.0 + visc * 0.3;
    amp *= decay;
    p += vec2(1.7, 9.2);
  }
  return val;
}

// ── Domain warping for viscous flow ──
float warpedField(vec2 p, float t, float visc) {
  // First warp layer — large slow currents
  vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0), t * 0.5, visc),
    fbm(p + vec2(5.2, 1.3), t * 0.5, visc)
  );

  // Second warp — medium flow detail
  vec2 r = vec2(
    fbm(p + 3.0 * q + vec2(1.7, 9.2), t * 0.7, visc),
    fbm(p + 3.0 * q + vec2(8.3, 2.8), t * 0.7, visc)
  );

  // Third warp — fine ripples and tension effects
  float f = fbm(p + 2.5 * r, t * 0.4, visc);

  // Combine warp magnitudes for surface detail
  return f + length(q) * 0.4 + length(r) * 0.3;
}

// ── Metaball-like surface bumps ──
float metaballs(vec2 p, float t) {
  float val = 0.0;
  for (int i = 0; i < 7; i++) {
    float fi = float(i);
    vec2 center = vec2(
      sin(t * 0.3 + fi * 2.1) * 0.6 + cos(t * 0.2 + fi * 1.3) * 0.3,
      cos(t * 0.25 + fi * 1.7) * 0.6 + sin(t * 0.15 + fi * 2.5) * 0.3
    );
    float radius = 0.15 + 0.1 * sin(t * 0.4 + fi * 3.0);
    float d = length(p - center);
    val += radius / (d + 0.05);
  }
  return val;
}

// ── Surface normal estimation for lighting ──
vec3 getNormal(vec2 p, float t, float visc, float warpCenter) {
  float eps = 0.005;
  float hC = warpCenter + metaballs(p, t) * 0.08;
  float hR = warpedField(p + vec2(eps, 0.0), t, visc) + metaballs(p + vec2(eps, 0.0), t) * 0.08;
  float hU = warpedField(p + vec2(0.0, eps), t, visc) + metaballs(p + vec2(0.0, eps), t) * 0.08;

  vec3 n = normalize(vec3(
    (hC - hR) / eps,
    (hC - hU) / eps,
    1.0
  ));
  return n;
}

// ── Fresnel approximation ──
float fresnel(float cosTheta, float f0) {
  return f0 + (1.0 - f0) * pow(1.0 - cosTheta, 5.0);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  vec2 screenUv = gl_FragCoord.xy / u_res;
  float t = u_time * u_flowSpeed;
  float visc = u_viscosity;

  // ── Compute the height field (domain-warped + metaballs) ──
  float field = warpedField(uv * 2.0, t, visc);
  float meta = metaballs(uv, t);

  // Surface height — combines warped noise and metaball bulges
  float height = field + meta * 0.08;

  // ── Surface normal for lighting ──
  vec3 normal = getNormal(uv * 2.0, t, visc, field);

  // ── View and light setup — mouse controls primary light direction ──
  vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));
  vec3 lightDir1 = normalize(vec3(0.4, 0.5, 0.9));
  vec3 lightDir2 = normalize(vec3(-0.6, -0.3, 0.7));
  vec3 lightDir3 = normalize(vec3(0.0, 0.8, 0.5));
  // Mouse creates a visible bump/dent in the gold surface
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    vec2 toMouse = uv - mUV;
    float md = length(toMouse);
    float bump = exp(-md * md * 25.0);
    // Strong normal perturbation — creates bright specular ring
    normal = normalize(normal + vec3(toMouse * bump * 12.0, 0.0));
    // Also dimple the height to affect the field-based coloring
    height += bump * 0.3;
  }

  // ── Gold material properties ──
  vec3 goldBase = vec3(0.83, 0.61, 0.22);
  vec3 goldBright = vec3(1.0, 0.84, 0.45);
  vec3 goldDeep = vec3(0.55, 0.35, 0.08);
  vec3 goldShadow = vec3(0.18, 0.10, 0.02);
  vec3 whiteHot = vec3(1.0, 0.97, 0.88);

  // Gold F0 (metallic reflectance at normal incidence)
  float f0 = 0.8;

  // ── Diffuse-like term (metallic surfaces color their reflections) ──
  float NdotL1 = max(dot(normal, lightDir1), 0.0);
  float NdotL2 = max(dot(normal, lightDir2), 0.0);
  float NdotL3 = max(dot(normal, lightDir3), 0.0);

  // ── Specular highlights (Blinn-Phong for each light) ──
  vec3 halfVec1 = normalize(lightDir1 + viewDir);
  vec3 halfVec2 = normalize(lightDir2 + viewDir);
  vec3 halfVec3 = normalize(lightDir3 + viewDir);

  float spec1 = pow(max(dot(normal, halfVec1), 0.0), 120.0);
  float spec2 = pow(max(dot(normal, halfVec2), 0.0), 80.0);
  float spec3 = pow(max(dot(normal, halfVec3), 0.0), 200.0);

  // ── Fresnel ──
  float NdotV = max(dot(normal, viewDir), 0.0);
  float fres = fresnel(NdotV, f0);

  // ── Build the color ──

  // Base gold tone varies with the surface field
  float fieldNorm = smoothstep(0.3, 1.8, field);
  vec3 baseColor = mix(goldShadow, goldDeep, smoothstep(0.0, 0.3, fieldNorm));
  baseColor = mix(baseColor, goldBase, smoothstep(0.3, 0.6, fieldNorm));
  baseColor = mix(baseColor, goldBright, smoothstep(0.6, 0.9, fieldNorm));

  // Metallic diffuse: gold-tinted light response
  vec3 diffuse = baseColor * (NdotL1 * 0.5 + NdotL2 * 0.3 + NdotL3 * 0.2);

  // Metallic specular: gold-tinted highlights with white-hot peaks
  vec3 specColor1 = mix(goldBright, whiteHot, spec1);
  vec3 specColor2 = mix(goldBright, whiteHot, spec2 * 0.5);
  vec3 specColor3 = mix(goldBright, whiteHot, spec3);

  vec3 specular = specColor1 * spec1 * 1.2
                + specColor2 * spec2 * 0.6
                + specColor3 * spec3 * 1.5;

  // ── Fake environment reflection ──
  // Gradient-based: reflects a warm gradient from a fake environment
  vec2 reflUv = normal.xy * 0.5 + 0.5;
  vec3 envRefl = mix(
    vec3(0.12, 0.07, 0.02),
    vec3(0.45, 0.30, 0.12),
    reflUv.y
  );
  envRefl = mix(envRefl, vec3(0.7, 0.55, 0.25), smoothstep(0.6, 1.0, reflUv.y));

  // ── Combine lighting ──
  vec3 col = diffuse * 0.4 + specular * fres + envRefl * fres * 0.5;

  // ── Ambient: warm gold fill light ──
  col += baseColor * 0.12;

  // ── Surface tension ripples: bright edges where metaballs meet ──
  float metaGrad = abs(meta - 3.5);
  float tensionLine = smoothstep(0.5, 0.0, metaGrad) * 0.3;
  col += goldBright * tensionLine;

  // ── Subtle ripple highlights from fine noise ──
  float ripple = noise(uv * 15.0 + t * 2.0);
  ripple = ripple * ripple;
  float rippleHighlight = smoothstep(0.6, 0.9, ripple) * 0.08;
  col += whiteHot * rippleHighlight * fres;

  // ── Radial vignette: dark edges where gold thins, bright center ──
  float dist = length(uv);
  float vignette = 1.0 - smoothstep(0.3, 1.2, dist);
  col *= 0.35 + vignette * 0.65;

  // ── Central pooling glow ──
  float poolGlow = smoothstep(0.8, 0.0, dist) * 0.15;
  col += goldBright * poolGlow;

  // ── Tone mapping (ACES-like) ──
  col = col * (2.51 * col + 0.03) / (col * (2.43 * col + 0.59) + 0.14);

  // ── Slight warmth push ──
  col = pow(col, vec3(0.95, 1.0, 1.08));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_auroraSpeed;
uniform float u_auroraIntensity;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define NUM_BG_STARS 120

// ── Hash functions ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453123);
}

// ── Smooth value noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── FBM ──
float fbm(vec2 p, float t, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    val += amp * noise(p * freq + t * 0.1);
    freq *= 2.1;
    amp *= 0.48;
    p += vec2(1.7, 9.2);
  }
  return val;
}

// ── Aurora ribbon function ──
float auroraRibbon(vec2 uv, float t, float ribbonX, float ribbonWidth, float waveFreq, float waveAmp, float phase) {
  // Horizontal position of the ribbon center, slowly drifting
  float centerX = ribbonX + sin(t * 0.15 + phase) * 0.25;

  // The ribbon undulates with wide, dramatic flowing motion
  float wave1 = sin(uv.y * waveFreq + t * 0.9 + phase) * waveAmp;
  float wave2 = sin(uv.y * waveFreq * 2.3 + t * 1.3 + phase * 1.7) * waveAmp * 0.5;
  float wave3 = sin(uv.y * waveFreq * 0.4 + t * 0.35 + phase * 0.6) * waveAmp * 1.2;
  float wave4 = sin(uv.y * waveFreq * 3.7 + t * 1.8 + phase * 2.3) * waveAmp * 0.2;
  float waveOffset = wave1 + wave2 + wave3 + wave4;

  // Distance from ribbon center
  float dx = uv.x - (centerX + waveOffset);

  // Ribbon profile — wide gaussian falloff
  float ribbon = exp(-dx * dx / (ribbonWidth * ribbonWidth));

  // Brightness varies along the ribbon vertically — shimmer and pulse
  float brightBand = 0.5 + 0.5 * sin(uv.y * 2.5 + t * 0.7 + phase * 2.0);
  brightBand *= 0.5 + 0.5 * sin(uv.y * 5.0 - t * 0.9 + phase);

  // Pulsing shimmer effect
  float shimmer = 0.7 + 0.3 * sin(t * 2.5 + phase * 3.0 + uv.y * 8.0);
  shimmer *= 0.8 + 0.2 * sin(t * 1.7 + phase * 1.1 + uv.x * 6.0);

  // Vertical fade: aurora fills the upper half of the sky
  // Strong presence from y=0.0 up to y=0.7, gentle fade at edges
  float verticalFade = smoothstep(-0.35, -0.05, uv.y) * smoothstep(0.75, 0.35, uv.y);

  // Add fine detail using noise
  float detail = noise(vec2(uv.x * 6.0, uv.y * 10.0 + t * 0.5 + phase));
  detail = 0.6 + 0.4 * detail;

  return ribbon * brightBand * verticalFade * detail * shimmer;
}

// ── Background stars ──
float bgStars(vec2 uv, float t) {
  float stars = 0.0;
  for (int i = 0; i < NUM_BG_STARS; i++) {
    float fi = float(i);
    vec2 pos = vec2(
      hash1(fi * 17.31 + 100.0) * 2.8 - 1.4,
      hash1(fi * 11.97 + 200.0) * 1.4 - 0.3
    );
    float d = length(uv - pos);
    // Twinkling with varied speeds
    float twinkleSpeed = 0.5 + hash1(fi * 3.3 + 300.0) * 2.0;
    float twinkle = 0.3 + 0.7 * sin(t * twinkleSpeed + fi * 2.7);
    twinkle = max(twinkle, 0.0);
    twinkle *= twinkle;
    float size = 0.0008 + hash1(fi * 5.5 + 400.0) * 0.002;
    // Brighter stars
    float brightness = 0.4 + hash1(fi * 7.7 + 500.0) * 0.6;
    stars += smoothstep(size, 0.0, d) * twinkle * brightness;
    // Add subtle glow around brighter stars
    if (brightness > 0.7) {
      stars += smoothstep(size * 5.0, 0.0, d) * twinkle * 0.08;
    }
  }
  return stars;
}

// ── Ice crystal pattern (hexagonal frost) ──
float hexDist(vec2 p) {
  p = abs(p);
  return max(p.x + p.y * 0.577350269, p.y * 1.154700538);
}

float crystalPattern(vec2 uv, float t) {
  float scale = 12.0;
  vec2 p = uv * scale;
  vec2 r = vec2(1.0, 1.732);
  vec2 h = r * 0.5;
  vec2 a = mod(p, r) - h;
  vec2 b = mod(p - h, r) - h;
  vec2 gv = (dot(a, a) < dot(b, b)) ? a : b;
  float hd = hexDist(gv);
  float edge = smoothstep(0.45, 0.40, hd) - smoothstep(0.40, 0.35, hd);
  float angle = atan(gv.y, gv.x);
  float branch = abs(sin(angle * 3.0));
  float branchLine = smoothstep(0.04, 0.0, abs(branch - 0.5) * hd);
  branchLine *= smoothstep(0.0, 0.15, hd) * smoothstep(0.45, 0.25, hd);
  float subBranch = abs(sin(angle * 6.0));
  float subLine = smoothstep(0.03, 0.0, abs(subBranch - 0.5) * hd);
  subLine *= smoothstep(0.1, 0.2, hd) * smoothstep(0.4, 0.3, hd);
  float crystal = edge * 0.6 + branchLine * 0.4 + subLine * 0.2;
  float shimmer = 0.7 + 0.3 * sin(t * 0.2 + hash(floor(p / r)) * 6.28);
  crystal *= shimmer;
  return crystal;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  if (u_mouse.x > 0.0) {
    vec2 mNorm = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    uv += (mNorm - uv) * 0.25;
  }
  vec2 screenUV = gl_FragCoord.xy / u_res;
  float t = u_time * u_auroraSpeed;

  // ── Dark sky background ──
  vec3 col = vec3(0.012, 0.010, 0.022);
  // Slight gradient — lighter near horizon
  col += vec3(0.012, 0.010, 0.018) * smoothstep(0.5, -0.3, uv.y);

  // ── Background stars ──
  float starField = bgStars(uv, u_time);
  vec3 starColor = vec3(0.9, 0.88, 0.8);
  col += starColor * starField;

  // ── Aurora ribbons — 7 layers for visual richness ──

  // Ribbon 1: dominant green curtain, wide and bright
  float r1 = auroraRibbon(uv, t, 0.0, 0.22, 2.5, 0.28, 0.0);
  vec3 r1color = mix(
    vec3(0.15, 0.95, 0.35),
    vec3(0.10, 0.75, 0.55),
    0.5 + 0.5 * sin(uv.y * 3.5 + t * 0.3)
  );
  // Purple at the top edges
  r1color = mix(r1color, vec3(0.55, 0.20, 0.80), smoothstep(0.25, 0.65, uv.y) * 0.4);

  // Ribbon 2: secondary green, offset to the right
  float r2 = auroraRibbon(uv, t * 0.9, 0.35, 0.18, 2.8, 0.24, 2.1);
  vec3 r2color = mix(
    vec3(0.20, 0.90, 0.30),
    vec3(0.30, 0.80, 0.25),
    0.5 + 0.5 * sin(uv.y * 4.0 - t * 0.4 + 1.0)
  );
  r2color = mix(r2color, vec3(0.65, 0.25, 0.75), smoothstep(0.3, 0.6, uv.y) * 0.35);

  // Ribbon 3: purple-magenta curtain on the left
  float r3 = auroraRibbon(uv, t * 0.75, -0.30, 0.16, 3.0, 0.22, 4.3);
  vec3 r3color = mix(
    vec3(0.60, 0.15, 0.70),
    vec3(0.80, 0.20, 0.55),
    0.5 + 0.5 * sin(uv.y * 5.0 + t * 0.2 + 2.0)
  );
  r3color = mix(r3color, vec3(0.20, 0.70, 0.40), smoothstep(0.1, -0.1, uv.y) * 0.3);

  // Ribbon 4: wide background green wash
  float r4 = auroraRibbon(uv, t * 0.6, 0.15, 0.30, 1.8, 0.35, 1.0);
  vec3 r4color = mix(
    vec3(0.10, 0.65, 0.25),
    vec3(0.05, 0.50, 0.35),
    0.5 + 0.5 * sin(uv.y * 2.0 + t * 0.15)
  );

  // Ribbon 5: thin bright accent ribbon
  float r5 = auroraRibbon(uv, t * 1.1, -0.10, 0.10, 3.5, 0.18, 5.7);
  vec3 r5color = mix(
    vec3(0.30, 1.0, 0.50),
    vec3(0.50, 0.30, 0.90),
    0.5 + 0.5 * sin(uv.y * 6.0 + t * 0.5 + 3.0)
  );

  // Ribbon 6: far right purple veil
  float r6 = auroraRibbon(uv, t * 0.65, 0.55, 0.14, 2.2, 0.20, 3.5);
  vec3 r6color = mix(
    vec3(0.45, 0.10, 0.65),
    vec3(0.70, 0.15, 0.50),
    0.5 + 0.5 * sin(uv.y * 3.0 - t * 0.3 + 1.5)
  );

  // Ribbon 7: wide subtle green base layer
  float r7 = auroraRibbon(uv, t * 0.5, -0.20, 0.35, 1.5, 0.30, 6.2);
  vec3 r7color = mix(
    vec3(0.08, 0.55, 0.20),
    vec3(0.12, 0.45, 0.30),
    0.5 + 0.5 * sin(uv.y * 2.5 + t * 0.1 + 4.0)
  );

  // Depth-based intensity layering
  float i1 = r1 * 1.4 * u_auroraIntensity;
  float i2 = r2 * 1.1 * u_auroraIntensity;
  float i3 = r3 * 0.9 * u_auroraIntensity;
  float i4 = r4 * 0.5 * u_auroraIntensity;
  float i5 = r5 * 0.8 * u_auroraIntensity;
  float i6 = r6 * 0.6 * u_auroraIntensity;
  float i7 = r7 * 0.35 * u_auroraIntensity;

  // Additive blending of all aurora light
  vec3 auroraLight = r1color * i1 + r2color * i2 + r3color * i3
                   + r4color * i4 + r5color * i5 + r6color * i6 + r7color * i7;

  // Global pulsing intensity — aurora shimmers and breathes
  float pulse = 0.85 + 0.15 * sin(t * 0.8) * sin(t * 0.53 + 1.0);
  auroraLight *= pulse;

  // Add atmospheric glow around the aurora
  float glowY = smoothstep(-0.3, 0.0, uv.y) * smoothstep(0.75, 0.25, uv.y);
  float totalAurora = i1 + i2 + i3 + i4 + i5 + i6 + i7;
  vec3 atmosphericGlow = mix(
    vec3(0.06, 0.15, 0.06),
    vec3(0.10, 0.05, 0.12),
    0.5 + 0.5 * sin(t * 0.15)
  ) * glowY * min(totalAurora, 2.5) * 0.4;

  col += auroraLight + atmosphericGlow;

  // ── Stars dimmed by aurora light ──
  col -= starColor * starField * clamp(totalAurora * 0.5, 0.0, 1.0);

  // ── Ice crystal ground plane (lower portion) ──
  float groundLine = -0.35;
  float groundFade = smoothstep(groundLine + 0.05, groundLine - 0.15, uv.y);

  if (groundFade > 0.001) {
    float perspY = max(0.001, groundLine - uv.y);
    vec2 crystalUV = vec2(uv.x / (perspY * 2.0 + 0.5), 1.0 / (perspY * 3.0));
    crystalUV.x += t * 0.02;
    float crystal = crystalPattern(crystalUV, u_time);
    vec3 iceColor = vec3(0.06, 0.08, 0.12);
    vec3 iceCrystalColor = vec3(0.18, 0.22, 0.32);
    vec3 iceSurface = mix(iceColor, iceCrystalColor, crystal * 0.5);

    // ── Aurora reflection on ice ──
    vec2 reflUV = vec2(uv.x, -uv.y - groundLine * 2.0);
    float rr1 = auroraRibbon(reflUV, t, 0.0, 0.25, 2.5, 0.28, 0.0) * 0.3;
    float rr2 = auroraRibbon(reflUV, t * 0.9, 0.35, 0.20, 2.8, 0.24, 2.1) * 0.2;
    float rr3 = auroraRibbon(reflUV, t * 0.75, -0.30, 0.18, 3.0, 0.22, 4.3) * 0.15;
    vec3 reflectionColor = r1color * rr1 + r2color * rr2 + r3color * rr3;
    reflectionColor *= u_auroraIntensity * pulse;
    float reflStrength = smoothstep(0.25, 0.0, perspY) * 0.6;
    float sparkle = pow(crystal, 3.0) * reflStrength;
    vec3 sparkleColor = vec3(0.9, 0.85, 0.7) * sparkle * 0.3;
    iceSurface += reflectionColor * reflStrength + sparkleColor;
    col = mix(col, iceSurface, groundFade);
  }

  // ── Horizon glow where sky meets ice ──
  float horizonDist = abs(uv.y - groundLine);
  float horizonGlow = exp(-horizonDist * horizonDist / 0.003);
  vec3 horizonColor = mix(
    vec3(0.10, 0.20, 0.08),
    vec3(0.12, 0.08, 0.18),
    0.5 + 0.5 * sin(t * 0.2)
  ) * min(totalAurora, 3.0) * 0.35 + vec3(0.02, 0.03, 0.04);
  col += horizonColor * horizonGlow;

  // ── Vignette ──
  float dist = length(uv * vec2(0.7, 0.9));
  float vignette = 1.0 - smoothstep(0.5, 1.5, dist);
  col *= 0.7 + vignette * 0.3;

  // ── Ensure no negatives ──
  col = max(col, vec3(0.0));

  // ── Subtle tone curve — boost saturation slightly ──
  col = pow(col, vec3(0.92, 0.95, 0.98));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_glowIntensity;
uniform float u_waveSpeed;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash & noise primitives ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── FBM for layered detail ──
float fbm(vec2 p, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    val += amp * noise(p * freq);
    freq *= 2.03;
    amp *= 0.49;
    p += vec2(1.7, 9.2);
  }
  return val;
}

// ── Domain-warped noise for organic flow ──
float warpedNoise(vec2 p, float t) {
  vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0) + t * 0.04, 4),
    fbm(p + vec2(5.2, 1.3) + t * 0.03, 4)
  );
  vec2 r = vec2(
    fbm(p + 3.0 * q + vec2(1.7, 9.2) + t * 0.05, 4),
    fbm(p + 3.0 * q + vec2(8.3, 2.8) + t * 0.04, 4)
  );
  return fbm(p + 2.5 * r, 5);
}

// ── Ocean wave height field ──
// Returns a wave height and derivative-like value for foam/disturbance
vec2 oceanWaves(vec2 p, float t) {
  float h = 0.0;
  float d = 0.0;
  float amp = 1.0;
  float freq = 1.0;

  // Layer multiple wave directions for realistic ocean
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float angle = fi * 0.7 + 0.3;
    vec2 dir = vec2(cos(angle), sin(angle));
    float phase = dot(p * freq, dir) + t * (0.6 + fi * 0.15);
    float wave = sin(phase) * 0.5 + 0.5;
    // Sharp crests via pow
    float sharpWave = pow(wave, 1.5);
    h += sharpWave * amp;
    // Disturbance is highest at wave crests
    d += pow(wave, 3.0) * amp;
    amp *= 0.55;
    freq *= 1.8;
  }
  return vec2(h, d);
}

// ── Breaking wave / foam line detection ──
float waveBreak(vec2 uv, float t) {
  float breaks = 0.0;
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float y_center = 0.1 + fi * 0.22;
    float wave_x = uv.x * (2.0 + fi * 0.8) + t * (0.15 + fi * 0.05);
    float undulation = sin(wave_x) * 0.03 + sin(wave_x * 2.3 + fi) * 0.015;
    float dist_to_wave = abs(uv.y - y_center - undulation);
    float breakLine = smoothstep(0.03, 0.0, dist_to_wave);
    // Modulate along the wave — some sections break, others don't
    float modulation = noise(vec2(uv.x * 3.0 + fi * 10.0, t * 0.2 + fi));
    modulation = smoothstep(0.35, 0.7, modulation);
    breaks += breakLine * modulation * (1.0 - fi * 0.2);
  }
  return breaks;
}

// ── Bioluminescent glow patterns ──
// Organisms glow when disturbed by wave motion
float bioGlow(vec2 uv, float t) {
  float glow = 0.0;

  // Large-scale wave disturbance triggering glow
  vec2 wv = oceanWaves(uv * 3.0, t * 0.8);
  float disturbance = wv.y;

  // Domain-warped organic glow patterns
  float organic1 = warpedNoise(uv * 4.0 + vec2(t * 0.06, t * 0.04), t * 0.5);
  float organic2 = warpedNoise(uv * 6.0 + vec2(-t * 0.05, t * 0.07), t * 0.4);

  // Glow is triggered where waves disturb the water
  glow += organic1 * disturbance * 0.8;
  glow += organic2 * pow(disturbance, 2.0) * 0.5;

  // Swirling tendrils of light — eddies and currents
  vec2 eddy_uv = uv * 5.0 + vec2(t * 0.08, t * 0.05);
  float eddy = fbm(eddy_uv, 6);
  float eddy_curl = abs(eddy - fbm(eddy_uv + vec2(0.01, 0.0), 6)) * 80.0;
  glow += eddy_curl * disturbance * 0.3;

  // Scattered bright plankton clusters
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    vec2 center = vec2(
      hash1(fi * 13.7 + 1.0) * 1.6 - 0.3,
      hash1(fi * 7.3 + 2.0) * 1.2 - 0.1
    );
    // Drift with current
    center.x += sin(t * 0.05 + fi * 2.0) * 0.15;
    center.y += cos(t * 0.04 + fi * 1.5) * 0.08;
    float d = length(uv - center);
    float cluster = exp(-d * d / (0.015 + hash1(fi * 3.1) * 0.02));
    // Pulse and breathe
    float pulse = sin(t * (0.3 + fi * 0.1) + fi * 4.0) * 0.5 + 0.5;
    glow += cluster * pulse * disturbance * 1.5;
  }

  return glow;
}

// ── Individual bright plankton sparks ──
float planktonSparks(vec2 uv, float t, float disturbance) {
  float sparks = 0.0;
  for (int i = 0; i < 25; i++) {
    float fi = float(i);
    vec2 pos = vec2(
      hash1(fi * 17.3 + 100.0),
      hash1(fi * 11.9 + 200.0)
    );
    // Drift in current
    pos.x = fract(pos.x + t * (0.01 + hash1(fi * 5.1 + 300.0) * 0.02));
    pos.y = fract(pos.y + sin(t * 0.3 + fi) * 0.02);

    float d = length(uv - pos);
    float size = 0.001 + hash1(fi * 3.7 + 400.0) * 0.003;
    float spark = smoothstep(size, 0.0, d);

    // Use pre-computed disturbance instead of per-spark wave calc
    float trigger = smoothstep(0.2, 0.6, disturbance);

    // Twinkle
    float twinkle = sin(t * (1.0 + hash1(fi * 2.3) * 3.0) + fi * 7.0);
    twinkle = twinkle * 0.5 + 0.5;

    sparks += spark * trigger * twinkle * 0.8;
  }
  return sparks;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  // Aspect-corrected UV for wave calculations
  float aspect = u_res.x / u_res.y;
  vec2 uvAspect = vec2(uv.x * aspect, uv.y);
  float t = u_time * u_waveSpeed;

  // ── Deep ocean base color ──
  // Dark navy-black gradient — darker at top (deep water), slightly lighter near surface
  vec3 deepColor = vec3(0.017, 0.011, 0.0);
  vec3 midColor = vec3(0.028, 0.018, 0.001);
  vec3 surfaceColor = vec3(0.034, 0.024, 0.0);
  vec3 col = mix(deepColor, surfaceColor, uv.y);

  // ── Subtle underwater caustic light from moonlight ──
  float caustic1 = noise(uvAspect * 8.0 + vec2(t * 0.12, t * 0.08));
  float caustic2 = noise(uvAspect * 12.0 + vec2(-t * 0.1, t * 0.15));
  float causticPattern = caustic1 * caustic2;
  causticPattern = pow(causticPattern, 2.0) * 3.0;
  // Caustics only near the surface
  float surfaceFade = smoothstep(0.3, 0.95, uv.y);
  col += vec3(0.034, 0.021, 0.005) * causticPattern * surfaceFade;

  // ── Ocean wave structure ──
  vec2 waves = oceanWaves(uvAspect * 2.5, t);
  float waveHeight = waves.x;
  float waveDisturbance = waves.y;

  // Subtle wave shading — dark troughs, slightly lit crests
  col += vec3(0.02, 0.012, 0.005) * waveHeight * 0.3;

  // ── BIOLUMINESCENCE ──
  float bio = bioGlow(uvAspect, t) * u_glowIntensity;

  // ── Mouse attraction: brighten glow near cursor ──
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res;
    vec2 mAspect = vec2(mUV.x * aspect, mUV.y);
    float mDist = length(uvAspect - mAspect);
    float attract = exp(-mDist * mDist * 10.0) * 1.2;
    bio += attract * u_glowIntensity;
  }

  // Wave-break bioluminescence — brightest at breaking wave lines
  float breaks = waveBreak(uvAspect, t);
  bio += breaks * 1.2 * u_glowIntensity;

  // Shape the glow — more concentrated, less uniform
  bio = pow(max(bio, 0.0), 1.3);

  // Bioluminescent color: electric blue-cyan with green tints
  vec3 bioColor1 = vec3(0.55, 0.26, 0.0);   // Deep amber (→ cyan-blue via blue filter)
  vec3 bioColor2 = vec3(0.90, 0.36, 0.41);  // Rose-amber (→ teal via blue filter)
  vec3 bioColor3 = vec3(1.0, 0.53, 0.37);   // Bright warm (→ bright cyan via blue filter)

  // Vary color across the scene for natural variation
  float colorVar = noise(uvAspect * 2.0 + t * 0.02);
  vec3 bioCol = mix(bioColor1, bioColor2, colorVar);
  bioCol = mix(bioCol, bioColor3, smoothstep(0.5, 1.0, bio));

  // Add the glow — additive blending
  col += bioCol * bio * 0.7;

  // ── Bright plankton sparks ──
  float sparks = planktonSparks(uv, t, waveDisturbance);
  vec3 sparkColor = vec3(1.0, 0.67, 0.52);
  col += sparkColor * sparks * u_glowIntensity;

  // ── Wave foam with bioluminescent edge ──
  // Where waves break, there's a bright edge of churned-up plankton
  float foam = waveBreak(uvAspect, t);
  float foamDetail = noise(uvAspect * 25.0 + t * 0.3);
  foam *= foamDetail;
  col += vec3(0.70, 0.36, 0.28) * foam * 0.4 * u_glowIntensity;

  // ── Flowing current streaks ──
  // Long horizontal streaks of glow following water flow
  float streak_uv_y = uv.y * 15.0;
  float streakNoise = noise(vec2(uvAspect.x * 3.0 + t * 0.15, streak_uv_y));
  float streak = pow(streakNoise, 5.0) * 2.0;
  streak *= waveDisturbance;
  col += vec3(0.38, 0.18, 0.06) * streak * u_glowIntensity;

  // ── Surface reflection / bright zone near top ──
  float surfaceGlow = smoothstep(0.7, 1.0, uv.y);
  float surfaceWave = noise(vec2(uvAspect.x * 4.0 + t * 0.1, t * 0.2));
  col += vec3(0.028, 0.018, 0.001) * surfaceGlow * surfaceWave;

  // ── Depth fog — darker in the deep ──
  float depthFog = smoothstep(0.6, 0.0, uv.y);
  col = mix(col, deepColor * 0.5, depthFog * 0.4);

  // ── Moonlight from above ──
  // Soft diffuse light concentrated at the top-center
  vec2 moonUV = uv - vec2(0.5, 1.0);
  float moonDist = length(moonUV * vec2(1.0, 1.5));
  float moonLight = exp(-moonDist * moonDist * 3.0);
  col += vec3(0.034, 0.021, 0.005) * moonLight;

  // ── Vignette ──
  vec2 vigUV = uv - 0.5;
  float vig = 1.0 - dot(vigUV, vigUV) * 1.8;
  vig = clamp(vig, 0.0, 1.0);
  col *= 0.5 + vig * 0.5;

  // ── Tone mapping & color grading ──
  col = max(col, vec3(0.0));

  col = pow(max(col, 0.0), vec3(0.95, 1.0, 1.02));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_detail;
uniform float u_glow;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

mat2 rot(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// Gothic pointed arch SDF — two overlapping circles
float archSDF(vec2 p, float w, float h) {
  float sep = w * 0.38;
  float rad = sqrt(sep * sep + h * h);
  float d1 = length(p - vec2(-sep, 0.0)) - rad;
  float d2 = length(p - vec2( sep, 0.0)) - rad;
  float arch = max(d1, d2);
  arch = max(arch, -p.y);
  arch = max(arch, p.y - h * 1.1);
  return arch;
}

// ── Main filigree composition ──
float filigree(vec2 uv, float t) {
  float d = 1e5;
  float lw = 0.002;  // base line width — very thin

  float angle = atan(uv.y, uv.x);
  float r = length(uv);
  vec2 p = abs(uv);  // 4-fold mirror

  // ════════════════════════════════════════════
  // ZONE 1: Central medallion (r < 0.12)
  // ════════════════════════════════════════════
  // Outer ring
  float mR = 0.10;
  d = min(d, abs(r - mR) - lw * 1.3);
  // Inner ring
  d = min(d, abs(r - 0.055) - lw * 0.8);
  // Tiny center dot
  d = min(d, r - 0.012);

  // 8 petals inside medallion
  float seg8 = TAU / 8.0;
  float ra8 = mod(angle + seg8 * 0.5, seg8) - seg8 * 0.5;
  vec2 petal8 = vec2(cos(ra8), sin(ra8)) * r;
  // Small teardrop petal
  float petalD = length((petal8 - vec2(0.075, 0.0)) * vec2(1.0, 2.5)) - 0.025;
  petalD = max(petalD, -(r - 0.055));
  petalD = max(petalD, r - mR);
  d = min(d, abs(petalD) - lw * 0.6);

  // ════════════════════════════════════════════
  // ZONE 2: Inner tracery ring (0.12 — 0.28)
  // ════════════════════════════════════════════
  // Bounding rings
  float r1 = 0.13 + 0.003 * sin(t * 0.5);
  float r2 = 0.28 + 0.004 * sin(t * 0.4 + 1.0);
  d = min(d, abs(r - r1) - lw);
  d = min(d, abs(r - r2) - lw * 1.1);
  // Mid ring with scallops
  float midR = 0.205;
  float scallop = 0.015 * abs(cos(angle * 8.0 + t * 0.08));
  d = min(d, abs(r - midR - scallop) - lw * 0.7);

  // 8 pointed gothic arches radiating outward
  float ra8b = mod(angle + seg8 * 0.5, seg8) - seg8 * 0.5;
  vec2 rp8 = vec2(cos(ra8b), sin(ra8b)) * r;
  // Arch between r1 and r2
  vec2 archP = rp8 - vec2(r1 + 0.01, 0.0);
  archP *= rot(-PI * 0.5);  // rotate so arch points outward
  float archW = 0.06;
  float archH = (r2 - r1) * 0.85;
  float arch = archSDF(archP, archW, archH);
  d = min(d, abs(arch) - lw * 0.9);

  // Nested inner arch (creates the tracery double-arch look)
  vec2 archP2 = rp8 - vec2(r1 + 0.015, 0.0);
  archP2 *= rot(-PI * 0.5);
  float arch2 = archSDF(archP2, archW * 0.55, archH * 0.7);
  d = min(d, abs(arch2) - lw * 0.6);

  // Delicate spokes connecting rings (only in this zone)
  float spoke = abs(ra8b);  // angular distance from spoke center
  float spokeD = spoke * r - lw * 0.6;
  spokeD = max(spokeD, -(r - r1));
  spokeD = max(spokeD, r - r2);
  d = min(d, spokeD);

  // ════════════════════════════════════════════
  // ZONE 3: Scrollwork belt (0.28 — 0.46)
  // ════════════════════════════════════════════
  float r3 = 0.46 + 0.005 * sin(t * 0.35 + 2.0);
  d = min(d, abs(r - r3) - lw);

  // Fleur-de-lis / quatrefoil ornaments at 8 positions
  for (int i = 0; i < 8; i++) {
    float ia = float(i) * seg8;
    float ornR = 0.37;
    vec2 oc = vec2(cos(ia), sin(ia)) * ornR;
    vec2 op = uv - oc;
    op *= rot(-ia);

    // Paired arcs forming a heart/fleur shape (mirror on y)
    vec2 opM = vec2(op.x, abs(op.y));

    // Main lobe — arc curving outward
    float lobe1 = abs(length(opM - vec2(0.015, 0.012)) - 0.022) - lw * 0.6;
    lobe1 = max(lobe1, -opM.x + 0.002);  // clip inner edge
    d = min(d, lobe1);

    // Inner counter-lobe — smaller arc curving inward
    float lobe2 = abs(length(opM - vec2(-0.008, 0.008)) - 0.015) - lw * 0.5;
    lobe2 = max(lobe2, opM.x + 0.005);
    d = min(d, lobe2);

    // Central stem
    float stem = abs(op.y) - lw * 0.5;
    stem = max(stem, op.x - 0.035);
    stem = max(stem, -op.x - 0.025);
    d = min(d, stem);

    // Tip finial — small circle at outer end
    d = min(d, length(op - vec2(0.035, 0.0)) - 0.005);

    // Base connecting to inner ring
    float base = abs(length(op + vec2(0.02, 0.0)) - 0.025) - lw * 0.5;
    base = max(base, abs(op.y) - 0.018);
    base = max(base, op.x + 0.008);
    d = min(d, base);
  }

  // 16 small cusps on inner edge of scrollwork belt
  float seg16 = TAU / 16.0;
  float ra16 = mod(angle + seg16 * 0.5, seg16) - seg16 * 0.5;
  vec2 rp16 = vec2(cos(ra16), sin(ra16)) * r;
  float cusp = length((rp16 - vec2(r2 + 0.01, 0.0)) * vec2(1.0, 3.0)) - 0.012;
  d = min(d, abs(cusp) - lw * 0.5);

  // ════════════════════════════════════════════
  // ZONE 4: Outer tracery (0.46 — 0.68)
  // ════════════════════════════════════════════
  float r4 = 0.68;
  d = min(d, abs(r - r4) - lw * 1.2);

  // Large gothic arches — 4-fold with half-arch subdivisions
  float seg4 = TAU / 4.0;
  float ra4 = mod(angle + seg4 * 0.5, seg4) - seg4 * 0.5;
  vec2 rp4 = vec2(cos(ra4), sin(ra4)) * r;

  vec2 oArchP = rp4 - vec2(r3 + 0.01, 0.0);
  oArchP *= rot(-PI * 0.5);
  float oArch = archSDF(oArchP, 0.16, (r4 - r3) * 0.9);
  d = min(d, abs(oArch) - lw);

  // Sub-arches (two smaller ones inside each big arch)
  vec2 subL = oArchP - vec2(-0.04, 0.0);
  float subArchL = archSDF(subL, 0.06, (r4 - r3) * 0.55);
  d = min(d, abs(subArchL) - lw * 0.7);

  vec2 subR = oArchP - vec2(0.04, 0.0);
  float subArchR = archSDF(subR, 0.06, (r4 - r3) * 0.55);
  d = min(d, abs(subArchR) - lw * 0.7);

  // Trefoil at apex of each big arch
  vec2 tP = oArchP - vec2(0.0, (r4 - r3) * 0.65);
  float trefoil = 1e5;
  for (int j = 0; j < 3; j++) {
    float ta = float(j) * TAU / 3.0 - PI * 0.5;
    vec2 tc = vec2(cos(ta), sin(ta)) * 0.016;
    trefoil = min(trefoil, length(tP - tc) - 0.012);
  }
  trefoil = max(trefoil, -(oArch + lw * 2.0));  // keep inside arch
  d = min(d, abs(trefoil) - lw * 0.5);

  // Diagonal spokes in outer zone (8-fold)
  float ra8c = mod(angle + seg8 * 0.5 + seg8 * 0.5, seg8) - seg8 * 0.5;
  float dSpoke = abs(ra8c) * r - lw * 0.5;
  dSpoke = max(dSpoke, -(r - r3));
  dSpoke = max(dSpoke, r - r4);
  d = min(d, dSpoke);

  // ════════════════════════════════════════════
  // ZONE 5: Corner filigree (using mirror coords)
  // ════════════════════════════════════════════
  // Elegant arcs sweeping from edges
  float cArc1 = abs(length(p - vec2(0.82, 0.0)) - 0.48) - lw * 1.0;
  float cArc2 = abs(length(p - vec2(0.0, 0.82)) - 0.48) - lw * 1.0;
  cArc1 = max(cArc1, -(p.y - 0.25));
  cArc1 = max(cArc1, p.y - 0.72);
  cArc2 = max(cArc2, -(p.x - 0.25));
  cArc2 = max(cArc2, p.x - 0.72);
  d = min(d, cArc1);
  d = min(d, cArc2);

  // Corner spiral flourishes
  vec2 cp = p - vec2(0.58, 0.58);
  float cr = length(cp);
  float ca = atan(cp.y, cp.x);
  float cSpiral = abs(cr - 0.015 * (ca / PI + 1.5)) - lw * 0.8;
  cSpiral = max(cSpiral, cr - 0.10);
  d = min(d, cSpiral);

  // Mirror corner spiral
  vec2 cp2 = vec2(cp.y, cp.x);
  cr = length(cp2);
  ca = atan(cp2.y, cp2.x);
  cSpiral = abs(cr - 0.015 * (ca / PI + 1.5)) - lw * 0.8;
  cSpiral = max(cSpiral, cr - 0.10);
  d = min(d, cSpiral);

  // ════════════════════════════════════════════
  // ACCENTS: Dot ornaments at structural intersections
  // ════════════════════════════════════════════
  for (int k = 0; k < 8; k++) {
    float da = float(k) * seg8;
    // Dots on inner ring
    d = min(d, length(uv - vec2(cos(da), sin(da)) * r1) - 0.005);
    // Dots on mid ring
    d = min(d, length(uv - vec2(cos(da), sin(da)) * r2) - 0.006);
    // Dots on outer ring
    d = min(d, length(uv - vec2(cos(da), sin(da)) * r3) - 0.005);
    // Offset dots
    float offA = da + seg8 * 0.5;
    d = min(d, length(uv - vec2(cos(offA), sin(offA)) * midR) - 0.004);
    d = min(d, length(uv - vec2(cos(offA), sin(offA)) * r4) - 0.005);
  }

  return d;
}

// Reveal from center outward
float reveal(vec2 uv, float t) {
  float r = length(uv);
  float edge = t * 0.25;  // speed of reveal
  float mask = smoothstep(edge, edge - 0.15, r);
  // Fully revealed after a while
  mask = max(mask, smoothstep(4.0, 5.5, t));
  return mask;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  uv = rot(u_mouse.x) * uv;

  float t = u_time;
  float d = filigree(uv, t);
  float rev = reveal(uv, t);

  // ── Anti-aliased line from SDF ──
  float px = 1.2 / min(u_res.x, u_res.y);
  float line = 1.0 - smoothstep(0.0, px * 1.8, d);

  // ── Subtle glow ──
  float gSig = 0.014 * u_glow;
  float glow = exp(-d * d / (gSig * gSig * 2.0)) * 0.32;
  float outerGlow = exp(-d * d / (gSig * gSig * 10.0)) * 0.10;

  // ── Color ──
  vec3 gold = vec3(0.90, 0.72, 0.34);
  vec3 amber = vec3(0.78, 0.55, 0.20);
  vec3 pale = vec3(1.0, 0.94, 0.76);
  vec3 bronze = vec3(0.45, 0.28, 0.10);

  float r = length(uv);
  float ang = atan(uv.y, uv.x);
  float cv = sin(ang * 4.0 + r * 6.0) * 0.5 + 0.5;
  vec3 lineCol = mix(amber, gold, cv);
  lineCol = mix(lineCol, pale, line * 0.25);

  // ── Background ──
  vec3 bg = vec3(0.028, 0.024, 0.022);

  // ── Composite ──
  vec3 col = bg;
  col += bronze * outerGlow * rev;
  col += amber * 0.5 * glow * rev;
  col = mix(col, lineCol, line * rev);

  // Vignette
  float vig = smoothstep(0.0, 0.55, 1.0 - dot(uv * 0.75, uv * 0.75));
  col *= 0.55 + 0.45 * vig;

  // Gentle pulse once fully revealed
  col *= 1.0 + 0.025 * sin(t * 0.35) * smoothstep(7.0, 10.0, t);

  col = clamp(col, 0.0, 1.0);
  col = pow(col, vec3(0.96));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_strikeInterval;
uniform float u_flashIntensity;
uniform vec2 u_mouse;

#define PI 3.14159265359

// ── Hash functions ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453123);
}

// ── Smooth value noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── FBM ──
float fbm(vec2 p, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 7; i++) {
    if (i >= octaves) break;
    val += amp * noise(p * freq);
    freq *= 2.03;
    amp *= 0.5;
    p += vec2(1.7, 9.2);
  }
  return val;
}

// ── Domain-warped storm clouds ──
float stormClouds(vec2 p, float t) {
  vec2 drift = vec2(t * 0.03, t * 0.015);
  vec2 pp = p + drift;
  vec2 q = vec2(
    fbm(pp, 5),
    fbm(pp + vec2(5.2, 1.3), 5)
  );
  vec2 r = vec2(
    fbm(pp + 3.0 * q + vec2(1.7, 9.2) + t * 0.05, 6),
    fbm(pp + 3.0 * q + vec2(8.3, 2.8) + t * 0.03, 6)
  );
  float f = fbm(pp + 2.5 * r, 7);
  return f * 0.5 + length(q) * 0.3 + length(r) * 0.2;
}

// ── Point-to-segment distance ──
float segDist(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// ── Lightning bolt: fractal jagged path with branches ──
float lightningBolt(vec2 uv, float seed, float startX, float endX) {
  float minD = 100.0;

  // Main bolt from top to bottom of screen
  float prevX = startX;
  float prevY = -0.6;

  for (int i = 1; i <= 14; i++) {
    float fi = float(i);
    float frac = fi / 14.0;

    // Jagged lateral displacement
    float jit = hash1(seed * 13.37 + fi * 7.91) * 2.0 - 1.0;
    float jit2 = hash1(seed * 29.13 + fi * 3.17) * 2.0 - 1.0;
    float disp = jit * 0.15 * (1.0 - frac * 0.4) + jit2 * 0.05;

    float targetX = mix(startX, endX, frac);
    float curX = targetX + disp;
    float curY = mix(-0.6, 0.55, frac);

    float d = segDist(uv, vec2(prevX, prevY), vec2(curX, curY));
    minD = min(minD, d);

    // Branches
    float roll = hash1(seed * 5.71 + fi * 11.3);
    if (roll > 0.45 && i > 1 && i < 13) {
      float side = (hash1(seed * 3.3 + fi * 9.1) > 0.5) ? 1.0 : -1.0;
      float bLen = 0.08 + hash1(seed * 7.7 + fi * 2.3) * 0.12;
      float bAng = 0.5 + hash1(seed * 2.2 + fi * 5.5) * 0.6;

      float bpx = curX;
      float bpy = curY;
      for (int j = 1; j <= 5; j++) {
        float fj = float(j);
        float bj = hash1(seed * 17.1 + fi * 3.7 + fj * 11.9) * 2.0 - 1.0;
        float bnx = bpx + side * bLen * 0.2 + bj * 0.025;
        float bny = bpy + bLen * 0.2 * bAng;
        float bd = segDist(uv, vec2(bpx, bpy), vec2(bnx, bny));
        minD = min(minD, bd * 1.5);
        bpx = bnx;
        bpy = bny;
      }

      // Sub-branch fork
      if (hash1(seed * 9.9 + fi * 4.1) > 0.55) {
        float sbx = curX + side * bLen * 0.12;
        float sby = curY + bLen * 0.12 * bAng;
        for (int k = 1; k <= 3; k++) {
          float fk = float(k);
          float sbj = hash1(seed * 23.7 + fi * 7.3 + fk * 5.1) * 2.0 - 1.0;
          float sbnx = sbx - side * 0.025 + sbj * 0.015;
          float sbny = sby + 0.035;
          float sbd = segDist(uv, vec2(sbx, sby), vec2(sbnx, sbny));
          minD = min(minD, sbd * 2.2);
          sbx = sbnx;
          sby = sbny;
        }
      }
    }

    prevX = curX;
    prevY = curY;
  }

  return minD;
}

// ── Get bolt parameters for a given index ──
void boltParams(int idx, float interval, out float birth, out float seed, out float sx, out float ex) {
  float fi = float(idx);
  birth = fi * interval + hash1(fi * 17.31 + 42.0) * interval * 0.5;
  seed = fi * 7.13 + 1.0;
  sx = (hash1(fi * 13.37 + 100.0) - 0.5) * 0.8;
  ex = sx + (hash1(fi * 9.91 + 200.0) - 0.5) * 0.35;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  vec2 screenUV = gl_FragCoord.xy / u_res;
  float t = u_time;

  // Mouse as lightning strike target
  vec2 mouseTarget = vec2(0.0);
  float mouseActive = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res;
    mouseTarget = (mUV - 0.5) * vec2(u_res.x / u_res.y, 1.0);
    mouseActive = 1.0;
  }

  // ── Storm sky ──
  vec3 skyTop = vec3(0.015, 0.008, 0.05);
  vec3 skyMid = vec3(0.025, 0.018, 0.07);
  vec3 skyBot = vec3(0.01, 0.012, 0.035);
  vec3 sky = mix(skyTop, skyMid, smoothstep(0.0, 0.5, screenUV.y));
  sky = mix(sky, skyBot, smoothstep(0.5, 1.0, screenUV.y));

  // ── Storm clouds ──
  float cloud1 = stormClouds(uv * 1.8, t);
  float cloud2 = stormClouds(uv * 2.4 + vec2(3.7, 1.2), t * 1.1);
  float cloudDensity = smoothstep(0.3, 0.75, cloud1) * 0.6 + smoothstep(0.35, 0.8, cloud2) * 0.4;

  // Denser clouds in upper portion
  float heightBias = smoothstep(0.85, 0.0, screenUV.y);
  cloudDensity *= 0.4 + heightBias * 0.6;

  vec3 cloudDark = vec3(0.025, 0.02, 0.055);
  vec3 cloudMid = vec3(0.055, 0.045, 0.09);
  vec3 cloudLight = vec3(0.09, 0.07, 0.13);
  vec3 cloudColor = mix(cloudDark, cloudMid, smoothstep(0.1, 0.4, cloudDensity));
  cloudColor = mix(cloudColor, cloudLight, smoothstep(0.4, 0.8, cloudDensity));

  vec3 col = mix(sky, cloudColor, cloudDensity * 0.85);

  // ── Lightning system ──
  float interval = u_strikeInterval;
  float totalFlash = 0.0;
  vec3 boltLight = vec3(0.0);

  // Cycle through bolt slots
  float period = interval * 60.0;
  float ct = mod(t, period);
  int cycle = int(floor(ct / interval));

  for (int i = -2; i <= 5; i++) {
    int bi = cycle + i;
    if (bi < 0) continue;

    float birth, seed, sx, ex;
    boltParams(bi, interval, birth, seed, sx, ex);

    if (mouseActive > 0.5) {
      ex = mix(ex, mouseTarget.x, 0.6);
      sx = mix(sx, mouseTarget.x, 0.3);
    }
    float age = ct - birth;
    if (age < -0.01 || age > 1.5) continue;
    if (age < 0.0) age = 0.0;

    // Flash lifecycle
    float flash = 0.0;
    if (age < 0.06) {
      flash = 1.0;
    } else if (age < 0.12) {
      flash = 0.4 + 0.6 * smoothstep(0.12, 0.06, age);
    } else if (age < 0.22) {
      // Restrike
      float rs = smoothstep(0.12, 0.16, age) * smoothstep(0.22, 0.16, age);
      flash = 0.15 + rs * 0.7;
    } else if (age < 0.7) {
      flash = 0.15 * smoothstep(0.7, 0.22, age);
    }

    float boltVis = smoothstep(0.45, 0.0, age);

    if (boltVis > 0.001) {
      float d = lightningBolt(uv, seed, sx, ex);

      // Outer atmospheric bloom
      float outer = exp(-d * d / 0.012) * boltVis * flash;
      boltLight += vec3(0.25, 0.25, 0.7) * outer * 0.6;

      // Mid glow
      float mid = exp(-d * d / 0.003) * boltVis * flash;
      boltLight += vec3(0.5, 0.6, 1.0) * mid;

      // Hot white core
      float core = exp(-d * d / 0.0004) * boltVis;
      float coreI = flash;
      if (age > 0.06 && age < 0.4) {
        float flk = 0.5 + 0.5 * sin(age * 130.0 + seed * 10.0);
        flk *= 0.5 + 0.5 * sin(age * 73.0 + seed * 7.0);
        coreI *= 0.4 + flk * 0.6;
      }
      boltLight += vec3(1.0, 0.97, 0.92) * core * coreI * 3.0;

      // Super bright center
      float inner = exp(-d * d / 0.00006) * boltVis * flash;
      boltLight += vec3(1.0) * inner * 4.0;
    }

    // Cloud illumination
    if (flash > 0.01) {
      vec2 bc = vec2(sx, -0.1);
      float dc = length(uv - bc);

      // Wide area illumination
      float illum = exp(-dc * dc / 0.45) * flash;
      illum *= 0.25 + cloudDensity * 0.75;
      vec3 illumCol = mix(vec3(0.12, 0.1, 0.22), vec3(0.35, 0.3, 0.55), cloudDensity);
      col += illumCol * illum * 2.2;

      // Close white illumination
      float close = exp(-dc * dc / 0.08) * flash;
      col += vec3(0.25, 0.22, 0.32) * close * cloudDensity * 1.5;

      // Ground illumination (bottom of screen)
      float groundDist = length(uv - vec2(ex, 0.55));
      float groundGlow = exp(-groundDist * groundDist / 0.1) * flash;
      col += vec3(0.15, 0.13, 0.22) * groundGlow * 0.8;

      totalFlash += flash * 0.5;
    }

    // Chromatic aberration shake on fresh strikes
    if (age < 0.1) {
      float shake = smoothstep(0.1, 0.0, age) * 0.35;
      float sn = hash1(seed + floor(age * 60.0)) * 2.0 - 1.0;
      col.r += sn * shake * 0.06;
      col.b -= sn * shake * 0.04;
    }
  }

  col += boltLight;

  // Global screen flash
  totalFlash = min(totalFlash, 1.0);
  col += vec3(0.1, 0.08, 0.16) * totalFlash * u_flashIntensity;

  // ── Sheet lightning (distant cloud flashes) ──
  float st = t * 0.8;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float ss = fi * 31.7 + 100.0;
    float sc = hash1(ss + floor(st + fi * 0.37));
    float sa = fract(st + fi * 0.37);

    if (sc > 0.65) {
      float sf = smoothstep(0.04, 0.0, sa) + smoothstep(0.12, 0.04, sa) * 0.35;
      vec2 sp = vec2(
        (hash1(ss + 1.0) - 0.5) * 1.4,
        (hash1(ss + 2.0) - 0.5) * 0.5 - 0.15
      );
      float sd = length(uv - sp);
      float sg = exp(-sd * sd / 0.2) * sf;
      col += vec3(0.07, 0.05, 0.14) * sg * (0.5 + cloudDensity * 1.5);
    }
  }

  // ── Rain ──
  vec2 rainUV = gl_FragCoord.xy / min(u_res.x, u_res.y);
  vec2 rc = vec2(rainUV.x + rainUV.y * 0.12, rainUV.y);
  rc.y += t * 3.0;
  rc.x += t * 0.35;

  float rain = 0.0;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float scale = 35.0 + fi * 20.0;
    vec2 rv = rc * scale + vec2(fi * 7.3, fi * 11.1);
    float ry = fract(rv.y);
    float rx = floor(rv.x);
    float rs = hash1(rx * 13.7 + fi * 31.0);
    if (rs > 0.65) {
      float streak = smoothstep(0.0, 0.008, ry) * smoothstep(0.12 + rs * 0.08, 0.008, ry);
      rain += streak * (0.018 + fi * 0.006);
    }
  }
  col += vec3(0.35, 0.38, 0.5) * rain * (0.25 + totalFlash * 2.5);

  // ── Vignette ──
  float vd = length(uv);
  float vig = 1.0 - smoothstep(0.35, 1.3, vd);
  col *= 0.5 + vig * 0.5;

  // ── Tone mapping ──
  col = col / (1.0 + col);
  col.r = pow(col.r, 1.05);
  col.b = pow(col.b, 0.93);
  col = max(col, vec3(0.0));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_rotSpeed;
uniform float u_grooveDensity;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash ──
float hash(float n) {
  return fract(sin(n) * 43758.5453123);
}

float hash2(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// ── Smooth value noise ──
float vnoise(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

float vnoise2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash2(i);
  float b = hash2(i + vec2(1.0, 0.0));
  float c = hash2(i + vec2(0.0, 1.0));
  float d = hash2(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── HSV to RGB ──
vec3 hsv2rgb(float h, float s, float v) {
  vec3 c = vec3(h, s, v);
  vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  return c.z * mix(vec3(1.0), rgb, c.y);
}

// ── Groove micro-structure ──
// Simulates the V-shaped groove cross-section of a vinyl record.
// Returns a groove profile value: 1.0 at groove walls, 0.0 at groove floor.
float grooveProfile(float r, float density) {
  // Primary fine grooves — ~300 lines per inch on a real record
  float grooveFreq = 280.0 * density;
  float groove = r * grooveFreq;
  float grooveFract = fract(groove);

  // V-shaped groove profile: sharp valley, reflective walls
  float profile = abs(grooveFract - 0.5) * 2.0;
  // Sharpen the groove walls
  profile = pow(profile, 0.7);

  return profile;
}

// ── Groove waveform modulation ──
// Simulates the audio waveform cut into the groove walls.
// This creates the characteristic wobble visible under magnification.
float grooveWaveform(float angle, float r) {
  float wave = 0.0;
  // Low frequency (bass)
  wave += sin(angle * 3.0 + r * 47.0) * 0.4;
  // Mid frequency
  wave += sin(angle * 7.0 + r * 91.0 + 1.3) * 0.3;
  // High frequency (treble)
  wave += sin(angle * 17.0 + r * 157.0 + 2.7) * 0.2;
  // Ultra-fine detail
  wave += sin(angle * 31.0 + r * 233.0 + 4.1) * 0.1;
  return wave;
}

// ── Diffraction grating color ──
// Vinyl grooves act as a diffraction grating, splitting white light
// into spectral colors. The color depends on the angle between
// the groove tangent, incident light, and viewing direction.
vec3 diffractionColor(float gratingAngle, float intensity) {
  // Map the grating angle to a hue — simulates spectral dispersion
  // Different diffraction orders create different color bands
  float hue1 = fract(gratingAngle * 0.5 + 0.0);
  float hue2 = fract(gratingAngle * 0.5 + 0.33);
  float hue3 = fract(gratingAngle * 0.5 + 0.67);

  // First-order diffraction (strongest)
  vec3 color1 = hsv2rgb(hue1, 0.7, 1.0) * 0.6;
  // Second-order (fainter, offset)
  vec3 color2 = hsv2rgb(hue2, 0.5, 0.8) * 0.25;
  // Third-order (very faint)
  vec3 color3 = hsv2rgb(hue3, 0.4, 0.6) * 0.15;

  return (color1 + color2 + color3) * intensity;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  float t = u_time * u_rotSpeed;

  // ── Record geometry ──
  float dist = length(uv);
  float angle = atan(uv.y, uv.x) + u_mouse.x;

  // Record boundaries
  float recordRadius = 0.44;
  float labelRadius = recordRadius * 0.27;
  float grooveInner = labelRadius + 0.01;
  float grooveOuter = recordRadius - 0.015;

  // ── Background — deep dark ──
  vec3 col = vec3(0.012, 0.010, 0.010);

  // Subtle warm ambient glow beneath the record
  float ambientGlow = exp(-dist * dist * 1.8) * 0.03;
  col += vec3(0.08, 0.05, 0.03) * ambientGlow;

  // ── Record disc ──
  if (dist < recordRadius) {
    // Record rotation — the grooves spin under the light
    float rpm = 33.333;
    float rotationAngle = t * rpm / 60.0 * TAU;
    float rotatedAngle = angle + rotationAngle;

    // Normalized radial position within groove area
    float rNorm = (dist - grooveInner) / (grooveOuter - grooveInner);
    rNorm = clamp(rNorm, 0.0, 1.0);

    // ── Vinyl base color — very dark with subtle warmth ──
    vec3 vinylBase = vec3(0.02, 0.018, 0.016);
    // Slight radial variation
    vinylBase += vec3(0.005) * vnoise2(vec2(dist * 20.0, angle * 3.0));

    col = vinylBase;

    // ── Groove structure ──
    if (dist > grooveInner && dist < grooveOuter) {
      // Groove profile — the V-shaped cross section
      float profile = grooveProfile(dist, u_grooveDensity);

      // Audio waveform modulation — makes grooves visibly wobble
      float waveform = grooveWaveform(rotatedAngle, dist) * 0.0004;
      float modulatedDist = dist + waveform;
      float modulatedProfile = grooveProfile(modulatedDist, u_grooveDensity);

      // Groove visibility — subtle dark/light alternation
      float grooveShading = mix(0.015, 0.03, modulatedProfile);
      col = vec3(grooveShading, grooveShading * 0.95, grooveShading * 0.9);

      // ── Light sources for reflections ──
      // Primary warm spotlight — upper right, slowly drifting
      vec2 light1Pos = vec2(0.6, 0.5);
      // Secondary cool fill light — lower left
      vec2 light2Pos = vec2(-0.5, -0.4);

      // ── Specular reflection off groove walls ──
      // The groove walls are angled, creating directional reflections.
      // As the record rotates, different parts of each groove
      // catch the light at different angles.

      // Direction from this point to light
      vec2 toLight1 = normalize(light1Pos - uv);
      vec2 toLight2 = normalize(light2Pos - uv);

      // Groove tangent direction (perpendicular to radial)
      vec2 radialDir = normalize(uv);
      vec2 tangentDir = vec2(-radialDir.y, radialDir.x);

      // Angle between light direction and groove tangent
      // This determines which spectral color is reflected
      float lightGrooveAngle1 = dot(toLight1, tangentDir);
      float lightGrooveAngle2 = dot(toLight2, tangentDir);

      // Distance-based light falloff from each source
      float lightDist1 = length(light1Pos - uv);
      float lightDist2 = length(light2Pos - uv);
      float lightFalloff1 = 1.0 / (1.0 + lightDist1 * lightDist1 * 2.0);
      float lightFalloff2 = 1.0 / (1.0 + lightDist2 * lightDist2 * 3.0);

      // ── Prismatic diffraction from grooves ──
      // The fine groove spacing acts as a diffraction grating.
      // The reflected color depends on the angle.

      // Primary light diffraction
      float gratingPhase1 = lightGrooveAngle1 + rotatedAngle * 0.05;
      vec3 diffraction1 = diffractionColor(gratingPhase1, lightFalloff1);

      // Secondary light diffraction
      float gratingPhase2 = lightGrooveAngle2 + rotatedAngle * 0.05 + 0.5;
      vec3 diffraction2 = diffractionColor(gratingPhase2, lightFalloff2);

      // Groove walls reflect more when the profile is at the wall angle
      float wallReflectivity = smoothstep(0.3, 0.8, modulatedProfile);

      // ── Specular highlight bands ──
      // On a real record, you see bright arcs where the groove angle
      // perfectly reflects light to the viewer.

      // Primary specular arc
      float specAngle1 = acos(clamp(lightGrooveAngle1, -1.0, 1.0));
      float specBand1 = exp(-pow(specAngle1 - PI * 0.25, 2.0) * 8.0);
      specBand1 += exp(-pow(specAngle1 - PI * 0.75, 2.0) * 8.0) * 0.5;

      // Secondary specular arc
      float specAngle2 = acos(clamp(lightGrooveAngle2, -1.0, 1.0));
      float specBand2 = exp(-pow(specAngle2 - PI * 0.3, 2.0) * 6.0) * 0.6;

      // ── Combine reflections ──
      // Warm ambient reflected light off the vinyl surface
      vec3 ambientReflection = vec3(0.04, 0.03, 0.025) * lightFalloff1;

      // Prismatic groove reflections
      vec3 grooveReflection = vec3(0.0);
      grooveReflection += diffraction1 * specBand1 * wallReflectivity * 1.2;
      grooveReflection += diffraction2 * specBand2 * wallReflectivity * 0.8;

      // Warm specular highlight — the bright band of reflected light
      vec3 warmSpec = vec3(0.95, 0.75, 0.5);
      float specIntensity1 = specBand1 * lightFalloff1 * wallReflectivity;
      float specIntensity2 = specBand2 * lightFalloff2 * wallReflectivity;
      vec3 specularHighlight = warmSpec * (specIntensity1 * 0.15 + specIntensity2 * 0.08);

      // ── Broad light sheen ──
      // The overall warm glow where the spotlight falls on the record
      float sheen = exp(-lightDist1 * lightDist1 * 3.0) * 0.08;
      sheen += exp(-lightDist2 * lightDist2 * 4.0) * 0.03;
      vec3 sheenColor = vec3(0.2, 0.15, 0.1) * sheen;

      // ── Micro-groove detail shimmer ──
      // Very fine flickering as individual grooves catch light
      float microGroove = fract(dist * 280.0 * u_grooveDensity);
      float microFlicker = pow(abs(sin(microGroove * PI)), 12.0);
      float microAngle = sin(rotatedAngle * 3.0 + dist * 200.0);
      float microSpec = microFlicker * max(microAngle, 0.0) * lightFalloff1 * 0.1;

      // ── Additional rainbow bands ──
      // Multiple diffraction orders create concentric rainbow arcs
      float bandPhase = rotatedAngle + dist * 60.0;
      float rainbowBand = sin(bandPhase * 2.0) * 0.5 + 0.5;
      rainbowBand = pow(rainbowBand, 3.0);
      float rainbowHue = fract(dist * 8.0 + angle * 0.3 + t * 0.02);
      vec3 rainbowColor = hsv2rgb(rainbowHue, 0.6, 0.4) * rainbowBand;
      rainbowColor *= specBand1 * lightFalloff1 * 0.3;

      // ── Assemble final groove color ──
      col += ambientReflection;
      col += grooveReflection;
      col += specularHighlight;
      col += sheenColor;
      col += vec3(microSpec) * vec3(1.0, 0.9, 0.8);
      col += rainbowColor;

      // ── Lead-in and run-out grooves ──
      // Wider spacing at the edges
      float edgeFade = smoothstep(0.0, 0.03, rNorm) * smoothstep(1.0, 0.97, rNorm);
      col *= edgeFade * 0.9 + 0.1;
    }

    // ── Center label ──
    if (dist < labelRadius) {
      // Warm amber/gold label — Tyler-inspired earthy tones
      float labelR = dist / labelRadius;
      vec3 labelColor = mix(
        vec3(0.45, 0.30, 0.12),
        vec3(0.30, 0.18, 0.08),
        labelR
      );

      // Subtle paper texture on the label
      float paperTex = vnoise2(vec2(
        cos(rotatedAngle) * dist * 50.0,
        sin(rotatedAngle) * dist * 50.0
      ));
      labelColor += vec3(0.03, 0.02, 0.01) * paperTex;

      // Label ring decoration
      float ring1 = smoothstep(0.72, 0.74, labelR) - smoothstep(0.76, 0.78, labelR);
      labelColor += vec3(0.1, 0.07, 0.03) * ring1;

      // Spindle hole
      float spindleHole = smoothstep(0.08, 0.06, labelR);
      labelColor = mix(labelColor, vec3(0.01), spindleHole);

      // Light reflection on label
      vec2 light1Pos = vec2(0.6, 0.5);
      float labelLight = exp(-length(light1Pos - uv) * length(light1Pos - uv) * 4.0);
      labelColor += vec3(0.15, 0.1, 0.05) * labelLight;

      col = labelColor;
    }

    // ── Record edge ──
    float edgeDist = recordRadius - dist;
    float edgeHighlight = smoothstep(0.008, 0.0, edgeDist) * 0.3;
    col += vec3(0.15, 0.12, 0.08) * edgeHighlight;

    // Edge shadow/bevel
    float edgeShadow = smoothstep(0.02, 0.0, edgeDist);
    col *= 1.0 - edgeShadow * 0.3;

    // Anti-alias the record edge
    float edgeAA = smoothstep(recordRadius, recordRadius - 0.002, dist);
    col *= edgeAA;
  }

  // ── Drop shadow beneath record ──
  if (dist >= recordRadius) {
    float shadowDist = dist - recordRadius;
    float shadow = exp(-shadowDist * shadowDist * 80.0) * 0.25;
    col = mix(col, vec3(0.0), shadow);
  }

  // ── Vignette ──
  float vig = 1.0 - dot(uv * 0.8, uv * 0.8);
  vig = smoothstep(0.0, 1.0, vig);
  col *= 0.7 + vig * 0.3;

  // ── Tone mapping ──
  col = col / (1.0 + col * 0.2);

  // ── Final warmth ──
  col = pow(max(col, 0.0), vec3(0.95, 0.98, 1.05));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_burnSpeed;
uniform float u_photoCount;
uniform vec2 u_mouse;

// --- Hash / noise utilities ---
float hash(float n){ return fract(sin(n)*43758.5453123); }
float hash2(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)))*43758.5453123); }

vec2 hash2v(vec2 p){
  return vec2(hash2(p), hash2(p + vec2(37.0, 91.0)));
}

// Simplex-like 2D noise
vec3 mod289(vec3 x){return x-floor(x*(1.0/289.0))*289.0;}
vec2 mod289v2(vec2 x){return x-floor(x*(1.0/289.0))*289.0;}
vec3 permute(vec3 x){return mod289(((x*34.0)+1.0)*x);}

float snoise(vec2 v){
  const vec4 C=vec4(0.211324865405187,0.366025403784439,-0.577350269189626,0.024390243902439);
  vec2 i=floor(v+dot(v,C.yy));
  vec2 x0=v-i+dot(i,C.xx);
  vec2 i1=(x0.x>x0.y)?vec2(1.0,0.0):vec2(0.0,1.0);
  vec4 x12=x0.xyxy+C.xxzz; x12.xy-=i1;
  i=mod289v2(i);
  vec3 p=permute(permute(i.y+vec3(0.0,i1.y,1.0))+i.x+vec3(0.0,i1.x,1.0));
  vec3 m=max(0.5-vec3(dot(x0,x0),dot(x12.xy,x12.xy),dot(x12.zw,x12.zw)),0.0);
  m=m*m; m=m*m;
  vec3 x=2.0*fract(p*C.www)-1.0;
  vec3 h=abs(x)-0.5;
  vec3 ox=floor(x+0.5);
  vec3 a0=x-ox;
  m*=1.79284291400159-0.85373472095314*(a0*a0+h*h);
  vec3 g;
  g.x=a0.x*x0.x+h.x*x0.y;
  g.yz=a0.yz*x12.xz+h.yz*x12.yw;
  return 130.0*dot(m,g);
}

float fbm(vec2 p){
  float f=0.0;
  f+=0.5000*snoise(p); p*=2.02;
  f+=0.2500*snoise(p); p*=2.03;
  f+=0.1250*snoise(p); p*=2.01;
  f+=0.0625*snoise(p);
  return f;
}

// Rotation matrix
mat2 rot(float a){ float c=cos(a), s=sin(a); return mat2(c,-s,s,c); }

// Rounded rectangle SDF
float roundedRectSDF(vec2 p, vec2 halfSize, float radius){
  vec2 d=abs(p)-halfSize+radius;
  return length(max(d, 0.0))+min(max(d.x,d.y), 0.0)-radius;
}

// Get deterministic polaroid properties from index
vec2 getPhotoPos(float idx){
  float hx = hash(idx * 73.156);
  float hy = hash(idx * 127.843);
  return vec2(hx * 1.2 - 0.6, hy * 0.8 - 0.4);
}

float getPhotoAngle(float idx){
  return (hash(idx * 231.71) - 0.5) * 0.6;
}

float getPhotoPhase(float idx){
  return hash(idx * 347.29) * 6.2831853;
}

// Warm nostalgic gradient for "photo" content
vec3 photoGradient(vec2 localUV, float idx){
  float n1 = fbm(localUV * 2.0 + vec2(hash(idx*13.0)*10.0, hash(idx*29.0)*10.0));
  float n2 = fbm(localUV * 1.5 + vec2(hash(idx*53.0)*10.0, hash(idx*67.0)*10.0));

  // Olivia Rodrigo nostalgia palette: faded pinks, amber, soft purple
  vec3 c1 = vec3(0.85, 0.45, 0.55);  // faded pink
  vec3 c2 = vec3(0.82, 0.58, 0.32);  // amber
  vec3 c3 = vec3(0.55, 0.38, 0.65);  // soft purple
  vec3 c4 = vec3(0.90, 0.72, 0.55);  // warm peach
  vec3 c5 = vec3(0.65, 0.30, 0.45);  // dusty rose

  float blend = n1 * 0.5 + 0.5;
  float blend2 = n2 * 0.5 + 0.5;
  float idxMod = hash(idx * 91.0);

  vec3 colA = mix(c1, c2, blend);
  vec3 colB = mix(c3, c4, blend2);
  vec3 col = mix(colA, colB, idxMod);
  col = mix(col, c5, smoothstep(0.4, 0.9, localUV.y) * 0.3);

  // Add gentle vignette inside the photo
  float photoVig = 1.0 - length(localUV) * 0.6;
  col *= 0.7 + 0.3 * clamp(photoVig, 0.0, 1.0);

  return col;
}

// Compute a single polaroid contribution
// Returns vec4(rgb, alpha)
vec4 polaroid(vec2 p, float idx, float time, float px){
  vec2 center = getPhotoPos(idx);
  float angle = getPhotoAngle(idx);
  float phase = getPhotoPhase(idx);

  // Cycle duration and phase
  float cycleDur = 6.2831853;
  float t = mod(time * u_burnSpeed + phase, cycleDur);
  float tNorm = t / cycleDur; // 0..1 cycle

  // Lifecycle phases:
  // 0.0 - 0.15: fade in from black (develop)
  // 0.15 - 0.45: full color (peak exposure)
  // 0.45 - 0.75: overexpose to white + burn edges
  // 0.75 - 0.95: burn out with embers
  // 0.95 - 1.0: fade to nothing

  // Overall visibility envelope
  float appear = smoothstep(0.0, 0.05, tNorm);
  float disappear = 1.0 - smoothstep(0.90, 1.0, tNorm);
  float visibility = appear * disappear;

  if(visibility < 0.001) return vec4(0.0);

  // Transform coordinate into polaroid space
  vec2 lp = p - center;
  lp = rot(angle) * lp;

  // Polaroid dimensions (photo + border)
  vec2 outerSize = vec2(0.16, 0.20);  // outer polaroid frame
  vec2 innerSize = vec2(0.13, 0.13);  // inner photo area (square)
  vec2 innerOffset = vec2(0.0, -0.02); // photo shifted up (bigger bottom border)
  float cornerR = 0.006;
  float aa = px * 2.0;  // pixel-relative anti-aliasing width

  // Outer frame SDF
  float outerD = roundedRectSDF(lp, outerSize, cornerR);
  float outerMask = smoothstep(aa, 0.0, outerD);

  if(outerMask < 0.001) return vec4(0.0);

  // Inner photo SDF
  float innerD = roundedRectSDF(lp - innerOffset, innerSize, 0.003);
  float innerMask = smoothstep(aa, 0.0, innerD);

  // Photo UV for gradient
  vec2 photoUV = (lp - innerOffset) / innerSize;

  // --- Develop phase ---
  float developAmount = smoothstep(0.0, 0.20, tNorm);

  // --- Overexposure phase ---
  float overexpose = smoothstep(0.40, 0.70, tNorm);

  // --- Burn phase ---
  float burnPhase = smoothstep(0.50, 0.85, tNorm);

  // Noise-driven burn edge propagation
  float burnNoise = fbm(lp * 12.0 + vec2(hash(idx*17.0)*5.0, hash(idx*31.0)*5.0));
  burnNoise += snoise(lp * 20.0 + time * 0.3) * 0.3;
  float burnEdgeDist = -outerD * 8.0; // distance from edge, normalized
  float burnMask = smoothstep(0.0, 1.0, burnPhase * 3.0 - burnEdgeDist - burnNoise * 0.5);

  // --- Compose the polaroid ---

  // Paper white with slight warm tint
  vec3 paperColor = vec3(0.95, 0.93, 0.90);

  // Photo content
  vec3 photoColor = photoGradient(photoUV, idx);

  // Develop: fade from dark to color
  photoColor = mix(vec3(0.02, 0.01, 0.02), photoColor, developAmount);

  // Overexpose: push toward blown-out white
  photoColor = mix(photoColor, vec3(1.0, 0.98, 0.95), overexpose * 0.85);

  // Paper also overexposes
  paperColor = mix(paperColor, vec3(1.0), overexpose * 0.3);

  // Combine paper border and photo area
  vec3 polaroidColor = mix(paperColor, photoColor, innerMask);

  // Apply burn: charred black edges with glowing amber embers
  float emberGlow = burnMask * (1.0 - smoothstep(0.0, 0.5, burnMask));
  vec3 emberColor = vec3(1.0, 0.5, 0.1) * 2.0; // bright amber-orange glow
  vec3 charColor = vec3(0.03, 0.02, 0.01);

  // Burning edge: char -> ember glow -> transparent
  polaroidColor = mix(polaroidColor, charColor, smoothstep(0.0, 0.5, burnMask));
  polaroidColor += emberColor * emberGlow * 1.5;

  // Subtle paper shadow / depth
  float shadow = smoothstep(0.0, 0.02, -outerD) * 0.15;

  // Alpha: frame mask, visibility, and burn-through
  float burnHole = smoothstep(0.6, 1.0, burnMask);
  float alpha = outerMask * visibility * (1.0 - burnHole);

  // Add subtle shadow under the polaroid
  float shadowD = roundedRectSDF(lp + vec2(0.004, 0.006), outerSize + 0.01, cornerR);
  float shadowMask = smoothstep(0.02, 0.0, shadowD) * 0.25 * visibility * (1.0 - burnPhase);

  return vec4(polaroidColor + shadowMask * 0.01, alpha + shadowMask * (1.0 - alpha));
}

void main(){
  vec2 uv = gl_FragCoord.xy / u_res;
  vec2 aspect = vec2(u_res.x / u_res.y, 1.0);
  vec2 p = (uv - 0.5) * aspect;
  // Mouse: compute heat source at cursor
  float mouseHeat = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mP = (u_mouse / u_res - 0.5) * aspect;
    float mDist = length(p - mP);
    mouseHeat = exp(-mDist * mDist * 8.0);
  }
  float t = u_time;
  float px = 1.0 / min(u_res.x, u_res.y);

  // Background: very subtle animated noise texture
  vec3 bg = vec3(0.039, 0.039, 0.039);
  float bgNoise = snoise(p * 3.0 + t * 0.02) * 0.008;
  bg += bgNoise;

  // Subtle ambient warm glow in background
  float ambientGlow = exp(-length(p) * 2.5) * 0.03;
  bg += vec3(0.8, 0.5, 0.3) * ambientGlow;

  vec3 col = bg;

  // Render polaroids back to front
  int maxPhotos = 8;
  for(int i = 0; i < 8; i++){
    if(float(i) >= u_photoCount) break;
    float idx = float(i);
    vec4 p4 = polaroid(p, idx, t, px);

    // Premultiplied alpha composite
    col = mix(col, p4.rgb, p4.a);
  }

  // Mouse heat: ember glow at cursor
  if (mouseHeat > 0.01) {
    col += vec3(1.0, 0.5, 0.1) * mouseHeat * 0.4;
    col = mix(col, vec3(0.15, 0.05, 0.0), mouseHeat * 0.3);
  }

  // Global vignette
  float vig = 1.0 - smoothstep(0.4, 1.2, length(p * vec2(0.85, 1.0)));
  col *= 0.65 + 0.35 * vig;

  // Film grain
  float grain = (fract(sin(dot(gl_FragCoord.xy, vec2(12.9898,78.233)) + fract(u_time*0.1)*100.0)*43758.5453) - 0.5) * 0.02;
  col += grain;

  // Tone mapping: subtle S-curve
  col = clamp(col, 0.0, 1.0);
  col = col * col * (3.0 - 2.0 * col);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_intensity;
uniform float u_waveSpeed;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define CYCLE 7.0

// ── Hash for noise ──
float hash(float n) {
  return fract(sin(n) * 43758.5453123);
}

float hash2(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// ── Value noise ──
float noise(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

// ── 2D noise for visual grain ──
float noise2d(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash2(i);
  float b = hash2(i + vec2(1.0, 0.0));
  float c = hash2(i + vec2(0.0, 1.0));
  float d = hash2(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── Emotional intensity envelope ──
// Returns 0..1 representing the emotional arc
float emotionCurve(float t) {
  // Phase timing within 7s cycle:
  // 0.0 - 1.5: calm (0.0 - 0.214)
  // 1.5 - 3.5: building (0.214 - 0.5)
  // 3.5 - 5.0: scream (0.5 - 0.714)
  // 5.0 - 7.0: collapse (0.714 - 1.0)
  float phase = fract(t / CYCLE);

  // Calm: gentle sine breathing (wider transitions for smooth blending)
  float calm = smoothstep(0.0, 0.06, phase) * (1.0 - smoothstep(0.14, 0.25, phase));
  float calmVal = 0.08 + 0.04 * sin(phase * PI * 20.0);

  // Building: exponential ramp (overlapping transitions)
  float buildStart = 0.214;
  float buildEnd = 0.5;
  float build = smoothstep(buildStart - 0.03, buildStart + 0.04, phase) * (1.0 - smoothstep(buildEnd - 0.04, buildEnd + 0.02, phase));
  float buildProgress = clamp((phase - buildStart) / (buildEnd - buildStart), 0.0, 1.0);
  // Smooth the progress curve itself
  buildProgress = buildProgress * buildProgress * (3.0 - 2.0 * buildProgress);
  float buildVal = 0.1 + buildProgress * buildProgress * 0.85;

  // Scream: peak with turbulence (wider entry/exit)
  float screamStart = 0.5;
  float screamEnd = 0.714;
  float scream = smoothstep(screamStart - 0.03, screamStart + 0.03, phase) * (1.0 - smoothstep(screamEnd - 0.04, screamEnd + 0.01, phase));
  float screamProgress = clamp((phase - screamStart) / (screamEnd - screamStart), 0.0, 1.0);
  float screamVal = 0.95 + 0.05 * sin(screamProgress * PI);

  // Collapse: flash spike then exponential decay with flutter
  float collapseStart = 0.714;
  float collapse = smoothstep(collapseStart - 0.04, collapseStart + 0.03, phase);
  float collapseProgress = clamp((phase - collapseStart) / (1.0 - collapseStart), 0.0, 1.0);
  // Brief brightness flash at the start of collapse
  float collapseFlash = exp(-collapseProgress * 20.0) * 0.25;
  // Decaying flutter/wobble
  float flutter = sin(collapseProgress * 40.0) * exp(-collapseProgress * 5.0) * 0.08;
  float collapseVal = (0.95 + collapseFlash) * exp(-collapseProgress * 4.5) + flutter;
  collapseVal = max(collapseVal, 0.0);

  return calmVal * calm + buildVal * build + screamVal * scream + collapseVal * collapse;
}

// ── Waveform function ──
// x: position along wave, t: time, emotion: 0..1 intensity
float waveform(float x, float t, float emotion, float speed) {
  float baseFreq = 3.0;
  float timeOsc = t * speed;

  // Base sine wave
  float wave = sin(x * baseFreq * PI * 2.0 + timeOsc * 4.0);

  // Subtle second harmonic always present (warmth in calm phase)
  wave += sin(x * baseFreq * 2.0 * PI * 2.0 + timeOsc * 3.0 + 0.8) * 0.12;

  // Add harmonics that increase with emotion
  float harmonics = emotion * emotion;
  wave += sin(x * baseFreq * 2.0 * PI * 2.0 + timeOsc * 6.0 + 0.5) * harmonics * 0.5;
  wave += sin(x * baseFreq * 3.0 * PI * 2.0 + timeOsc * 8.0 + 1.2) * harmonics * harmonics * 0.35;
  wave += sin(x * baseFreq * 5.0 * PI * 2.0 + timeOsc * 12.0 + 2.1) * harmonics * harmonics * 0.2;
  wave += sin(x * baseFreq * 7.0 * PI * 2.0 - timeOsc * 5.0 + 3.7) * pow(harmonics, 3.0) * 0.15;

  // High frequency noise at peak emotion
  float noiseAmt = smoothstep(0.7, 1.0, emotion);
  wave += (noise(x * 40.0 + timeOsc * 15.0) - 0.5) * 2.0 * noiseAmt * 0.6;
  wave += (noise(x * 80.0 - timeOsc * 20.0) - 0.5) * 2.0 * noiseAmt * noiseAmt * 0.3;

  // Amplitude scales with emotion
  float amplitude = 0.05 + emotion * 0.45;
  wave *= amplitude;

  // Hard clipping at scream peak - creates that harsh distortion
  float clipThreshold = mix(0.5, 0.12, smoothstep(0.8, 1.0, emotion));
  wave = clamp(wave, -clipThreshold, clipThreshold);

  return wave;
}

void main() {
  vec2 fragCoord = gl_FragCoord.xy;
  vec2 uv = fragCoord / u_res;
  float aspect = u_res.x / u_res.y;
  float t = u_time;

  // ── Mouse: shift distortion center ──
  vec2 mouseShift = vec2(0.0);
  if (u_mouse.x > 0.0) {
    vec2 mNorm = u_mouse / u_res;
    mouseShift = (mNorm - 0.5) * 0.3;
  }

  // Emotional intensity
  float emotion = emotionCurve(t) * u_intensity;
  emotion = clamp(emotion, 0.0, 1.0);

  // ── Background ──
  // Dark, with subtle color that shifts with emotion
  vec3 bgCalm = vec3(0.02, 0.01, 0.04);
  vec3 bgScream = vec3(0.06, 0.01, 0.01);
  vec3 bg = mix(bgCalm, bgScream, emotion);

  // Subtle radial gradient behind the wave
  float centerDist = length(uv - vec2(0.5, 0.5));
  float bgGlow = exp(-centerDist * centerDist * 3.0);
  vec3 bgGlowColor = mix(vec3(0.05, 0.02, 0.08), vec3(0.12, 0.02, 0.02), emotion);
  bg += bgGlowColor * bgGlow * (0.3 + emotion * 0.5);

  // ── Screen noise at peak ──
  float screenNoise = 0.0;
  float noiseIntensity = smoothstep(0.6, 1.0, emotion);
  if (noiseIntensity > 0.0) {
    screenNoise = (noise2d(fragCoord * 0.8 + t * 100.0) - 0.5) * noiseIntensity * 0.15;
    screenNoise += (noise2d(fragCoord * 2.5 + t * 200.0) - 0.5) * noiseIntensity * noiseIntensity * 0.08;
  }

  // ── Chromatic aberration offset ──
  float chromatic = smoothstep(0.5, 1.0, emotion) * 0.025 * u_intensity;

  // Vertical jitter during scream
  float jitter = smoothstep(0.85, 1.0, emotion) * (noise(t * 30.0) - 0.5) * 0.015;

  // ── Horizontal glitch displacement during scream ──
  float glitchAmt = smoothstep(0.8, 1.0, emotion);
  float glitchBand = step(0.92, noise(floor(uv.y * 25.0) + floor(t * 8.0) * 7.3));
  float glitchOffset = glitchBand * glitchAmt * (noise(t * 50.0 + uv.y * 10.0) - 0.5) * 0.06;

  // ── Compute waveform SDF for each RGB channel ──
  // Map uv.x to wave x coordinate
  float waveX = uv.x + glitchOffset - mouseShift.x;

  // Centered y coordinate (-0.5 to 0.5) with mouse shift
  float yCenter = uv.y - 0.5 + jitter - mouseShift.y;

  // Compute wave value at this x
  float speed = u_waveSpeed;

  // Red channel - offset for chromatic aberration
  float waveR = waveform(waveX - chromatic, t, emotion, speed);
  float distR = abs(yCenter - waveR);

  // Green channel - center
  float waveG = waveform(waveX, t, emotion, speed);
  float distG = abs(yCenter - waveG);

  // Blue channel - opposite offset
  float waveB = waveform(waveX + chromatic, t, emotion, speed);
  float distB = abs(yCenter - waveB);

  // ── Wave thickness and glow ──
  // Core line thickness (thicker base for warm calm, thicker still during scream)
  float lineThickness = 0.003 + emotion * 0.004;

  // Inner glow radius (wider base glow for warmth)
  float glowRadius = 0.022 + emotion * 0.038;

  // Outer bloom
  float bloomRadius = 0.08 + emotion * 0.14;

  // ── Color palette based on emotion ──
  // Calm: warm lavender/purple with golden undertone
  vec3 calmColor = vec3(0.62, 0.42, 0.88);
  // Building: hot pink/magenta
  vec3 buildColor = vec3(0.95, 0.2, 0.6);
  // Scream: harsh white/red
  vec3 screamCoreColor = vec3(1.0, 0.95, 0.9);
  vec3 screamGlowColor = vec3(1.0, 0.25, 0.1);

  // Interpolate colors
  float buildPhase = smoothstep(0.1, 0.6, emotion);
  float screamPhase = smoothstep(0.7, 0.95, emotion);

  vec3 coreColor = mix(calmColor, buildColor, buildPhase);
  coreColor = mix(coreColor, screamCoreColor, screamPhase);

  vec3 glowColor = mix(calmColor * 0.6, buildColor * 0.7, buildPhase);
  glowColor = mix(glowColor, screamGlowColor, screamPhase);

  // ── Compute per-channel intensities ──
  // Core line
  float coreR = smoothstep(lineThickness, 0.0, distR);
  float coreG = smoothstep(lineThickness, 0.0, distG);
  float coreB = smoothstep(lineThickness, 0.0, distB);

  // Inner glow
  float glowR = exp(-distR * distR / (glowRadius * glowRadius));
  float glowG = exp(-distG * distG / (glowRadius * glowRadius));
  float glowB = exp(-distB * distB / (glowRadius * glowRadius));

  // Outer bloom
  float bloomR = exp(-distR * distR / (bloomRadius * bloomRadius));
  float bloomG = exp(-distG * distG / (bloomRadius * bloomRadius));
  float bloomB = exp(-distB * distB / (bloomRadius * bloomRadius));

  // ── Compose final color ──
  vec3 col = bg;

  // When emotion is low, render as single-color (no chromatic split)
  // When emotion is high, split into RGB channels
  float splitAmount = smoothstep(0.4, 0.9, emotion);

  // Unified wave (low emotion)
  float unifiedCore = smoothstep(lineThickness, 0.0, distG);
  float unifiedGlow = exp(-distG * distG / (glowRadius * glowRadius));
  float unifiedBloom = exp(-distG * distG / (bloomRadius * bloomRadius));

  // Core brightness increases during scream
  float coreBright = 2.0 + smoothstep(0.8, 1.0, emotion) * 1.5;

  vec3 unifiedCol = coreColor * unifiedCore * coreBright
                  + glowColor * unifiedGlow * 0.9
                  + glowColor * 0.35 * unifiedBloom;

  // Split wave (high emotion) - chromatic aberration
  vec3 splitCol = vec3(0.0);
  // Red channel gets the red-shifted wave
  splitCol.r = coreColor.r * coreR * coreBright + glowColor.r * glowR * 0.9 + glowColor.r * 0.35 * bloomR;
  // Green channel gets the center wave
  splitCol.g = coreColor.g * coreG * coreBright + glowColor.g * glowG * 0.9 + glowColor.g * 0.35 * bloomG;
  // Blue channel gets the blue-shifted wave
  splitCol.b = coreColor.b * coreB * coreBright + glowColor.b * glowB * 0.9 + glowColor.b * 0.35 * bloomB;

  vec3 waveCol = mix(unifiedCol, splitCol, splitAmount);
  col += waveCol;

  // ── Reflection: mirrored faded wave below center ──
  // Mirror the y coordinate around center (0.5)
  float reflUvY = 1.0 - uv.y;
  float reflYCenter = reflUvY - 0.5 + jitter;
  float reflDistG = abs(reflYCenter - waveG);
  // Fade: strongest just below center, fading to nothing toward bottom
  float belowCenter = uv.y - 0.5;
  float reflFade = step(0.0, belowCenter) * (1.0 - smoothstep(0.0, 0.35, belowCenter)) * 0.2;
  float reflGlow = exp(-reflDistG * reflDistG / (glowRadius * glowRadius * 3.0));
  float reflBloom = exp(-reflDistG * reflDistG / (bloomRadius * bloomRadius * 2.5));
  vec3 reflCol = glowColor * reflGlow * 0.45 + glowColor * reflBloom * 0.12;
  col += reflCol * reflFade;

  // ── Horizontal scan lines during scream (subtle CRT effect) ──
  float scanline = smoothstep(0.8, 1.0, emotion) * 0.08;
  float scan = sin(fragCoord.y * 1.5) * 0.5 + 0.5;
  col *= 1.0 - scanline * scan;

  // ── Screen noise ──
  col += vec3(screenNoise);

  // ── Subtle edge darkening (vignette) ──
  vec2 vigUV = uv - 0.5;
  float vig = 1.0 - dot(vigUV, vigUV) * 1.8;
  vig = clamp(vig, 0.0, 1.0);
  col *= 0.5 + vig * 0.5;

  // ── Pulsing brightness at scream peak ──
  float pulse = 1.0 + smoothstep(0.85, 1.0, emotion) * sin(t * 25.0) * 0.15;
  col *= pulse;

  // ── Tone mapping ──
  col = col / (1.0 + col * 0.4);
  col = pow(col, vec3(0.95));
  col = max(col, vec3(0.0));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_ringDensity;
uniform float u_driftSpeed;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ── Hash for grain texture ──
float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// ── Concentric ring pattern from a center point ──
// Returns a value in [-1, 1] based on sine of distance
float rings(vec2 uv, vec2 center, float freq) {
  float d = length(uv - center);
  return sin(d * freq);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  float t = u_time;
  float drift = u_driftSpeed;
  float density = u_ringDensity;

  // ── Ring frequency — controls how tight the concentric circles are ──
  float baseFreq = 60.0 * density;

  // ── Subtle breathing — ring spacing pulses slowly ──
  float breathe = 1.0 + 0.04 * sin(t * 0.3) + 0.02 * sin(t * 0.17 + 1.0);
  float freq = baseFreq * breathe;

  // ── Center points — 4 sources orbiting at different speeds and radii ──
  // Each center drifts in a unique elliptical/Lissajous path
  float d = drift;

  vec2 c0 = vec2(
    0.22 * cos(t * d * 0.31 + 0.0),
    0.18 * sin(t * d * 0.43 + 0.0)
  );

  vec2 c1 = vec2(
    0.25 * cos(t * d * 0.23 + 2.1),
    0.20 * sin(t * d * 0.37 + 1.4)
  );

  vec2 c2 = vec2(
    0.19 * sin(t * d * 0.41 + 4.2),
    0.24 * cos(t * d * 0.29 + 3.1)
  );

  vec2 c3 = vec2(
    0.21 * cos(t * d * 0.19 + 5.7),
    0.17 * sin(t * d * 0.47 + 0.8)
  );

  // ── Mouse-driven 5th center — shifts one pattern layer ──
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    c3 = mUV;
  }

  // ── Each center generates rings at a slightly different frequency ──
  // The frequency differences are what create the moiré beats
  float f0 = freq;
  float f1 = freq * 1.07;
  float f2 = freq * 0.93;
  float f3 = freq * 1.13;

  // ── Compute ring patterns ──
  float r0 = rings(uv, c0, f0);
  float r1 = rings(uv, c1, f1);
  float r2 = rings(uv, c2, f2);
  float r3 = rings(uv, c3, f3);

  // ── Combine ring patterns through multiplication ──
  // Multiplying sine patterns produces sum and difference frequencies,
  // which is exactly the moiré interference effect
  float moire = r0 * r1 * r2 * r3;

  // ── Also compute additive blend for a secondary interference layer ──
  float additive = (r0 + r1 + r2 + r3) * 0.25;

  // ── Blend multiplicative and additive for richer pattern ──
  float pattern = moire * 0.7 + additive * 0.3;

  // ── Normalize pattern to [0, 1] range ──
  // Multiplicative moiré ranges roughly [-1, 1], additive too
  float intensity = pattern * 0.5 + 0.5;
  intensity = clamp(intensity, 0.0, 1.0);

  // ── Color mapping ──
  // Map interference intensity through a cool blue-violet-teal palette

  // Dark zones: deep warm-black
  vec3 darkColor = vec3(0.05, 0.035, 0.025);

  // Mid zones: deep amber-brown
  vec3 midColor = vec3(0.35, 0.22, 0.12);

  // Bright interference zones: warm amber
  vec3 brightColor = vec3(0.65, 0.42, 0.22);

  // Peak interference: bright gold-white
  vec3 peakColor = vec3(0.9, 0.78, 0.55);

  // ── Three-stop gradient through the palette ──
  vec3 col;
  if (intensity < 0.35) {
    col = mix(darkColor, midColor, intensity / 0.35);
  } else if (intensity < 0.65) {
    col = mix(midColor, brightColor, (intensity - 0.35) / 0.3);
  } else {
    col = mix(brightColor, peakColor, (intensity - 0.65) / 0.35);
  }

  // ── Add subtle luminance boost at interference peaks ──
  // Where the multiplicative pattern hits strong peaks, push toward warm white
  float peakMask = smoothstep(0.7, 1.0, intensity);
  col += peakColor * peakMask * 0.15;

  // ── Secondary interference shimmer ──
  // Use pairwise products for additional subtle patterns
  float shimmer = r0 * r2 * 0.5 + 0.5;
  shimmer = smoothstep(0.4, 0.8, shimmer);
  col += vec3(0.12, 0.08, 0.04) * shimmer * 0.2;

  // ── Vignette — darken edges to focus attention on center ──
  float vig = 1.0 - dot(uv * 0.9, uv * 0.9);
  vig = clamp(vig, 0.0, 1.0);
  vig = pow(vig, 0.5);
  col *= vig;

  // ── Fine grain — subtle noise overlay for tactile quality ──
  float grain = (hash(gl_FragCoord.xy + fract(t * 37.0) * 1000.0) - 0.5) * 0.03;
  col += grain;

  // ── Tone mapping — keep blacks deep ──
  col = max(col, vec3(0.0));
  col = col / (1.0 + col * 0.2);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_waveSpeed;
uniform float u_lineCount;
uniform vec2 u_mouse;

#define S smoothstep
#define PI 3.14159265

// ── Hash for noise ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Rotate 2D
vec2 rot(vec2 p, float a) {
  float c = cos(a), s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

// Analytical dipole field line distance.
// Field lines satisfy: r = R_k * sin^2(theta) in polar coords.
// For a pixel at (r, theta), the field line passing through it has R = r / sin^2(theta).
// We quantize R into discrete lines and measure how far this pixel is from the nearest one.
float fieldLineGlow(vec2 lp, float numLines, float t) {
  float r = length(lp);
  if (r < 0.01) return 0.0;
  float theta = atan(abs(lp.y), lp.x);

  // Avoid singularity at theta=0 and theta=PI
  float sinT = sin(theta);
  if (sinT < 0.05) return 0.0;

  // The field line constant for this pixel
  float R = r / (sinT * sinT);

  // Quantize into discrete field lines
  float spacing = 0.8 / numLines;
  float lineIdx = R / spacing;
  float nearest = floor(lineIdx + 0.5) * spacing;

  // Distance in R-space, convert to approximate screen distance
  float dR = abs(R - nearest);
  // dr/dR at this theta: dr = sin^2(theta) * dR
  float screenDist = dR * sinT * sinT;

  // Silk-style glow: thin bright core with edge fade
  float lw = 0.06 * S(0.05, 0.5, r);
  float l = S(lw, 0.0, screenDist - 0.004);

  // Fade at extremities
  float fade = S(0.9, 0.2, r) * S(0.0, 0.05, sinT);

  // Energy pulse flowing along the field lines (theta = path parameter)
  float pulse = pow(sin(theta * 3.0 - t * 1.5) * 0.5 + 0.5, 3.0);
  float brightness = 0.4 + pulse * 0.6;

  return l * fade * brightness;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * u_res.xy) / u_res.y;
  float t = u_time * u_waveSpeed;

  // Poles — mouse rotates the dipole axis
  float poleAngle = 0.0;
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - 0.5 * u_res.xy) / u_res.y;
    poleAngle = atan(mUV.y, mUV.x);
  }
  vec2 pole1 = vec2(cos(poleAngle), sin(poleAngle)) * -0.3;
  vec2 pole2 = vec2(cos(poleAngle), sin(poleAngle)) * 0.3;
  vec2 center = vec2(0.0);
  vec2 axis = normalize(pole2 - pole1);

  // Transform uv into dipole-local coords (axis-aligned)
  vec2 lp = uv - center;
  lp = vec2(dot(lp, axis), dot(lp, vec2(-axis.y, axis.x)));

  // Noise perturbation
  float n = noise(vec2(lp.x * 3.0, t * 0.1)) * 0.01;
  lp += vec2(n, n * 0.5);

  float numLines = u_lineCount;

  // Compute glow for both halves of the dipole (y>0 and y<0)
  // Upper half
  float glow1 = fieldLineGlow(lp, numLines, t);
  // Lower half (mirror)
  float glow2 = fieldLineGlow(vec2(lp.x, -lp.y), numLines, t);
  float glow = max(glow1, glow2);


  // Color: warm amber gradient based on position
  float r = length(uv);
  float angle = atan(lp.y, lp.x) / PI;
  vec3 lineCol = vec3(
    0.35 + abs(angle) * 0.55,
    0.25 + abs(angle) * 0.3,
    0.3 + (1.0 - abs(angle)) * 0.1
  );

  vec3 col = glow * lineCol;

  // Subtle glow at poles
  float g1 = 0.006 / (length(uv - pole1) + 0.01);
  float g2 = 0.006 / (length(uv - pole2) + 0.01);
  col += vec3(0.9, 0.6, 0.3) * (g1 + g2) * 0.12;

  // ── Vignette ──
  float vig = 1.0 - dot(uv, uv) * 0.4;
  col *= max(vig, 0.0);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_waveSpeed;
uniform float u_lineCount;
uniform float u_amplitude;
uniform float u_rotation;
uniform vec2 u_mouse;
uniform float u_dragAngle;

// ── Hash for noise ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// ── Smooth value noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

#define S smoothstep

mat2 rot2(float a) { float c=cos(a),s=sin(a); return mat2(c,-s,s,c); }

// ── Single vertical curtain line ──
vec3 curtainLine(vec2 uv, float speed, float freq, vec3 c, float t) {
  // Sine displacement on x based on y position (vertical flow)
  uv.x += S(1.0, 0.0, abs(uv.y)) * sin(t * speed + uv.y * freq) * 0.2;
  float lw = 0.06 * S(0.2, 0.9, abs(uv.y));
  float l = S(lw, 0.0, abs(uv.x) - 0.004);
  // Edge fade top/bottom instead of left/right
  float fade = S(1.0, 0.3, abs(uv.y));
  return l * c * fade;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * u_res.xy) / u_res.y;
  uv = rot2(u_dragAngle + u_rotation) * uv;
  // Base from sliders, mouse modifies on top
  float mouseAmp = u_amplitude;
  float mouseFreq = 1.0;
  if (u_mouse.x > 0.0) {
    vec2 mUV = u_mouse / u_res;
    mouseAmp *= 0.3 + mUV.y * 1.4;
    mouseFreq = 0.5 + mUV.x * 1.0;
  }
  float t = u_time * u_waveSpeed;
  int lineCount = int(u_lineCount);

  vec3 col = vec3(0.0);

  for (int i = 0; i < 12; i++) {
    if (i >= lineCount) break;
    float fi = float(i);
    float frac = fi / max(u_lineCount - 1.0, 1.0);

    float speed = (0.6 + frac * 0.5) * mouseFreq;
    float freq = (4.0 + frac * 2.0) * mouseAmp;

    // Color: warm amber at base (bottom), cool teal at top
    vec3 warmAmber = vec3(0.85, 0.55, 0.25);
    vec3 coolTeal = vec3(0.2, 0.6, 0.65);
    // Blend per-line from amber to teal
    vec3 lineCol = mix(warmAmber, coolTeal, frac) * (0.5 + frac * 0.5);

    // Also blend per-pixel based on vertical position
    float yBlend = S(-0.4, 0.5, uv.y);
    vec3 pixelCol = mix(warmAmber, coolTeal, yBlend) * (0.4 + frac * 0.6);
    lineCol = mix(lineCol, pixelCol, 0.6);

    // Slow lateral drift
    float drift = sin(t * 0.15 + fi * 1.3) * 0.03;

    float nOff = noise(vec2(uv.y * 2.0 + fi * 3.7, t * 0.1 + fi)) * 0.015;

    col += curtainLine(uv + vec2(nOff + drift, 0.0), speed, freq, lineCol, t);
  }

  // ── Vignette ──
  float vig = 1.0 - dot(uv, uv) * 0.4;
  col *= max(vig, 0.0);

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_waveSpeed;
uniform float u_lineCount;
uniform vec2 u_mouse;

#define S smoothstep
#define PI 3.14159265
#define TAU 6.28318530

// ── Hash for noise ──
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Distance from point to nearest logarithmic spiral arm
// Spiral: r = a * exp(b * theta)
// Inverted: theta = ln(r/a) / b
// For a given r, the spiral passes at angles theta_n = (ln(r/a)/b) + n*TAU
// We find the closest arm by checking angular distance
float spiralDist(vec2 uv, float a, float b, float numArms, float t) {
  float r = length(uv);
  if (r < 0.001) return 1e6;
  float angle = atan(uv.y, uv.x);

  // Where does the spiral cross this radius?
  float baseTheta = log(r / a) / b;

  // Add time rotation
  baseTheta -= t * 0.3 + u_mouse.x;

  // Find nearest arm
  float armSpacing = TAU / numArms;
  float nearest = mod(angle - baseTheta, armSpacing);
  if (nearest > armSpacing * 0.5) nearest -= armSpacing;

  // Convert angular distance to approximate Euclidean distance
  // d ~ r * |delta_theta| for small angles
  float d = abs(nearest) * r;

  // Add sine undulation along the spiral
  float undulation = sin(baseTheta * 4.0 + t * 0.5) * 0.015;
  d += undulation;
  d = abs(d);

  return d;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * u_res.xy) / u_res.y;
  float t = u_time * u_waveSpeed;

  // Center drifts slowly
  vec2 center = vec2(sin(t * 0.07) * 0.05, cos(t * 0.09) * 0.04);
  vec2 p = uv - center;

  float r = length(p);
  int lineCount = int(u_lineCount);

  vec3 col = vec3(0.0);

  for (int i = 0; i < 10; i++) {
    if (i >= lineCount) break;
    float fi = float(i);
    float frac = fi / max(u_lineCount - 1.0, 1.0);

    // Each layer: different tightness and scale
    float a = 0.02 + frac * 0.03;
    float b = 0.15 + frac * 0.08;
    float numArms = 3.0 + fi;

    // Noise perturbation
    float nOff = noise(vec2(fi * 3.7, t * 0.1)) * 0.008;

    float dist = spiralDist(p + vec2(nOff), a, b, numArms, t + fi * 0.5);

    // Silk glow: thin bright core with edge fade
    float lw = 0.05 * S(0.1, 0.6, r);
    float l = S(lw, 0.0, dist - 0.004);

    // Brighten toward center, fade at edge
    float radialFade = S(0.9, 0.15, r) * S(0.0, 0.04, r);

    // Color: warm amber to gold
    vec3 lineCol = vec3(
      0.25 + frac * 0.65,
      0.2 + frac * 0.4,
      0.25 + (1.0 - frac) * 0.15
    );

    col += l * lineCol * radialFade;
  }

  // Central glow
  float centerGlow = 0.015 / (r + 0.02);
  col += vec3(0.9, 0.65, 0.35) * centerGlow * 0.15;

  // ── Vignette ──
  float vig = 1.0 - dot(uv, uv) * 0.4;
  col *= max(vig, 0.0);

  gl_FragColor = vec4(col, 1.0);
}

