  col += orb(uv, s7, dimRose, 0.14, 0.12);



  // ── Layer 5: Vignette ──
  float vd = length(uv * vec2(1.1, 1.0));
  float vignette = 1.0 - smoothstep(0.5, 1.1, vd);
  col *= vignette;

  // Clamp to avoid artifacts
  col = max(col, vec3(0.0));

  // Minimal tone mapping — just a soft knee to avoid hard clipping
  // where overlap creates values > 1, gently compress; otherwise pass through
  col = mix(col, sqrt(col), smoothstep(0.6, 1.5, col));

  // Mouse: brighten blooms near cursor + add warm glow
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    float mDist = length(uv - mUV);
    float attract = exp(-mDist * mDist * 4.0);
    col *= 1.0 + attract * 1.5;
    col += vec3(0.8, 0.6, 0.9) * attract * 0.08;
  }
  // ── Film grain (applied in display space, after tone mapping) ──
  float grain = fract(sin(dot(gl_FragCoord.xy + fract(u_time) * 100.0, vec2(12.9898, 78.233))) * 43758.5453) - 0.5;
  col += grain * 0.3 * u_grain;
  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_flareSpread;
uniform float u_driftSpeed;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define NUM_LIGHTS 6

// ── Hash functions ──
float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float hash1(float n) {
  return fract(sin(n * 127.1) * 43758.5453);
}

// ── Smooth value noise ──
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// ── FBM noise for ambient haze ──
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p = p * 2.1 + vec2(1.7, 3.2);
    a *= 0.5;
  }
  return v;
}

// ── Per-light color tint ──
// 0: cobalt, 1: amber, 2: teal, 3: warm white, 4: rose, 5: cool white
vec3 lightTint(int idx) {
  if (idx == 0) return vec3(0.30, 0.45, 1.00);
  if (idx == 1) return vec3(1.00, 0.65, 0.20);
  if (idx == 2) return vec3(0.20, 0.85, 0.75);
  if (idx == 3) return vec3(1.00, 0.92, 0.80);
  if (idx == 4) return vec3(0.95, 0.40, 0.55);
  return vec3(0.75, 0.85, 1.00);
}

// ── Light source positions with slow cinematic drift ──
vec2 lightPos(int idx, float t) {
  float fi = float(idx);
  float seed = fi * 47.3;
  // Slow Lissajous-like orbits, each light on its own path
  float ax = 0.30 + hash1(seed) * 0.20;
  float ay = 0.35 + hash1(seed + 1.0) * 0.20;
  float fx = 0.07 + hash1(seed + 2.0) * 0.05;
  float fy = 0.05 + hash1(seed + 3.0) * 0.04;
  float px = hash1(seed + 4.0) * PI * 2.0;
  float py = hash1(seed + 5.0) * PI * 2.0;
  // Noise perturbation for organic feel
  float nx = noise(vec2(t * 0.03 + fi * 10.0, 0.0)) * 0.08 - 0.04;
  float ny = noise(vec2(0.0, t * 0.025 + fi * 10.0)) * 0.06 - 0.03;
  return vec2(
    sin(t * fx + px) * ax + nx,
    sin(t * fy + py) * ay + ny
  );
}

// ── Light brightness (pulsing subtly, dimmer per light for 6 sources) ──
float lightBrightness(int idx, float t) {
  float fi = float(idx);
  float base = 0.45 + hash1(fi * 13.7 + 100.0) * 0.25;
  float pulse = sin(t * (0.15 + hash1(fi * 23.1) * 0.1) + fi * 2.0) * 0.12;
  return base + pulse;
}

// ── Anamorphic flare for a single light source ──
// tint is the per-light color identity
vec3 anamorphicFlare(vec2 uv, vec2 lp, float brightness, float spread, vec3 tint) {
  vec2 delta = uv - lp;

  // Horizontal stretch factor for the characteristic anamorphic look
  float stretch = 7.0 * spread;

  // ── Soft Gaussian point light (the core) ──
  float coreD = length(delta);
  float core = exp(-coreD * coreD * 160.0) * brightness * 0.45;
  vec3 coreCol = mix(vec3(1.0, 0.97, 0.90), tint, 0.3) * core;

  // ── Anamorphic horizontal streak ──
  float streakDx = delta.x / stretch;
  float streakDy = delta.y;

  // Main streak envelope: very wide in x, tight in y
  float streakD = streakDx * streakDx * 12.0 + streakDy * streakDy * 600.0;
  float streak = exp(-streakD) * brightness * 0.35;

  // Chromatic aberration: warm orange left, cool blue right
  float chromaOffset = 0.015 * spread;
  float streakR_dx = (delta.x - chromaOffset) / stretch;
  float streakB_dx = (delta.x + chromaOffset) / stretch;
  float streakR_d = streakR_dx * streakR_dx * 12.0 + streakDy * streakDy * 600.0;
  float streakB_d = streakB_dx * streakB_dx * 12.0 + streakDy * streakDy * 600.0;
  float streakR = exp(-streakR_d) * brightness * 0.35;
  float streakB = exp(-streakB_d) * brightness * 0.35;

  // Chromatic fringing: warm orange on one side, cool blue on the other
  float edgeness = smoothstep(0.0, 0.35 * spread, abs(delta.x));

  // Warm fringe color (orange) and cool fringe color (blue)
  vec3 warmFringe = vec3(1.00, 0.55, 0.15);
  vec3 coolFringe = vec3(0.15, 0.35, 1.00);

  // Blend from the light tint at center to directional fringe at edges
  vec3 leftColor = mix(tint, warmFringe, edgeness);
  vec3 rightColor = mix(tint, coolFringe, edgeness);
  vec3 streakTint = mix(leftColor, rightColor, smoothstep(-0.1, 0.1, delta.x));

  // Build streak color with chromatic separation
  vec3 streakCol = vec3(0.0);
  streakCol.r = streakR * streakTint.r;
  streakCol.g = streak * streakTint.g;
  streakCol.b = streakB * streakTint.b;

  // ── Secondary wider, dimmer streak for extra softness ──
  float wideStretch = stretch * 1.6;
  float wideDx = delta.x / wideStretch;
  float wideD = wideDx * wideDx * 8.0 + streakDy * streakDy * 700.0;
  float wideStreak = exp(-wideD) * brightness * 0.15;
  vec3 wideCol = mix(tint * 0.6, mix(warmFringe, coolFringe, smoothstep(-0.2, 0.2, delta.x)) * 0.4, edgeness) * wideStreak;

  // ── Bokeh halo around the brightest point ──
  float haloR = 0.05 + brightness * 0.015;
  float haloDist = abs(coreD - haloR);
  float halo = exp(-haloDist * haloDist * 3500.0) * brightness * 0.10;
  float haloR2 = haloR * 1.8;
  float haloDist2 = abs(coreD - haloR2);
  float halo2 = exp(-haloDist2 * haloDist2 * 5000.0) * brightness * 0.04;
  vec3 haloCol = tint * 0.8 * halo + vec3(0.50, 0.60, 0.80) * halo2;

  return coreCol + streakCol + wideCol + haloCol;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - u_res * 0.5) / min(u_res.x, u_res.y);
  float aspect = u_res.x / u_res.y;
  float t = u_time * u_driftSpeed;


  // ── Layer 1: Pure black background ──
  vec3 col = vec3(0.0);

  // ── Ambient warm haze field (subtle noise-based glow) ──
  vec2 hazeUV = uv * 1.5 + vec2(t * 0.01, t * 0.007);
  float hazeNoise = fbm(hazeUV);
  float hazeNoise2 = fbm(hazeUV * 0.7 + vec2(5.3, 2.1));
  vec3 hazeColor = mix(vec3(0.35, 0.22, 0.10), vec3(0.12, 0.15, 0.30), hazeNoise2);
  col += hazeColor * hazeNoise * 0.03;

  // ── Light sources with anamorphic flares and bokeh ──
  for (int i = 0; i < NUM_LIGHTS; i++) {
    vec2 lp = lightPos(i, t);
    float bright = lightBrightness(i, t);
    vec3 tint = lightTint(i);
    col += anamorphicFlare(uv, lp, bright, u_flareSpread, tint);
  }

  // ── Mouse: cursor becomes an additional light source ──
  if (u_mouse.x > 0.0) {
    vec2 mUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    col += anamorphicFlare(uv, mUV, 0.8, u_flareSpread, vec3(0.9, 0.8, 0.6));
  }

  // ── Lens dust / sparkle noise ──
  vec2 dustUV = gl_FragCoord.xy * 0.8;
  float dustNoise = hash(dustUV + fract(u_time * 0.7) * 200.0);
  float dust = smoothstep(0.985, 1.0, dustNoise);
  float dustLight = 0.0;
  for (int i = 0; i < NUM_LIGHTS; i++) {
    vec2 lp = lightPos(i, t);
    float d = length(uv - lp);
    dustLight += exp(-d * d * 8.0) * lightBrightness(i, t);
  }
  dustLight = min(dustLight, 1.2);
  col += vec3(0.9, 0.85, 0.7) * dust * dustLight * 0.4;

  // ── Subtle warm ambient haze near lights ──
  float haze = 0.0;
  for (int i = 0; i < NUM_LIGHTS; i++) {
    vec2 lp = lightPos(i, t);
    float d = length(uv - lp);
    haze += exp(-d * d * 3.0) * lightBrightness(i, t) * 0.012;
  }
  col += vec3(0.40, 0.25, 0.12) * haze;

  // ── Film grain ──
  vec2 grainSeed = gl_FragCoord.xy + fract(u_time * 60.0) * vec2(1973.0, 9277.0);
  float grain = (hash(grainSeed) - 0.5) * 0.03;
  col += grain;

  // ── Vignette ──
  float vd = length(uv * vec2(1.2, 1.0));
  float vignette = 1.0 - smoothstep(0.3, 0.95, vd);
  vignette = vignette * vignette;
  col *= vignette;

  // ── Tone mapping ──
  col = max(col, vec3(0.0));
  col = col / (col + vec3(0.6)) * 1.5;

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_foldSpeed;
uniform float u_layerCount;
uniform vec2 u_mouse;

// ── Hash functions ──
float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

// ── Simplex-like value noise ──
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// ── FBM ──
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  vec2 shift = vec2(100.0);
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p = rot * p * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

// ── Domain warp for tectonic deformation ──
vec2 tectonicWarp(vec2 uv, float t) {
  float slow = t * 0.15;
  // Large-scale folding
  float warpX = fbm(uv * 1.5 + vec2(slow * 0.7, slow * 0.3)) - 0.5;
  float warpY = fbm(uv * 1.5 + vec2(slow * 0.5 + 50.0, slow * 0.8 + 30.0)) - 0.5;
  // Compression waves
  float compress = sin(uv.x * 2.0 + slow * 0.4) * 0.08;
  // Shearing
  float shear = sin(uv.y * 3.0 + slow * 0.6) * 0.06;
  return vec2(
    uv.x + warpX * 0.25 + shear,
    uv.y + warpY * 0.18 + compress
  );
}

// ── Layer boundary function ──
float layerBoundary(float x, float baseY, float idx, float t) {
  float h1 = hash11(idx * 7.13);
  float h2 = hash11(idx * 13.37);
  float h3 = hash11(idx * 23.71);
  float freq1 = 1.5 + h1 * 2.5;
  float freq2 = 3.0 + h2 * 3.0;
  float amp1 = 0.04 + h1 * 0.06;
  float amp2 = 0.015 + h2 * 0.025;
  float phase1 = t * (0.1 + h3 * 0.15);
  float phase2 = t * (0.08 + h1 * 0.12);
  // Main fold
  float fold = amp1 * sin(x * freq1 + phase1 + h2 * 6.28);
  // Secondary ripple
  fold += amp2 * sin(x * freq2 + phase2 + h3 * 6.28);
  // Noise-based deformation for organic feel
  fold += 0.02 * vnoise(vec2(x * 4.0 + h1 * 100.0, t * 0.2 + idx));
  return baseY + fold;
}

// ── Earth tone palette ──
vec3 stratumColor(float idx, float maxLayers) {
  // 7 earth tone colors
  vec3 colors[7];
  colors[0] = vec3(145.0, 105.0, 60.0) / 255.0;   // Warm umber
  colors[1] = vec3(190.0, 155.0, 105.0) / 255.0;  // Muted amber
  colors[2] = vec3(215.0, 195.0, 155.0) / 255.0;  // Parchment
  colors[3] = vec3(225.0, 205.0, 165.0) / 255.0;  // Pale straw
  colors[4] = vec3(115.0, 85.0, 55.0) / 255.0;    // Dark walnut
  colors[5] = vec3(165.0, 120.0, 75.0) / 255.0;   // Soft sienna
  colors[6] = vec3(230.0, 218.0, 190.0) / 255.0;  // Warm cream
  // Pick from palette using hashed index
  float h = hash11(idx * 17.31 + 3.7);
  int ci = int(mod(floor(h * 7.0), 7.0));
  vec3 base;
  if (ci == 0) base = colors[0];
  else if (ci == 1) base = colors[1];
  else if (ci == 2) base = colors[2];
  else if (ci == 3) base = colors[3];
  else if (ci == 4) base = colors[4];
  else if (ci == 5) base = colors[5];
  else base = colors[6];
  // Slight per-layer variation
  float h2 = hash11(idx * 31.17);
  base += (h2 - 0.5) * 0.06;
  return base;
}

// ── Grain texture per layer — washi paper fibers ──
float grainTexture(vec2 uv, float layerIdx) {
  float h = hash11(layerIdx * 41.93);
  float h2 = hash11(layerIdx * 67.19);
  float intensity = 0.0;
  // Primary fiber direction per layer (varies by layer)
  float fiberAngle = h * 3.14 * 0.3;
  float ca = cos(fiberAngle), sa = sin(fiberAngle);
  vec2 rotUV = vec2(uv.x * ca - uv.y * sa, uv.x * sa + uv.y * ca);
  // Long directional fibers (stretched noise)
  float fiber1 = vnoise(vec2(rotUV.x * 120.0, rotUV.y * 18.0) + layerIdx * 30.0);
  float fiber2 = vnoise(vec2(rotUV.x * 80.0, rotUV.y * 12.0) + layerIdx * 50.0 + 100.0);
  intensity = fiber1 * 0.08 + fiber2 * 0.05;
  // Softer cross-fibers
  float cross = vnoise(vec2(rotUV.x * 15.0, rotUV.y * 70.0) + layerIdx * 40.0);
  intensity += cross * 0.03;
  // Subtle overall paper texture
  intensity += vnoise(uv * 50.0 + layerIdx * 25.0) * 0.025;
  return intensity - 0.04;
}

// ── Crystalline sparkles ──
float sparkle(vec2 uv, float t, float layerIdx) {
  float h = hash11(layerIdx * 53.71);
  // Only some layers have crystals
  if (h < 0.4) return 0.0;
  float density = 60.0 + h * 80.0;
  vec2 cell = floor(uv * density);
  vec2 cellHash = hash22(cell + layerIdx * 7.0);
  // Position within cell
  vec2 cellUV = fract(uv * density);
  vec2 sparklePos = cellHash;
  float dist = length(cellUV - sparklePos);
  // Time-varying twinkle
  float phase = cellHash.x * 6.28 + cellHash.y * 3.14;
  float twinkle = sin(t * (2.0 + cellHash.x * 4.0) + phase);
  float threshold = 0.7 + twinkle * 0.25;
  float sparkleVal = smoothstep(threshold, threshold + 0.05, cellHash.x * cellHash.y + 0.3);
  // Sharp point of light
  sparkleVal *= smoothstep(0.06, 0.01, dist);
  return sparkleVal * 0.8;
}

// ── Cross-cutting faults ──
float faultDisplacement(vec2 uv, float t) {
  float totalDisp = 0.0;
  // 3 fault lines
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float h1 = hash11(fi * 71.13 + 5.0);
    float h2 = hash11(fi * 97.31 + 11.0);
    float h3 = hash11(fi * 37.71 + 17.0);
    // Fault line: diagonal line across the view
    float angle = 0.5 + h1 * 1.2;  // 30-90 degrees
    float offset = h2 * 2.0 - 1.0;
    float ca = cos(angle), sa = sin(angle);
    float lineVal = (uv.x - 0.5) * ca + (uv.y - 0.5) * sa + offset * 0.3;
    // Add noise to make fault line irregular
    lineVal += vnoise(vec2(uv.x * 8.0 + fi * 50.0, uv.y * 8.0 + t * 0.05)) * 0.02;
    // Sharp step with thin transition
    float faultWidth = 0.003 + h3 * 0.004;
    float side = smoothstep(-faultWidth, faultWidth, lineVal);
    // Displacement amount varies slowly with time
    float dispAmount = (0.01 + h3 * 0.02) * sin(t * 0.08 + fi * 2.0);
    totalDisp += side * dispAmount;
  }
  return totalDisp;
}

// ── Fault line visibility (thin dark lines) ──
float faultLine(vec2 uv, float t) {
  float line = 0.0;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float h1 = hash11(fi * 71.13 + 5.0);
    float h2 = hash11(fi * 97.31 + 11.0);
    float angle = 0.5 + h1 * 1.2;
    float offset = h2 * 2.0 - 1.0;
    float ca = cos(angle), sa = sin(angle);
    float lineVal = (uv.x - 0.5) * ca + (uv.y - 0.5) * sa + offset * 0.3;
    lineVal += vnoise(vec2(uv.x * 8.0 + fi * 50.0, uv.y * 8.0 + t * 0.05)) * 0.02;
    // Thin dark line at fault
    float faultVis = 1.0 - smoothstep(0.0, 0.004, abs(lineVal));
    line = max(line, faultVis * 0.4);
  }
  return line;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;
  vec2 uvAspect = vec2(uv.x * aspect, uv.y);

  float t = u_time * u_foldSpeed;
  float layerCount = floor(u_layerCount);

  // Apply tectonic domain warp
  vec2 warped = tectonicWarp(uvAspect, t);

  // Mouse parallax offset (each layer shifts differently)
  vec2 mOff = vec2(0.0);
  if (u_mouse.x >= 0.0) {
    mOff = (u_mouse - 0.5) * vec2(-0.12, -0.06);
  }

  // Determine which layer this pixel is in
  float layerSpacing = 1.0 / (layerCount + 1.0);
  float currentLayer = -1.0;
  float layerPos = 0.0;  // 0-1 position within current layer

  // Compute boundaries and find current layer
  float prevBound = -0.2;  // below screen
  for (int i = 0; i < 24; i++) {
    if (float(i) >= layerCount) break;
    float fi = float(i);
    float baseY = (fi + 1.0) * layerSpacing;
    // Per-layer parallax: deeper layers shift more
    float layerDepth = fi / layerCount;
    float px = warped.x + mOff.x * (0.3 + layerDepth * 1.5);
    float bound = layerBoundary(px, baseY, fi, t);
    bound += mOff.y * (0.1 + layerDepth * 0.4);
    if (warped.y >= prevBound && warped.y < bound) {
      currentLayer = fi;
      float thickness = bound - prevBound;
      layerPos = (warped.y - prevBound) / max(thickness, 0.001);
      break;
    }
    prevBound = bound;
  }
  // Top layer catches everything above last boundary
  if (currentLayer < 0.0) {
    currentLayer = layerCount;
    layerPos = 0.5;
  }

  // Get stratum color
  vec3 col = stratumColor(currentLayer, layerCount);

  // Add grain texture
  float grain = grainTexture(warped, currentLayer);
  col += grain;

  // Subtle shading at layer boundaries (darker at edges, lighter in middle)
  float edgeShade = smoothstep(0.0, 0.15, layerPos) * smoothstep(1.0, 0.85, layerPos);
  col *= 0.85 + 0.15 * edgeShade;

  // Paper edge shadow — soft shadow at bottom of each layer
  float edgeShadow = smoothstep(0.0, 0.08, layerPos);
  col *= 0.82 + 0.18 * edgeShadow;
  // Slight highlight at top edge (paper catching light)
  float topHighlight = smoothstep(1.0, 0.92, layerPos);
  col += vec3(0.04, 0.035, 0.025) * (1.0 - topHighlight);

  // Subtle vignette
  float vig = 1.0 - 0.3 * length((uv - 0.5) * 1.5);
  col *= vig;

  // Overall paper texture overlay (uniform across all layers)
  float paperTex = vnoise(gl_FragCoord.xy * 0.15) * 0.03;
  paperTex += (hash21(gl_FragCoord.xy + fract(u_time * 0.1) * 1000.0) - 0.5) * 0.015;
  col += paperTex;

  // Slightly desaturate for natural dyed paper feel
  float lum = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(vec3(lum), col, 0.82);

  // Warm tone adjustment
  col = pow(col, vec3(0.95, 1.0, 1.08));

  gl_FragColor = vec4(col, 1.0);
}

precision highp float;
uniform float u_time;
uniform vec2 u_res;
uniform float u_ditherScale;
uniform float u_bitDepth;
uniform vec2 u_mouse;

#define PI 3.14159265359
#define TAU 6.28318530718

// ══════════════════════════════════════════
// Hash / noise helpers
// ══════════════════════════════════════════
float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 4; i++) {
    v += a * vnoise(p);
    p = rot * p * 2.0 + vec2(100.0);
    a *= 0.5;
  }
  return v;
}

// ══════════════════════════════════════════
// Bayer 8x8 dithering matrix (float-based, WebGL 1.0 safe)
// ══════════════════════════════════════════
// Standard Bayer 2x2: [[0,2],[3,1]]
// Recursive: M_2N(x,y) = 4*M_N(x%N,y%N) + M_2(x/N,y/N)
float bayer8(vec2 p) {
  vec2 fp = floor(mod(p, 8.0));
  // Encode 8x8 Bayer via 3 recursive levels of 2x2
  // Each level: map (bx, by) -> Bayer2x2 value
  // Bayer2x2(0,0)=0, (1,0)=2, (0,1)=3, (1,1)=1
  float val = 0.0;

  // Level 1: coarsest (4x4 blocks)
  float bx = step(4.0, fp.x);
  float by = step(4.0, fp.y);
  // Bayer2x2 via formula: 2*bx + by - 2*bx*by + 2*by*(1-bx)
  // Simpler: just encode directly
  // (0,0)->0, (1,0)->2, (0,1)->3, (1,1)->1
  float b = bx * 2.0 * (1.0 - by) + (1.0 - bx) * 3.0 * by + bx * by * 1.0;
  val += b * 16.0;

  // Level 2: mid (2x2 blocks within each 4x4)
  float mx = mod(fp.x, 4.0);
  float my = mod(fp.y, 4.0);
  bx = step(2.0, mx);
  by = step(2.0, my);
  b = bx * 2.0 * (1.0 - by) + (1.0 - bx) * 3.0 * by + bx * by * 1.0;
  val += b * 4.0;

  // Level 3: finest (pixel pairs)
  float lx = mod(fp.x, 2.0);
  float ly = mod(fp.y, 2.0);
  bx = step(1.0, lx);
  by = step(1.0, ly);
  b = bx * 2.0 * (1.0 - by) + (1.0 - bx) * 3.0 * by + bx * by * 1.0;
  val += b;

  return val / 64.0;
}

// ══════════════════════════════════════════
// Halftone dot pattern
// ══════════════════════════════════════════
float halftone(vec2 p, float size) {
  vec2 cell = floor(p / size) * size + size * 0.5;
  float d = length(p - cell) / (size * 0.5);
  return clamp(d, 0.0, 1.0);
}

// ══════════════════════════════════════════
// Diagonal line dither pattern
// ══════════════════════════════════════════
float lineDither(vec2 p, float size) {
  float d = mod(p.x + p.y, size) / size;
  return d;
}

// ══════════════════════════════════════════
// Cross-hatch dither pattern
// ══════════════════════════════════════════
float crossHatch(vec2 p, float size) {
  float d1 = mod(p.x + p.y, size) / size;
  float d2 = mod(p.x - p.y, size) / size;
  return min(d1, d2);
}

// ══════════════════════════════════════════
// Dithered quantization
// ══════════════════════════════════════════
float ditherQuantize(float val, float levels, float threshold) {
  float stepped = floor(val * levels) / levels;
  float next = stepped + 1.0 / levels;
  float frac = fract(val * levels);
  return frac > threshold ? next : stepped;
}

// ══════════════════════════════════════════
// Base gradient field — slowly morphing multi-center gradients
// ══════════════════════════════════════════
vec3 baseGradient(vec2 uv, float t) {
  // Slowly rotating coordinate system
  float angle = t * 0.05;
  mat2 rot = mat2(cos(angle), sin(angle), -sin(angle), cos(angle));
  vec2 ruv = rot * uv;

  // Multiple gradient centers drifting slowly
  vec2 c1 = vec2(0.35 * sin(t * 0.07), 0.25 * cos(t * 0.09));
  vec2 c2 = vec2(-0.3 * cos(t * 0.06 + 1.0), 0.3 * sin(t * 0.08 + 2.0));
  vec2 c3 = vec2(0.2 * sin(t * 0.11 + 3.0), -0.35 * cos(t * 0.05 + 1.5));

  // Radial distances from each center
  float d1 = length(ruv - c1);
  float d2 = length(ruv - c2);
  float d3 = length(ruv - c3);

  // Angular component for swirling
  float a1 = atan(ruv.y - c1.y, ruv.x - c1.x);
  float a2 = atan(ruv.y - c2.y, ruv.x - c2.x);

  // Combine into flowing gradient field
  float g1 = sin(d1 * 3.0 - t * 0.15 + a1 * 0.5) * 0.5 + 0.5;
  float g2 = cos(d2 * 2.5 + t * 0.12 - a2 * 0.3) * 0.5 + 0.5;
  float g3 = sin(d3 * 4.0 + t * 0.1 + d1 * 2.0) * 0.5 + 0.5;

  // FBM warp for organic feel
  float warp = fbm(ruv * 2.0 + t * 0.05) * 0.3;

  float f = g1 * 0.4 + g2 * 0.35 + g3 * 0.25 + warp;
  f = clamp(f, 0.0, 1.0);

  // Warm amber palette
  // Dark background -> deep amber -> warm gold -> bright cream
  vec3 col0 = vec3(0.04, 0.03, 0.02);  // near-black warm
  vec3 col1 = vec3(0.30, 0.15, 0.06);  // deep amber
  vec3 col2 = vec3(0.70, 0.40, 0.15);  // warm gold
  vec3 col3 = vec3(0.92, 0.75, 0.45);  // bright cream-gold

  vec3 col;
  if (f < 0.33) {
    col = mix(col0, col1, f / 0.33);
  } else if (f < 0.66) {
    col = mix(col1, col2, (f - 0.33) / 0.33);
  } else {
    col = mix(col2, col3, (f - 0.66) / 0.34);
  }

  return col;
}

// ══════════════════════════════════════════
// Main
// ══════════════════════════════════════════
void main() {
  vec2 fragCoord = gl_FragCoord.xy;
  vec2 uv = (fragCoord - u_res * 0.5) / min(u_res.x, u_res.y);
  float t = u_time;
  float ditherSc = u_ditherScale;
  float bitD = u_bitDepth;

  // ── Mouse interaction ──
  // Mouse reveals "analog truth" — smooth gradients in a radius
  float mouseReveal = 0.0;
  vec2 mouseUV = vec2(-10.0);
  if (u_mouse.x >= 0.0) {
    mouseUV = (u_mouse - u_res * 0.5) / min(u_res.x, u_res.y);
    float mouseDist = length(uv - mouseUV);
    // Smooth reveal radius
    mouseReveal = 1.0 - smoothstep(0.06, 0.18, mouseDist);
  }

  // ── Layer 1: Base gradient field ──
  vec3 smoothColor = baseGradient(uv, t);

  // ── Pixel coordinates for dither patterns ──
  // Scale by ditherScale — larger = bigger dither cells
  vec2 ditherCoord = fragCoord / ditherSc;

  // ── Layer 2 & 3: Pattern transition regions ──
  // Different areas of canvas use different dither algorithms
  // Morphing between them based on FBM noise + time
  float regionNoise = fbm(uv * 1.5 + t * 0.04);
  float regionNoise2 = fbm(uv * 2.0 - t * 0.03 + vec2(50.0));

  // Four zones that drift and blend
  float zoneBayer = smoothstep(0.3, 0.6, regionNoise);
  float zoneHalftone = smoothstep(0.4, 0.7, regionNoise2);
  float zoneLine = smoothstep(0.35, 0.65, sin(regionNoise * TAU + t * 0.2) * 0.5 + 0.5);
  float zoneCross = 1.0 - zoneBayer;

  // Normalize zone weights
  float totalWeight = zoneBayer + zoneHalftone + zoneLine + zoneCross + 0.001;
  zoneBayer /= totalWeight;
  zoneHalftone /= totalWeight;
  zoneLine /= totalWeight;
  zoneCross /= totalWeight;

  // ── Layer 4: Bit-depth wave ──
  // A traveling wavefront that changes quantization levels
  // Creates visible "resolution bands" sweeping across canvas
  float waveAngle = t * 0.08;
  vec2 waveDir = vec2(cos(waveAngle), sin(waveAngle));
  float wavePos = dot(uv, waveDir);

  // Multiple overlapping waves at different speeds/angles
  float wave1 = sin(wavePos * 4.0 - t * 0.3) * 0.5 + 0.5;
  float wave2 = sin(dot(uv, vec2(sin(t * 0.05), cos(t * 0.07))) * 6.0 + t * 0.2) * 0.5 + 0.5;
  float waveMix = wave1 * 0.6 + wave2 * 0.4;

  // Map wave to quantization levels: low bits (2-4) to high bits (16-32)
  // bitD parameter scales the whole range
  float baseLevels = mix(2.0, 32.0, waveMix) * bitD;
  baseLevels = max(baseLevels, 2.0);

  // ── Layer 5: Chromatic dither separation ──
  // R, G, B channels use slightly offset dither matrices
  vec2 offsetR = vec2(0.0, 0.0);
  vec2 offsetG = vec2(2.7, 1.3);
  vec2 offsetB = vec2(-1.5, 3.1);

  float threshR = bayer8(ditherCoord + offsetR) * zoneBayer
                + halftone(ditherCoord + offsetR, 8.0) * zoneHalftone
                + lineDither(ditherCoord + offsetR, 6.0) * zoneLine
                + crossHatch(ditherCoord + offsetR, 6.0) * zoneCross;

  float threshG = bayer8(ditherCoord + offsetG) * zoneBayer
                + halftone(ditherCoord + offsetG, 8.0) * zoneHalftone
                + lineDither(ditherCoord + offsetG, 6.0) * zoneLine
                + crossHatch(ditherCoord + offsetG, 6.0) * zoneCross;

  float threshB = bayer8(ditherCoord + offsetB) * zoneBayer
                + halftone(ditherCoord + offsetB, 8.0) * zoneHalftone
                + lineDither(ditherCoord + offsetB, 6.0) * zoneLine
                + crossHatch(ditherCoord + offsetB, 6.0) * zoneCross;

  // ── Apply dithered quantization per channel ──
  // Slightly different quantization levels per channel for color fringing
  float levelsR = baseLevels;
  float levelsG = baseLevels * 1.15;
  float levelsB = baseLevels * 0.85;

  vec3 ditheredColor;
  ditheredColor.r = ditherQuantize(smoothColor.r, levelsR, threshR);
  ditheredColor.g = ditherQuantize(smoothColor.g, levelsG, threshG);
  ditheredColor.b = ditherQuantize(smoothColor.b, levelsB, threshB);

  // ── Near the mouse: halftone circles override other patterns ──
  // Creates a distinct visual zone around cursor
  if (u_mouse.x >= 0.0) {
    float mouseD = length(uv - mouseUV);
    float ringZone = smoothstep(0.18, 0.25, mouseD) * (1.0 - smoothstep(0.25, 0.38, mouseD));
    // In the ring zone, use pure halftone with higher bit depth
    float ringHalftone = halftone(ditherCoord, 6.0);
    vec3 ringDithered;
    float ringLevels = baseLevels * 2.0;
    ringDithered.r = ditherQuantize(smoothColor.r, ringLevels, ringHalftone);
    ringDithered.g = ditherQuantize(smoothColor.g, ringLevels, ringHalftone);
    ringDithered.b = ditherQuantize(smoothColor.b, ringLevels, ringHalftone);
    ditheredColor = mix(ditheredColor, ringDithered, ringZone);
  }

  // ── Blend between dithered and smooth based on mouse reveal ──
  vec3 finalColor = mix(ditheredColor, smoothColor, mouseReveal);

  // ── Subtle edge emphasis ──
  // Emphasize transitions between bit-depth bands
  float bandEdge = abs(fract(waveMix * 4.0) - 0.5) * 2.0;
  bandEdge = smoothstep(0.85, 1.0, bandEdge);
  finalColor += vec3(0.08, 0.05, 0.02) * bandEdge * (1.0 - mouseReveal);

  // ── Vignette ──
  float vig = 1.0 - dot(uv * 0.85, uv * 0.85);
  vig = clamp(vig, 0.0, 1.0);
  vig = pow(vig, 0.4);
  finalColor *= vig;

  // ── Film grain — very subtle ──
  float grain = (hash(fragCoord + fract(t * 41.0) * 1000.0) - 0.5) * 0.02;
  finalColor += grain;

  // ── Keep blacks deep ──
  finalColor = max(finalColor, vec3(0.0));

  gl_FragColor = vec4(finalColor, 1.0);
}
